HT.CDF["G07"] = {"bang":[{"i":0,"tieu_de_bang":"Nước Mỹ – Boston và New York","tieu_de":"Nước Mỹ 1912 – 1913: đoạn đứt nét trên tấm bản đồ hành trình","sapo":"Trên tấm bản đồ hành trình tìm đường cứu nước, chặng Mỹ là một đoạn đứt nét: không rõ con tàu, không rõ ngày đến, ngày đi. Vậy mà người thanh niên hai mươi hai tuổi đã đi qua một nền cộng hòa hơn trăm tuổi và nhìn thấy cả ánh sáng lẫn bóng tối của nó. Gian nhỏ này mời bạn bước vào mùa đông năm ấy, và phân biệt thật rõ đâu là điều giấy tờ đã xác nhận, đâu là lời kể.","bia":{"src":"textures/bai/G07_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một đoạn đứt nét trên bản đồ","text":"Trên tấm bản đồ lớn vẽ hành trình tìm đường cứu nước, những đường kẻ liền nét nối bến Nhà Rồng với Marseille, với Le Havre, rồi tới nhiều hải cảng châu Phi. Đến giữa Đại Tây Dương, nét vẽ bỗng đứt quãng. Đó là chặng Mỹ, những năm 1912 – 1913. Không ai biết chắc người thanh niên Nguyễn Tất Thành đi con tàu nào, cập bến ngày nào, rời đi lúc nào. Thứ còn lại trên giấy chỉ là một lá thư đề ngày 15/12/1912, đóng dấu bưu điện New York, cùng vài điều Người nhắc lại về sau.\n\nVậy mà chặng đường đứt nét ấy lại dẫn tới một trong những câu văn nổi tiếng nhất của lịch sử Việt Nam hiện đại. Ba mươi ba năm sau mùa đông ở Boston và New York, bản Tuyên ngôn Độc lập của nước Việt Nam Dân chủ Cộng hòa mở đầu bằng lời trích Tuyên ngôn Độc lập Hoa Kỳ năm 1776. Gian trưng bày này nhỏ, vì tư liệu ít ỏi. Nhưng nó đặt ra một câu hỏi lớn: người thợ phụ vô danh năm ấy đã nhìn thấy gì ở nước Mỹ, và những điều đó theo Người đi xa đến đâu?","doc":1},{"loai":"doan","tieu_de":"Người phụ bếp tên Văn Ba","text":"Ngày 5/6/1911, Nguyễn Tất Thành rời bến Nhà Rồng trên tàu Amiral Latouche-Tréville, nhận chân phụ bếp với cái tên Văn Ba. Ngày 6/7/1911, tàu cập cảng Marseille. Từ đó, suốt hơn một năm, cuộc sống của người thanh niên hai mươi mốt tuổi gắn với những con tàu và những bến cảng: Le Havre bên bờ biển Manche, rồi nhiều hải cảng ở châu Phi. Người làm việc bằng đôi tay để đổi lấy mỗi hải trình, và ở mỗi nơi dừng chân lại thấy thêm một cảnh đời của người lao động, ở chính quốc cũng như ở thuộc địa.\n\nChuyến đi ấy có một mục đích rõ ràng. Người không ra đi để lập nghiệp hay làm giàu, mà để xem các nước phương Tây làm thế nào, rồi trở về giúp đồng bào. Năm 1923, trả lời phỏng vấn nhà thơ Nga Osip Mandelstam, Nguyễn Ái Quốc kể rằng vào khoảng mười ba tuổi, lần đầu Người được nghe ba chữ Pháp: Tự do, Bình đẳng, Bác ái. Từ thuở ấy, Người muốn tìm xem những gì ẩn sau ba chữ đó. Nước Mỹ, một nền cộng hòa khác bên kia đại dương, là nơi để tiếp tục đi tìm câu trả lời.","doc":2},{"loai":"trich","text":"Tôi muốn đi ra ngoài, xem nước Pháp và các nước khác. Sau khi xem xét họ làm như thế nào, tôi sẽ trở về giúp đồng bào chúng ta.","nguoi":"Nguyễn Tất Thành, nói với một người bạn trước lúc ra đi (theo Trần Dân Tiên)","nguon_ten":"Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","doc":3},{"loai":"doan","tieu_de":"Nước Mỹ năm 1912","text":"Nước Mỹ mà Người đặt chân tới cuối năm 1912 là một cường quốc đang lớn rất nhanh. Cuộc tổng điều tra dân số năm 1910 ghi nhận hơn 92 triệu người, trong đó gần 15% sinh ra ở nước ngoài. Riêng thành phố New York có gần 4,8 triệu dân, còn Boston khoảng 670 nghìn. Đầu năm 1912, New Mexico và Arizona vừa gia nhập liên bang, nâng số bang lên 48. Tháng 4 năm ấy, tàu Titanic chìm trên đường tới New York, khiến cả hai bờ Đại Tây Dương bàng hoàng.\n\nMùa thu 1912 cũng là một mùa bầu cử tổng thống sôi động bậc nhất. Bốn ứng cử viên cùng tranh cử: Woodrow Wilson của Đảng Dân chủ, Tổng thống đương nhiệm William Taft, cựu Tổng thống Theodore Roosevelt và lãnh tụ xã hội chủ nghĩa Eugene Debs. Ngày 5/11/1912, Wilson thắng cử. Debs chỉ được khoảng 6% số phiếu, nhưng đó là hơn 900 nghìn lá phiếu của những người lao động mong đổi thay. Khoảng sáu tuần sau ngày bầu cử, lá thư của Nguyễn Tất Thành đã mang dấu bưu điện New York.","doc":4},{"loai":"anh","src":"textures/bang_w/G07_0_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nước Mỹ – Boston và New York”, nhìn từ xa."},{"loai":"doan","tieu_de":"Những người làm thuê từ khắp thế giới","text":"Nước Mỹ năm ấy được dựng lên bằng bàn tay của người nhập cư. Từ năm 1892, trạm di trú trên đảo Ellis ở cửa cảng New York đón những đoàn người từ Ireland, Italia, Ba Lan, Nga và nhiều miền khác của châu Âu; riêng năm kỷ lục 1907 có hơn một triệu người qua đây. Họ làm việc trong nhà máy, bến cảng, công trường, khách sạn, thường với đồng lương thấp và giờ làm dài.\n\nTháng 1/1912, ở thị trấn dệt Lawrence, cách Boston chừng bốn mươi cây số, hơn hai vạn công nhân thuộc hàng chục dân tộc đã bãi công phản đối việc cắt lương. Cuộc đấu tranh kéo dài khoảng hai tháng, về sau thường được gọi là cuộc bãi công “Bánh mì và hoa hồng”. Với người châu Á, cánh cửa còn hẹp hơn nhiều: luật pháp Mỹ khi ấy ngăn chặn gắt gao người lao động Trung Hoa nhập cư. Một thủy thủ đến từ xứ An Nam thuộc Pháp như Nguyễn Tất Thành hẳn là một gương mặt hiếm gặp, sống lẫn trong thế giới của những người làm thuê từ khắp nơi đổ về.","doc":5},{"loai":"ban_co_biet","text":"Khi Người đến Mỹ, Đạo luật Loại trừ người Hoa ký năm 1882 vẫn còn hiệu lực. Đó là đạo luật lớn đầu tiên của Mỹ ngăn người lao động thuộc một dân tộc cụ thể nhập cư, và phải đến năm 1943 mới bị bãi bỏ.","nguon_ten":"Cục Lưu trữ Quốc gia Hoa Kỳ (National Archives), hồ sơ Đạo luật Loại trừ người Hoa năm 1882","doc":6},{"loai":"doan","tieu_de":"Boston: phố School và gian bếp bánh","text":"Boston là thành phố của những ký ức cách mạng Mỹ. Chính ở đây đã diễn ra sự kiện Tiệc trà Boston năm 1773, mở màn cho cuộc đấu tranh của mười ba thuộc địa Bắc Mỹ chống lại nước Anh (xem chuyên đề Nhà thờ King’s Chapel). Theo những gì Người kể lại về sau và theo thư từ gửi cụ Phan Châu Trinh, khi ấy đang sống ở Paris, Nguyễn Tất Thành từng làm phụ bếp bánh ở khách sạn Parker House trên phố School, ngay trung tâm thành phố.\n\nMùa đông Boston lạnh buốt, tuyết phủ kín mặt đường. Công việc của người thợ phụ trong một bếp bánh thời ấy thường bắt đầu từ rất sớm: khuân bột, nhồi bột, canh lò, rửa khay. Hồ sơ nhân sự còn lại của khách sạn không lưu tên Người, nên câu chuyện này vẫn được trình bày là lời kể, chưa phải sự kiện có văn bản độc lập xác nhận. Dù vậy, nó ăn khớp với cả chặng đường dài: ở đâu, Người cũng sống bằng lao động chân tay của chính mình (xem chuyên đề Khách sạn Parker House và chuyên đề Gian bếp bánh).","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_omni_parker_house_school_st_boston_493545_110616.jpg","chu_thich":"Khách sạn Parker House trên phố School, Boston (ảnh chụp năm 2013) — nơi theo lời kể, Người từng làm phụ bếp bánh mùa đông 1912 – 1913.","credit":"Ảnh: Robert Linsdell from St. Andrews, Canada · CC BY 2.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"New York: lá thư và khu Harlem","text":"Nếu Boston được biết qua lời kể, thì New York để lại một dấu vết bằng giấy. Lá thư đề ngày 15/12/1912, đóng dấu bưu điện thành phố này và gửi các quan chức thuộc địa Pháp, là bằng chứng gần như duy nhất xác nhận Người có mặt trên đất Mỹ. Trong thư, Người khai nghề nghiệp là thủy thủ và ghi địa chỉ liên lạc là thư lưu tại bưu điện Le Havre (xem chuyên đề Lá thư đóng dấu bưu điện New York).\n\nCũng ở New York, theo lời kể của chính Người và các tư liệu sau này, Người đi xem khu Harlem, nơi cộng đồng người Mỹ gốc Phi đang tụ hội ngày một đông. Người dự các buổi diễn thuyết và chứng kiến cảnh phân biệt chủng tộc. Một số nhà viết tiểu sử còn cho rằng Người có thể đã sống một thời gian ở Harlem. Những điều đã chứng kiến ấy, hơn mười năm sau, trở thành chất liệu cho các bài báo tố cáo tội ác hành hình người da đen (xem chuyên đề Từ Harlem đến bài báo “Hành hình kiểu Linsơ”).","doc":8},{"loai":"doan","tieu_de":"Tách bạch sự thật và lời kể","text":"Vì tư liệu ít, gian trưng bày này được xây dựng theo một nguyên tắc: nói rõ nguồn gốc của từng chi tiết. Có thể chia những gì ta biết về chặng Mỹ thành ba lớp. Lớp thứ nhất là văn bản đương thời, tiêu biểu là lá thư đóng dấu New York. Lớp thứ hai là những điều chính Người nhắc lại về sau, như trong thư từ gửi cụ Phan Châu Trinh. Lớp thứ ba là hồi ức được ghi thành sách, như cuốn Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch của Trần Dân Tiên, cùng những suy đoán của các nhà viết tiểu sử.\n\nCác nhà nghiên cứu nghiêm túc, trong nước cũng như nước ngoài, chẳng hạn William J. Duiker, tác giả cuốn Ho Chi Minh: A Life, đều dùng những chữ thận trọng như “theo lời kể”, “có thể”. Đó không phải là sự nghi ngờ, mà là thái độ tôn trọng sự thật lịch sử. Ở bảo tàng này, điều gì đã có văn bản xác nhận thì được nói là sự thật; điều gì chỉ đến từ lời kể thì được ghi rõ là lời kể. Khách tham quan sẽ gặp lại nguyên tắc ấy ở mọi bảng trong gian.","doc":9},{"loai":"anh","src":"textures/bang_w/G07_0_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nước Mỹ – Boston và New York”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Đi qua gian trưng bày","text":"Gian nước Mỹ được dựng như một góc phố Boston mùa đông đầu thế kỷ XX. Bước qua bảng giới thiệu này, khách tham quan gặp gian bếp bánh với lò gạch, bàn nhồi bột và âu gỗ trộn bột. Đó là những đồ vật minh họa, phục dựng theo hình dung chung về một bếp bánh thời ấy, chứ không phải bản sao của một căn bếp có thật. Hai tấm ảnh tư liệu cho thấy khách sạn Parker House trên phố School ngày nay, trong tòa nhà đã được xây lại từ năm 1927.\n\nXa hơn là nhà thờ đá King’s Chapel ở góc phố Tremont, một trong những công trình cổ nhất Boston, rồi góc New York – Harlem với câu chuyện về thành phố lớn nhất nước Mỹ. Bảng “Lời Bác” đặt câu mở đầu Tuyên ngôn Độc lập năm 1945 bên cạnh lời Tuyên ngôn Mỹ năm 1776. Bảng mốc thời gian nối tất cả lại, từ bến Nhà Rồng đến Quảng trường Ba Đình. Mỗi bảng, mỗi đồ vật đều có một chuyên đề riêng để bạn đọc sâu hơn.","doc":10},{"loai":"ban_co_biet","text":"Bài phỏng vấn trong đó Nguyễn Ái Quốc kể về ba chữ Tự do, Bình đẳng, Bác ái do nhà thơ Nga Osip Mandelstam thực hiện, đăng trên tạp chí Ogoniok số 39, ngày 23/12/1923, khi Người vừa đến Liên Xô được ít tháng.","nguon_ten":"Tạp chí Ogoniok (Liên Xô), số 39, 23/12/1923; Bảo tàng Hồ Chí Minh","doc":11},{"loai":"anh","src":"textures/bang_w/G07_0_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nước Mỹ – Boston và New York”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Những gì nước Mỹ để lại","text":"Chặng Mỹ ngắn, nhưng dấu ấn của nó còn hiện ra nhiều lần trong cuộc đời Người. Tháng 1/1918, Tổng thống Wilson, người đắc cử đúng năm Người đến Mỹ, đưa ra chương trình mười bốn điểm với những lời hứa hẹn về quyền của các dân tộc. Tháng 6/1919, Nguyễn Ái Quốc gửi bản Yêu sách của nhân dân An Nam tới các phái đoàn dự Hội nghị Versailles, trong đó có phái đoàn Mỹ. Bản Yêu sách chỉ đòi những quyền tự do, dân chủ tối thiểu, nhưng không được đáp ứng.\n\nNăm 1924, Người viết những bài báo đanh thép về nạn hành hình người da đen và tổ chức Ku Klux Klan. Năm 1945, Người mở đầu Tuyên ngôn Độc lập bằng lời Tuyên ngôn Mỹ năm 1776, rồi “suy rộng ra” thành quyền của mọi dân tộc (xem chuyên đề Lời Bác). Từ cuối năm 1945 đến năm 1946, Chủ tịch Hồ Chí Minh nhiều lần gửi thư, điện tới Tổng thống Mỹ Harry Truman, đề nghị ủng hộ nền độc lập của Việt Nam, nhưng không nhận được hồi âm. Người trân trọng lý tưởng của nước Mỹ, nhưng chưa bao giờ quên khoảng cách giữa lời tuyên bố và thực tế.","doc":12},{"loai":"ban_co_biet","text":"Bản Yêu sách của nhân dân An Nam năm 1919 cũng được gửi tới phái đoàn Mỹ tại Hội nghị Hòa bình Paris. Một bản kèm thư ký tên Nguyễn Ái Quốc gửi Ngoại trưởng Robert Lansing hiện vẫn được lưu tại Cục Lưu trữ Quốc gia Hoa Kỳ.","nguon_ten":"Cục Lưu trữ Quốc gia Hoa Kỳ (National Archives), hồ sơ phái đoàn Mỹ tại Hội nghị Hòa bình Paris 1919","doc":13},{"loai":"anh","src":"textures/ht/ht_anh_omni_parker_house_54957839082.jpg","chu_thich":"Mặt tiền khách sạn Parker House ngày nay (ảnh chụp năm 2025); tòa nhà hiện tại phần lớn được xây dựng lại từ năm 1927.","credit":"Ảnh: ajay_suresh · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hơn một thế kỷ đã trôi qua, nhưng nhiều địa điểm của chặng Mỹ vẫn còn. Khách sạn Parker House, nay mang tên Omni Parker House, vẫn đón khách ở số 60 phố School, dù tòa nhà đã được xây lại. Ngay góc phố Tremont gần đó là nhà thờ King’s Chapel, gần như vẹn nguyên từ giữa thế kỷ XVIII. Cả hai nằm bên tuyến đi bộ Con đường Tự do, nối các di tích thời cách mạng Mỹ. Khu Harlem ở phía bắc đảo Manhattan ngày nay vẫn là trung tâm văn hóa của người Mỹ gốc Phi.\n\nỞ Việt Nam, câu chuyện được tiếp nối tại Bảo tàng Hồ Chí Minh ở Hà Nội, nơi lưu giữ nhiều tư liệu về những năm tìm đường cứu nước, trong đó có một bản in bài báo “Hành hình kiểu Linsơ” năm 1924. Bến Nhà Rồng, nơi con tàu Amiral Latouche-Tréville nhổ neo năm 1911, nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. Đứng ở một trong hai nơi ấy, người xem có thể hình dung trọn đoạn đường mà tấm bản đồ chỉ vẽ được bằng nét đứt.","doc":14}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","William J. Duiker, Ho Chi Minh: A Life (2000)","Cục Điều tra Dân số Hoa Kỳ (U.S. Census Bureau), Tổng điều tra dân số năm 1910","Cục Lưu trữ Quốc gia Hoa Kỳ (National Archives): Đạo luật Loại trừ người Hoa 1882; hồ sơ phái đoàn Mỹ tại Hội nghị Hòa bình Paris 1919","Bảo tàng Hồ Chí Minh (Hà Nội) và Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh (Bến Nhà Rồng)"],"doc":[{"t":"Nước Mỹ 1912 – 1913: đoạn đứt nét trên tấm bản đồ hành trình. Trên tấm bản đồ hành trình tìm đường cứu nước, chặng Mỹ là một đoạn đứt nét: không rõ con tàu, không rõ ngày đến, ngày đi. Vậy mà người thanh niên hai mươi hai tuổi đã đi qua một nền cộng hòa hơn trăm tuổi và nhìn thấy cả ánh sáng lẫn bóng tối của nó. Gian nhỏ này mời bạn bước vào mùa đông năm ấy, và phân biệt thật rõ đâu là điều giấy tờ đã xác nhận, đâu là lời kể."},{"t":"Một đoạn đứt nét trên bản đồ. Trên tấm bản đồ lớn vẽ hành trình tìm đường cứu nước, những đường kẻ liền nét nối bến Nhà Rồng với Marseille, với Le Havre, rồi tới nhiều hải cảng châu Phi. Đến giữa Đại Tây Dương, nét vẽ bỗng đứt quãng. Đó là chặng Mỹ, những năm 1912 – 1913. Không ai biết chắc người thanh niên Nguyễn Tất Thành đi con tàu nào, cập bến ngày nào, rời đi lúc nào. Thứ còn lại trên giấy chỉ là một lá thư đề ngày 15/12/1912, đóng dấu bưu điện New York, cùng vài điều Người nhắc lại về sau. Vậy mà chặng đường đứt nét ấy lại dẫn tới một trong những câu văn nổi tiếng nhất của lịch sử Việt Nam hiện đại. Ba mươi ba năm sau mùa đông ở Boston và New York, bản Tuyên ngôn Độc lập của nước Việt Nam Dân chủ Cộng hòa mở đầu bằng lời trích Tuyên ngôn Độc lập Hoa Kỳ năm 1776. Gian trưng bày này nhỏ, vì tư liệu ít ỏi. Nhưng nó đặt ra một câu hỏi lớn: người thợ phụ vô danh năm ấy đã nhìn thấy gì ở nước Mỹ, và những điều đó theo Người đi xa đến đâu?"},{"t":"Người phụ bếp tên Văn Ba. Ngày 5/6/1911, Nguyễn Tất Thành rời bến Nhà Rồng trên tàu Amiral Latouche-Tréville, nhận chân phụ bếp với cái tên Văn Ba. Ngày 6/7/1911, tàu cập cảng Marseille. Từ đó, suốt hơn một năm, cuộc sống của người thanh niên hai mươi mốt tuổi gắn với những con tàu và những bến cảng: Le Havre bên bờ biển Manche, rồi nhiều hải cảng ở châu Phi. Người làm việc bằng đôi tay để đổi lấy mỗi hải trình, và ở mỗi nơi dừng chân lại thấy thêm một cảnh đời của người lao động, ở chính quốc cũng như ở thuộc địa. Chuyến đi ấy có một mục đích rõ ràng. Người không ra đi để lập nghiệp hay làm giàu, mà để xem các nước phương Tây làm thế nào, rồi trở về giúp đồng bào. Năm 1923, trả lời phỏng vấn nhà thơ Nga Osip Mandelstam, Nguyễn Ái Quốc kể rằng vào khoảng mười ba tuổi, lần đầu Người được nghe ba chữ Pháp: Tự do, Bình đẳng, Bác ái. Từ thuở ấy, Người muốn tìm xem những gì ẩn sau ba chữ đó. Nước Mỹ, một nền cộng hòa khác bên kia đại dương, là nơi để tiếp tục đi tìm câu trả lời."},{"t":"Tôi muốn đi ra ngoài, xem nước Pháp và các nước khác. Sau khi xem xét họ làm như thế nào, tôi sẽ trở về giúp đồng bào chúng ta. — Nguyễn Tất Thành, nói với một người bạn trước lúc ra đi (theo Trần Dân Tiên)"},{"t":"Nước Mỹ năm 1912. Nước Mỹ mà Người đặt chân tới cuối năm 1912 là một cường quốc đang lớn rất nhanh. Cuộc tổng điều tra dân số năm 1910 ghi nhận hơn 92 triệu người, trong đó gần 15% sinh ra ở nước ngoài. Riêng thành phố New York có gần 4,8 triệu dân, còn Boston khoảng 670 nghìn. Đầu năm 1912, New Mexico và Arizona vừa gia nhập liên bang, nâng số bang lên 48. Tháng 4 năm ấy, tàu Titanic chìm trên đường tới New York, khiến cả hai bờ Đại Tây Dương bàng hoàng. Mùa thu 1912 cũng là một mùa bầu cử tổng thống sôi động bậc nhất. Bốn ứng cử viên cùng tranh cử: Woodrow Wilson của Đảng Dân chủ, Tổng thống đương nhiệm William Taft, cựu Tổng thống Theodore Roosevelt và lãnh tụ xã hội chủ nghĩa Eugene Debs. Ngày 5/11/1912, Wilson thắng cử. Debs chỉ được khoảng 6% số phiếu, nhưng đó là hơn 900 nghìn lá phiếu của những người lao động mong đổi thay. Khoảng sáu tuần sau ngày bầu cử, lá thư của Nguyễn Tất Thành đã mang dấu bưu điện New York."},{"t":"Những người làm thuê từ khắp thế giới. Nước Mỹ năm ấy được dựng lên bằng bàn tay của người nhập cư. Từ năm 1892, trạm di trú trên đảo Ellis ở cửa cảng New York đón những đoàn người từ Ireland, Italia, Ba Lan, Nga và nhiều miền khác của châu Âu; riêng năm kỷ lục 1907 có hơn một triệu người qua đây. Họ làm việc trong nhà máy, bến cảng, công trường, khách sạn, thường với đồng lương thấp và giờ làm dài. Tháng 1/1912, ở thị trấn dệt Lawrence, cách Boston chừng bốn mươi cây số, hơn hai vạn công nhân thuộc hàng chục dân tộc đã bãi công phản đối việc cắt lương. Cuộc đấu tranh kéo dài khoảng hai tháng, về sau thường được gọi là cuộc bãi công “Bánh mì và hoa hồng”. Với người châu Á, cánh cửa còn hẹp hơn nhiều: luật pháp Mỹ khi ấy ngăn chặn gắt gao người lao động Trung Hoa nhập cư. Một thủy thủ đến từ xứ An Nam thuộc Pháp như Nguyễn Tất Thành hẳn là một gương mặt hiếm gặp, sống lẫn trong thế giới của những người làm thuê từ khắp nơi đổ về."},{"t":"Bạn có biết? Khi Người đến Mỹ, Đạo luật Loại trừ người Hoa ký năm 1882 vẫn còn hiệu lực. Đó là đạo luật lớn đầu tiên của Mỹ ngăn người lao động thuộc một dân tộc cụ thể nhập cư, và phải đến năm 1943 mới bị bãi bỏ."},{"t":"Boston: phố School và gian bếp bánh. Boston là thành phố của những ký ức cách mạng Mỹ. Chính ở đây đã diễn ra sự kiện Tiệc trà Boston năm 1773, mở màn cho cuộc đấu tranh của mười ba thuộc địa Bắc Mỹ chống lại nước Anh (xem chuyên đề Nhà thờ King’s Chapel). Theo những gì Người kể lại về sau và theo thư từ gửi cụ Phan Châu Trinh, khi ấy đang sống ở Paris, Nguyễn Tất Thành từng làm phụ bếp bánh ở khách sạn Parker House trên phố School, ngay trung tâm thành phố. Mùa đông Boston lạnh buốt, tuyết phủ kín mặt đường. Công việc của người thợ phụ trong một bếp bánh thời ấy thường bắt đầu từ rất sớm: khuân bột, nhồi bột, canh lò, rửa khay. Hồ sơ nhân sự còn lại của khách sạn không lưu tên Người, nên câu chuyện này vẫn được trình bày là lời kể, chưa phải sự kiện có văn bản độc lập xác nhận. Dù vậy, nó ăn khớp với cả chặng đường dài: ở đâu, Người cũng sống bằng lao động chân tay của chính mình (xem chuyên đề Khách sạn Parker House và chuyên đề Gian bếp bánh)."},{"t":"New York: lá thư và khu Harlem. Nếu Boston được biết qua lời kể, thì New York để lại một dấu vết bằng giấy. Lá thư đề ngày 15/12/1912, đóng dấu bưu điện thành phố này và gửi các quan chức thuộc địa Pháp, là bằng chứng gần như duy nhất xác nhận Người có mặt trên đất Mỹ. Trong thư, Người khai nghề nghiệp là thủy thủ và ghi địa chỉ liên lạc là thư lưu tại bưu điện Le Havre (xem chuyên đề Lá thư đóng dấu bưu điện New York). Cũng ở New York, theo lời kể của chính Người và các tư liệu sau này, Người đi xem khu Harlem, nơi cộng đồng người Mỹ gốc Phi đang tụ hội ngày một đông. Người dự các buổi diễn thuyết và chứng kiến cảnh phân biệt chủng tộc. Một số nhà viết tiểu sử còn cho rằng Người có thể đã sống một thời gian ở Harlem. Những điều đã chứng kiến ấy, hơn mười năm sau, trở thành chất liệu cho các bài báo tố cáo tội ác hành hình người da đen (xem chuyên đề Từ Harlem đến bài báo “Hành hình kiểu Linsơ”)."},{"t":"Tách bạch sự thật và lời kể. Vì tư liệu ít, gian trưng bày này được xây dựng theo một nguyên tắc: nói rõ nguồn gốc của từng chi tiết. Có thể chia những gì ta biết về chặng Mỹ thành ba lớp. Lớp thứ nhất là văn bản đương thời, tiêu biểu là lá thư đóng dấu New York. Lớp thứ hai là những điều chính Người nhắc lại về sau, như trong thư từ gửi cụ Phan Châu Trinh. Lớp thứ ba là hồi ức được ghi thành sách, như cuốn Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch của Trần Dân Tiên, cùng những suy đoán của các nhà viết tiểu sử. Các nhà nghiên cứu nghiêm túc, trong nước cũng như nước ngoài, chẳng hạn William J. Duiker, tác giả cuốn Ho Chi Minh: A Life, đều dùng những chữ thận trọng như “theo lời kể”, “có thể”. Đó không phải là sự nghi ngờ, mà là thái độ tôn trọng sự thật lịch sử. Ở bảo tàng này, điều gì đã có văn bản xác nhận thì được nói là sự thật; điều gì chỉ đến từ lời kể thì được ghi rõ là lời kể. Khách tham quan sẽ gặp lại nguyên tắc ấy ở mọi bảng trong gian."},{"t":"Đi qua gian trưng bày. Gian nước Mỹ được dựng như một góc phố Boston mùa đông đầu thế kỷ XX. Bước qua bảng giới thiệu này, khách tham quan gặp gian bếp bánh với lò gạch, bàn nhồi bột và âu gỗ trộn bột. Đó là những đồ vật minh họa, phục dựng theo hình dung chung về một bếp bánh thời ấy, chứ không phải bản sao của một căn bếp có thật. Hai tấm ảnh tư liệu cho thấy khách sạn Parker House trên phố School ngày nay, trong tòa nhà đã được xây lại từ năm 1927. Xa hơn là nhà thờ đá King’s Chapel ở góc phố Tremont, một trong những công trình cổ nhất Boston, rồi góc New York – Harlem với câu chuyện về thành phố lớn nhất nước Mỹ. Bảng “Lời Bác” đặt câu mở đầu Tuyên ngôn Độc lập năm 1945 bên cạnh lời Tuyên ngôn Mỹ năm 1776. Bảng mốc thời gian nối tất cả lại, từ bến Nhà Rồng đến Quảng trường Ba Đình. Mỗi bảng, mỗi đồ vật đều có một chuyên đề riêng để bạn đọc sâu hơn."},{"t":"Bạn có biết? Bài phỏng vấn trong đó Nguyễn Ái Quốc kể về ba chữ Tự do, Bình đẳng, Bác ái do nhà thơ Nga Osip Mandelstam thực hiện, đăng trên tạp chí Ogoniok số 39, ngày 23/12/1923, khi Người vừa đến Liên Xô được ít tháng."},{"t":"Những gì nước Mỹ để lại. Chặng Mỹ ngắn, nhưng dấu ấn của nó còn hiện ra nhiều lần trong cuộc đời Người. Tháng 1/1918, Tổng thống Wilson, người đắc cử đúng năm Người đến Mỹ, đưa ra chương trình mười bốn điểm với những lời hứa hẹn về quyền của các dân tộc. Tháng 6/1919, Nguyễn Ái Quốc gửi bản Yêu sách của nhân dân An Nam tới các phái đoàn dự Hội nghị Versailles, trong đó có phái đoàn Mỹ. Bản Yêu sách chỉ đòi những quyền tự do, dân chủ tối thiểu, nhưng không được đáp ứng. Năm 1924, Người viết những bài báo đanh thép về nạn hành hình người da đen và tổ chức Ku Klux Klan. Năm 1945, Người mở đầu Tuyên ngôn Độc lập bằng lời Tuyên ngôn Mỹ năm 1776, rồi “suy rộng ra” thành quyền của mọi dân tộc (xem chuyên đề Lời Bác). Từ cuối năm 1945 đến năm 1946, Chủ tịch Hồ Chí Minh nhiều lần gửi thư, điện tới Tổng thống Mỹ Harry Truman, đề nghị ủng hộ nền độc lập của Việt Nam, nhưng không nhận được hồi âm. Người trân trọng lý tưởng của nước Mỹ, nhưng chưa bao giờ quên khoảng cách giữa lời tuyên bố và thực tế."},{"t":"Bạn có biết? Bản Yêu sách của nhân dân An Nam năm 1919 cũng được gửi tới phái đoàn Mỹ tại Hội nghị Hòa bình Paris. Một bản kèm thư ký tên Nguyễn Ái Quốc gửi Ngoại trưởng Robert Lansing hiện vẫn được lưu tại Cục Lưu trữ Quốc gia Hoa Kỳ."},{"t":"Dấu tích hôm nay. Hơn một thế kỷ đã trôi qua, nhưng nhiều địa điểm của chặng Mỹ vẫn còn. Khách sạn Parker House, nay mang tên Omni Parker House, vẫn đón khách ở số 60 phố School, dù tòa nhà đã được xây lại. Ngay góc phố Tremont gần đó là nhà thờ King’s Chapel, gần như vẹn nguyên từ giữa thế kỷ XVIII. Cả hai nằm bên tuyến đi bộ Con đường Tự do, nối các di tích thời cách mạng Mỹ. Khu Harlem ở phía bắc đảo Manhattan ngày nay vẫn là trung tâm văn hóa của người Mỹ gốc Phi. Ở Việt Nam, câu chuyện được tiếp nối tại Bảo tàng Hồ Chí Minh ở Hà Nội, nơi lưu giữ nhiều tư liệu về những năm tìm đường cứu nước, trong đó có một bản in bài báo “Hành hình kiểu Linsơ” năm 1924. Bến Nhà Rồng, nơi con tàu Amiral Latouche-Tréville nhổ neo năm 1911, nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. Đứng ở một trong hai nơi ấy, người xem có thể hình dung trọn đoạn đường mà tấm bản đồ chỉ vẽ được bằng nét đứt."}],"so_chu":2245},{"i":1,"tieu_de_bang":"Lá thư đóng dấu bưu điện New York","tieu_de":"Ngày 15/12/1912: lá thư đóng dấu New York và nghịch lý của kho hồ sơ theo dõi","sapo":"Không có tấm ảnh hay trang nhật ký nào ghi lại những ngày Người ở Mỹ. Thứ còn lại trên giấy là một lá thư ngắn đề ngày 15/12/1912, mang dấu bưu điện New York. Nghịch lý thay, nó được giữ lại nhờ chính bộ máy thuộc địa vốn muốn theo dõi người viết. Đọc kỹ từng dòng khai báo, ta thấy hiện lên chân dung một người thủy thủ trẻ không nhà cửa mà không lạc hướng.","bia":{"src":"textures/bai/G07_v2.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một lá thư từ bên kia đại dương","text":"Tháng 12/1912, New York bước vào mùa đông. Gió từ sông Hudson thổi lạnh buốt qua những bến cảng dọc Manhattan, nơi tàu bè từ khắp thế giới ra vào tấp nập. Ngày 15/12/1912, một thanh niên Việt Nam hai mươi hai tuổi viết thư gửi các quan chức thuộc địa Pháp. Lá thư được đóng dấu bưu điện New York rồi bắt đầu hành trình vượt Đại Tây Dương.\n\nTrong thư, người viết khai nghề nghiệp của mình là thủy thủ. Địa chỉ liên lạc được ghi là “poste restante”, tức thư lưu tại bưu điện, ở thành phố cảng Le Havre bên bờ biển nước Pháp. Người viết lá thư ấy là Nguyễn Tất Thành. Lá thư được vào sổ, xếp vào hồ sơ, rồi nằm yên ở đó. Hơn một thế kỷ sau, nó là bằng chứng giấy tờ gần như duy nhất xác nhận rằng người thanh niên ấy thực sự có mặt trên đất Mỹ trong mùa đông năm 1912. Mọi câu chuyện khác về chặng Mỹ đều phải bắt đầu từ mấy dòng khai báo ngắn ngủi này.","doc":1},{"loai":"doan","tieu_de":"Người viết thư là ai trong mắt nhà cầm quyền","text":"Với chính quyền thuộc địa, cái tên Nguyễn Tất Thành không hoàn toàn xa lạ. Người là con trai cụ Nguyễn Sinh Sắc, đỗ Phó bảng năm 1901, từng làm quan ở Bộ Lễ tại Huế rồi được bổ làm Tri huyện Bình Khê, tỉnh Bình Định. Năm 1910, cụ Sắc bị cách chức. Bản thân người con cũng đã sớm lọt vào tầm mắt của nhà cầm quyền: năm 1908, khi đang học ở Trường Quốc học Huế, Nguyễn Tất Thành tham gia phong trào nông dân chống thuế ở Trung Kỳ.\n\nSau đó, Người rời Huế vào phía Nam, dạy học ở Trường Dục Thanh, Phan Thiết, rồi vào Sài Gòn đầu năm 1911 và xuống tàu ra đi với tên Văn Ba. Một thanh niên có lý lịch như thế, lại xuất dương, là người mà bộ máy thuộc địa muốn biết đang ở đâu, làm gì. Điều đáng chú ý là trong những thư từ gửi chính quyền các năm 1911 – 1912, Người vẫn ký chính tên thật của mình. Người thủy thủ trẻ không lẩn tránh; Người trực tiếp viết cho bộ máy cai trị, bằng chính tên mình, từ những nơi xa xôi nhất.","doc":2},{"loai":"doan","tieu_de":"Lá đơn gửi từ Marseille","text":"Lá thư New York không phải là lần đầu người thanh niên ấy viết cho chính quyền Pháp. Ngày 15/9/1911, từ Marseille, Người gửi đơn lên Tổng thống Cộng hòa Pháp, xin được vào học Trường Thuộc địa. Ngôi trường ở Paris này, thành lập năm 1889, là nơi đào tạo viên chức cho bộ máy cai trị các xứ thuộc địa. Trong đơn, người viết tự giới thiệu là con trai ông Nguyễn Sinh Huy, tức cụ Nguyễn Sinh Sắc, một vị Phó bảng, và cho biết mình đang làm việc trên tàu Amiral Latouche-Tréville để kiếm sống.\n\nLá đơn bị từ chối. Nhưng cũng như lá thư New York sau này, nó được lưu giữ trong hồ sơ của chính quyền. Đặt hai văn bản cạnh nhau, ta thấy một người thanh niên muốn hiểu bộ máy thuộc địa từ bên trong: xin vào học chính ngôi trường đào tạo những người cai trị đất nước mình, rồi khi không được, lại lên đường đi tiếp. Mười lăm tháng ngăn cách hai lá thư, và trong mười lăm tháng ấy, người viết đã đi từ bến cảng Marseille tới thành phố New York.","doc":3},{"loai":"ban_co_biet","text":"Trong lá đơn gửi Tổng thống Pháp ngày 15/9/1911, người viết ghi mình sinh ở Vinh năm 1892, trong khi Người sinh năm 1890 tại quê ngoại, làng Hoàng Trù. Những chênh lệch như vậy là lý do các nhà nghiên cứu phải đối chiếu thật kỹ từng văn bản thời kỳ này.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","doc":4},{"loai":"anh","src":"textures/bang_w/G07_1_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lá thư đóng dấu bưu điện New York”, nhìn từ xa."},{"loai":"doan","tieu_de":"“Poste restante”: địa chỉ của người không nhà","text":"Chi tiết đáng chú ý nhất trong lá thư New York có lẽ là địa chỉ liên lạc. “Poste restante”, dịch sát là “thư lưu lại”, là dịch vụ bưu điện dành cho những người không có chỗ ở cố định. Thư gửi tới được giữ tại quầy bưu điện của thành phố ghi trên phong bì, cho đến khi người nhận tự đến, trình giấy tờ và lấy về. Đầu thế kỷ XX, đây là cách liên lạc quen thuộc của thủy thủ, người buôn bán, khách lữ hành, những người hôm nay ở cảng này, tháng sau đã ở cảng khác.\n\nViệc chọn Le Havre cũng có lý do. Đây là một trong những hải cảng lớn nhất nước Pháp, nằm ở cửa sông Seine, nơi con tàu Amiral Latouche-Tréville từng ghé trong chuyến đi năm 1911. Le Havre còn là đầu mối của tuyến tàu khách thường xuyên sang New York. Ghi địa chỉ ở Le Havre cho thấy Người vẫn coi các bến cảng nước Pháp là nơi mình sẽ quay về và nhận tin tức. Không có tư liệu nào cho biết Người đã trở lại bưu điện Le Havre để nhận thư hay chưa.","doc":5},{"loai":"ban_co_biet","text":"Tuyến tàu khách thường xuyên Le Havre – New York do Công ty Tàu biển Xuyên Đại Tây Dương (Compagnie Générale Transatlantique) mở từ năm 1864. Đến đầu thế kỷ XX, những con tàu lớn của hãng vượt đại dương trong khoảng một tuần.","nguon_ten":"Hiệp hội French Lines & Compagnies (Le Havre), tư liệu lịch sử Compagnie Générale Transatlantique","doc":6},{"loai":"doan","tieu_de":"Nghề ghi trong thư: thủy thủ","text":"Chữ “thủy thủ” trong lá thư cũng đáng suy ngẫm. Từ khi rời bến Nhà Rồng, Người đã sống bằng công việc trên tàu biển: phụ bếp, quét dọn, khuân vác, những việc nặng nhọc nhất của đời đi biển. Nghề ấy vừa là kế sinh nhai, vừa là tấm vé đi khắp thế giới mà một thanh niên xứ thuộc địa không có tiền bạc có thể có được. Mỗi chuyến làm việc trên tàu thường kết thúc ở một hải cảng, và người thủy thủ có thể lên bờ tìm việc khác trước khi xuống một con tàu mới.\n\nChính lối sống ấy giải thích vì sao Người có thể có mặt ở New York, rồi theo lời kể, làm phụ bếp ở Boston. Nó cũng giải thích vì sao dấu vết để lại quá ít: người lao động phiêu bạt không có giấy thuê nhà, không có tên trong danh bạ, hiếm khi được chụp ảnh. Lá thư New York vì thế càng quý. Đó là khoảnh khắc hiếm hoi người thủy thủ vô danh tự ghi tên mình, nghề mình và nơi mình nhận tin lên một tờ giấy còn lưu đến hôm nay.","doc":7},{"loai":"doan","tieu_de":"Hành trình của một lá thư năm 1912","text":"Năm 1912, gửi một lá thư từ New York sang châu Âu đã là việc bình thường, nhờ Liên minh Bưu chính Quốc tế ra đời năm 1874 tại Bern, Thụy Sĩ. Cả Mỹ và Pháp đều là thành viên, nên thư từ nước này sang nước kia được chuyển theo những quy tắc chung. Từ bưu điện, thư được đưa lên những con tàu hơi nước chở thư, vượt Đại Tây Dương trong khoảng một tuần, rồi tiếp tục theo đường bưu chính tới nơi nhận.\n\nTổng bưu cục New York khi ấy vẫn nằm trong tòa nhà ở mũi nam công viên City Hall, khu hạ Manhattan. Tòa bưu điện đồ sộ trên Đại lộ Tám, nay mang tên James A. Farley, phải đến năm 1914 mới khánh thành. Không ai biết lá thư của Người được bỏ vào thùng thư ở góc phố nào. Chỉ biết rằng con dấu bưu điện New York trên lá thư đã trở thành một chứng từ lịch sử, vì nó đặt người viết vào đúng một thành phố, trong đúng một thời điểm.","doc":8},{"loai":"anh","src":"textures/bang_w/G07_1_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lá thư đóng dấu bưu điện New York”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Kho hồ sơ của kẻ theo dõi","text":"Vì sao lá thư còn lại? Trước hết, nó được gửi tới chính bộ máy cai trị, nơi mọi giấy tờ gửi đến đều được vào sổ và lưu hồ sơ. Sau nữa, chỉ vài năm sau, người viết trở thành một nhân vật mà bộ máy ấy ra sức truy tìm. Tháng 6/1919, bản Yêu sách của nhân dân An Nam ký tên Nguyễn Ái Quốc được gửi tới Hội nghị Versailles, rồi được in thành truyền đơn phân phát ở Paris. Chính quyền Pháp lập tức muốn biết Nguyễn Ái Quốc là ai.\n\nMật thám được cài theo dõi, báo cáo từng bước đi, từng cuộc gặp của Người. Các cơ quan thuộc địa ra sức truy tìm lai lịch và mọi dấu vết của người con trai cụ Phó bảng Nguyễn Sinh Sắc, từ Huế, Phan Thiết, Sài Gòn đến Marseille, Le Havre. Nhờ vậy, những dòng chữ của người thủy thủ trẻ năm nào đã không thất lạc. Nghịch lý là ở chỗ đó: kho hồ sơ lập ra để theo dõi, kiểm soát, rốt cuộc lại giữ gìn cho hậu thế những dấu vết quý giá về hành trình của Người.","doc":9},{"loai":"ban_co_biet","text":"Phần lớn hồ sơ của bộ máy thuộc địa Pháp cũ nay được lưu tại Kho Lưu trữ quốc gia hải ngoại (Archives nationales d’outre-mer) ở thành phố Aix-en-Provence, miền Nam nước Pháp, lập năm 1966. Đây là nơi nhiều nhà nghiên cứu Việt Nam và quốc tế tìm đọc tư liệu về những năm bôn ba của Người.","nguon_ten":"Kho Lưu trữ quốc gia hải ngoại Pháp (Archives nationales d’outre-mer), Aix-en-Provence","doc":10},{"loai":"doan","tieu_de":"Đọc lá thư như một nhà sử học","text":"Chỉ vài dòng khai báo, nhưng lá thư trả lời được mấy câu hỏi quan trọng. Nó xác nhận Người có mặt ở New York vào giữa tháng 12/1912, nghĩa là đã vượt Đại Tây Dương trước thời điểm ấy. Nó cho biết Người vẫn sống bằng nghề đi biển. Nó cho thấy Người chưa có chỗ ở cố định và vẫn gắn với các hải cảng nước Pháp. Từ một điểm mốc chắc chắn như thế, các nhà nghiên cứu mới có thể sắp xếp những chi tiết khác vào trước hoặc sau.\n\nNhưng lá thư cũng im lặng về nhiều điều. Nó không nói Người đến Mỹ trên con tàu nào, từ bao giờ, định ở lại bao lâu. Nó không nhắc tới Boston hay khách sạn Parker House. Câu chuyện làm phụ bếp bánh ở Boston đến từ một nguồn khác: thư từ Người gửi cụ Phan Châu Trinh và những lời kể về sau. Nhà sử học phải đặt các nguồn ấy cạnh nhau, xem chúng khớp nhau đến đâu, và nói rõ chỗ nào là văn bản, chỗ nào là lời kể.","doc":11},{"loai":"anh","src":"textures/bang_w/G07_1_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lá thư đóng dấu bưu điện New York”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Những khoảng trống còn lại","text":"Ngoài lá thư, chặng Mỹ gần như không để lại văn bản độc lập nào. Hồ sơ nhân sự còn lại của khách sạn Parker House không có tên Người, và cho đến nay chưa có giấy tờ nào khác của nước Mỹ xác nhận sự có mặt ấy. Điều đó không quá lạ: người lao động nhập cư thời ấy, nhất là người châu Á, thường để lại rất ít giấy tờ, còn tên của họ lại dễ bị ghi sai hoặc thay bằng một bí danh. Vì thế, các nhà viết tiểu sử trong và ngoài nước đưa ra những mốc hơi khác nhau cho ngày rời nước Mỹ, phổ biến nhất là năm 1913.\n\nNhững khoảng trống ấy không làm chặng Mỹ kém quan trọng. Chúng chỉ nhắc rằng lịch sử được dựng lên từ bằng chứng, và nơi nào thiếu bằng chứng thì phải chấp nhận để trống. Một chi tiết dù hợp lý đến đâu, nếu chưa có văn bản xác nhận, vẫn chỉ được trình bày là khả năng. Chính sự thận trọng ấy làm cho những gì đã được xác nhận, như lá thư ngày 15/12/1912, càng có giá trị.","doc":12},{"loai":"anh","src":"textures/ht/ht_anh_omni_parker_house_school_st_boston_493545_110616.jpg","chu_thich":"Khách sạn Parker House trên phố School, Boston (ảnh chụp năm 2013). Địa chỉ này được biết qua lời kể; lá thư New York không nhắc tới Boston.","credit":"Ảnh: Robert Linsdell from St. Andrews, Canada · CC BY 2.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Từ người thủy thủ vô danh","text":"Lá thư ngày 15/12/1912 nhắc người xem hôm nay một điều giản dị: hành trình tìm đường cứu nước không bắt đầu bằng những sự kiện lớn, mà bằng những ngày lao động vô danh nơi đất khách. Người thủy thủ khai nghề trong lá thư ấy, chưa đầy bảy năm sau, sẽ ký tên Nguyễn Ái Quốc dưới bản Yêu sách của nhân dân An Nam. Gần ba mươi ba năm sau, Người sẽ đứng trên lễ đài Ba Đình đọc Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa.\n\nNgày nay, các văn bản của thời kỳ này phần lớn nằm trong những kho lưu trữ của Pháp. Nội dung của chúng đã được các nhà nghiên cứu khai thác, ghi lại trong bộ Hồ Chí Minh – Biên niên tiểu sử và nhiều công trình khác, để người đọc hôm nay có thể lần theo từng bước chân của Người. Đứng trước bảng này, người xem được mời làm việc của một nhà sử học: đọc chậm từng chữ, phân biệt điều đã biết với điều còn phải tìm, và trân trọng cả những dấu vết nhỏ nhất.","doc":13}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","William J. Duiker, Ho Chi Minh: A Life (2000)","Kho Lưu trữ quốc gia hải ngoại Pháp (Archives nationales d’outre-mer), Aix-en-Provence","Hiệp hội French Lines & Compagnies (Le Havre), tư liệu lịch sử Compagnie Générale Transatlantique","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Ngày 15/12/1912: lá thư đóng dấu New York và nghịch lý của kho hồ sơ theo dõi. Không có tấm ảnh hay trang nhật ký nào ghi lại những ngày Người ở Mỹ. Thứ còn lại trên giấy là một lá thư ngắn đề ngày 15/12/1912, mang dấu bưu điện New York. Nghịch lý thay, nó được giữ lại nhờ chính bộ máy thuộc địa vốn muốn theo dõi người viết. Đọc kỹ từng dòng khai báo, ta thấy hiện lên chân dung một người thủy thủ trẻ không nhà cửa mà không lạc hướng."},{"t":"Một lá thư từ bên kia đại dương. Tháng 12/1912, New York bước vào mùa đông. Gió từ sông Hudson thổi lạnh buốt qua những bến cảng dọc Manhattan, nơi tàu bè từ khắp thế giới ra vào tấp nập. Ngày 15/12/1912, một thanh niên Việt Nam hai mươi hai tuổi viết thư gửi các quan chức thuộc địa Pháp. Lá thư được đóng dấu bưu điện New York rồi bắt đầu hành trình vượt Đại Tây Dương. Trong thư, người viết khai nghề nghiệp của mình là thủy thủ. Địa chỉ liên lạc được ghi là “poste restante”, tức thư lưu tại bưu điện, ở thành phố cảng Le Havre bên bờ biển nước Pháp. Người viết lá thư ấy là Nguyễn Tất Thành. Lá thư được vào sổ, xếp vào hồ sơ, rồi nằm yên ở đó. Hơn một thế kỷ sau, nó là bằng chứng giấy tờ gần như duy nhất xác nhận rằng người thanh niên ấy thực sự có mặt trên đất Mỹ trong mùa đông năm 1912. Mọi câu chuyện khác về chặng Mỹ đều phải bắt đầu từ mấy dòng khai báo ngắn ngủi này."},{"t":"Người viết thư là ai trong mắt nhà cầm quyền. Với chính quyền thuộc địa, cái tên Nguyễn Tất Thành không hoàn toàn xa lạ. Người là con trai cụ Nguyễn Sinh Sắc, đỗ Phó bảng năm 1901, từng làm quan ở Bộ Lễ tại Huế rồi được bổ làm Tri huyện Bình Khê, tỉnh Bình Định. Năm 1910, cụ Sắc bị cách chức. Bản thân người con cũng đã sớm lọt vào tầm mắt của nhà cầm quyền: năm 1908, khi đang học ở Trường Quốc học Huế, Nguyễn Tất Thành tham gia phong trào nông dân chống thuế ở Trung Kỳ. Sau đó, Người rời Huế vào phía Nam, dạy học ở Trường Dục Thanh, Phan Thiết, rồi vào Sài Gòn đầu năm 1911 và xuống tàu ra đi với tên Văn Ba. Một thanh niên có lý lịch như thế, lại xuất dương, là người mà bộ máy thuộc địa muốn biết đang ở đâu, làm gì. Điều đáng chú ý là trong những thư từ gửi chính quyền các năm 1911 – 1912, Người vẫn ký chính tên thật của mình. Người thủy thủ trẻ không lẩn tránh; Người trực tiếp viết cho bộ máy cai trị, bằng chính tên mình, từ những nơi xa xôi nhất."},{"t":"Lá đơn gửi từ Marseille. Lá thư New York không phải là lần đầu người thanh niên ấy viết cho chính quyền Pháp. Ngày 15/9/1911, từ Marseille, Người gửi đơn lên Tổng thống Cộng hòa Pháp, xin được vào học Trường Thuộc địa. Ngôi trường ở Paris này, thành lập năm 1889, là nơi đào tạo viên chức cho bộ máy cai trị các xứ thuộc địa. Trong đơn, người viết tự giới thiệu là con trai ông Nguyễn Sinh Huy, tức cụ Nguyễn Sinh Sắc, một vị Phó bảng, và cho biết mình đang làm việc trên tàu Amiral Latouche-Tréville để kiếm sống. Lá đơn bị từ chối. Nhưng cũng như lá thư New York sau này, nó được lưu giữ trong hồ sơ của chính quyền. Đặt hai văn bản cạnh nhau, ta thấy một người thanh niên muốn hiểu bộ máy thuộc địa từ bên trong: xin vào học chính ngôi trường đào tạo những người cai trị đất nước mình, rồi khi không được, lại lên đường đi tiếp. Mười lăm tháng ngăn cách hai lá thư, và trong mười lăm tháng ấy, người viết đã đi từ bến cảng Marseille tới thành phố New York."},{"t":"Bạn có biết? Trong lá đơn gửi Tổng thống Pháp ngày 15/9/1911, người viết ghi mình sinh ở Vinh năm 1892, trong khi Người sinh năm 1890 tại quê ngoại, làng Hoàng Trù. Những chênh lệch như vậy là lý do các nhà nghiên cứu phải đối chiếu thật kỹ từng văn bản thời kỳ này."},{"t":"“Poste restante”: địa chỉ của người không nhà. Chi tiết đáng chú ý nhất trong lá thư New York có lẽ là địa chỉ liên lạc. “Poste restante”, dịch sát là “thư lưu lại”, là dịch vụ bưu điện dành cho những người không có chỗ ở cố định. Thư gửi tới được giữ tại quầy bưu điện của thành phố ghi trên phong bì, cho đến khi người nhận tự đến, trình giấy tờ và lấy về. Đầu thế kỷ XX, đây là cách liên lạc quen thuộc của thủy thủ, người buôn bán, khách lữ hành, những người hôm nay ở cảng này, tháng sau đã ở cảng khác. Việc chọn Le Havre cũng có lý do. Đây là một trong những hải cảng lớn nhất nước Pháp, nằm ở cửa sông Seine, nơi con tàu Amiral Latouche-Tréville từng ghé trong chuyến đi năm 1911. Le Havre còn là đầu mối của tuyến tàu khách thường xuyên sang New York. Ghi địa chỉ ở Le Havre cho thấy Người vẫn coi các bến cảng nước Pháp là nơi mình sẽ quay về và nhận tin tức. Không có tư liệu nào cho biết Người đã trở lại bưu điện Le Havre để nhận thư hay chưa."},{"t":"Bạn có biết? Tuyến tàu khách thường xuyên Le Havre – New York do Công ty Tàu biển Xuyên Đại Tây Dương (Compagnie Générale Transatlantique) mở từ năm 1864. Đến đầu thế kỷ XX, những con tàu lớn của hãng vượt đại dương trong khoảng một tuần."},{"t":"Nghề ghi trong thư: thủy thủ. Chữ “thủy thủ” trong lá thư cũng đáng suy ngẫm. Từ khi rời bến Nhà Rồng, Người đã sống bằng công việc trên tàu biển: phụ bếp, quét dọn, khuân vác, những việc nặng nhọc nhất của đời đi biển. Nghề ấy vừa là kế sinh nhai, vừa là tấm vé đi khắp thế giới mà một thanh niên xứ thuộc địa không có tiền bạc có thể có được. Mỗi chuyến làm việc trên tàu thường kết thúc ở một hải cảng, và người thủy thủ có thể lên bờ tìm việc khác trước khi xuống một con tàu mới. Chính lối sống ấy giải thích vì sao Người có thể có mặt ở New York, rồi theo lời kể, làm phụ bếp ở Boston. Nó cũng giải thích vì sao dấu vết để lại quá ít: người lao động phiêu bạt không có giấy thuê nhà, không có tên trong danh bạ, hiếm khi được chụp ảnh. Lá thư New York vì thế càng quý. Đó là khoảnh khắc hiếm hoi người thủy thủ vô danh tự ghi tên mình, nghề mình và nơi mình nhận tin lên một tờ giấy còn lưu đến hôm nay."},{"t":"Hành trình của một lá thư năm 1912. Năm 1912, gửi một lá thư từ New York sang châu Âu đã là việc bình thường, nhờ Liên minh Bưu chính Quốc tế ra đời năm 1874 tại Bern, Thụy Sĩ. Cả Mỹ và Pháp đều là thành viên, nên thư từ nước này sang nước kia được chuyển theo những quy tắc chung. Từ bưu điện, thư được đưa lên những con tàu hơi nước chở thư, vượt Đại Tây Dương trong khoảng một tuần, rồi tiếp tục theo đường bưu chính tới nơi nhận. Tổng bưu cục New York khi ấy vẫn nằm trong tòa nhà ở mũi nam công viên City Hall, khu hạ Manhattan. Tòa bưu điện đồ sộ trên Đại lộ Tám, nay mang tên James A. Farley, phải đến năm 1914 mới khánh thành. Không ai biết lá thư của Người được bỏ vào thùng thư ở góc phố nào. Chỉ biết rằng con dấu bưu điện New York trên lá thư đã trở thành một chứng từ lịch sử, vì nó đặt người viết vào đúng một thành phố, trong đúng một thời điểm."},{"t":"Kho hồ sơ của kẻ theo dõi. Vì sao lá thư còn lại? Trước hết, nó được gửi tới chính bộ máy cai trị, nơi mọi giấy tờ gửi đến đều được vào sổ và lưu hồ sơ. Sau nữa, chỉ vài năm sau, người viết trở thành một nhân vật mà bộ máy ấy ra sức truy tìm. Tháng 6/1919, bản Yêu sách của nhân dân An Nam ký tên Nguyễn Ái Quốc được gửi tới Hội nghị Versailles, rồi được in thành truyền đơn phân phát ở Paris. Chính quyền Pháp lập tức muốn biết Nguyễn Ái Quốc là ai. Mật thám được cài theo dõi, báo cáo từng bước đi, từng cuộc gặp của Người. Các cơ quan thuộc địa ra sức truy tìm lai lịch và mọi dấu vết của người con trai cụ Phó bảng Nguyễn Sinh Sắc, từ Huế, Phan Thiết, Sài Gòn đến Marseille, Le Havre. Nhờ vậy, những dòng chữ của người thủy thủ trẻ năm nào đã không thất lạc. Nghịch lý là ở chỗ đó: kho hồ sơ lập ra để theo dõi, kiểm soát, rốt cuộc lại giữ gìn cho hậu thế những dấu vết quý giá về hành trình của Người."},{"t":"Bạn có biết? Phần lớn hồ sơ của bộ máy thuộc địa Pháp cũ nay được lưu tại Kho Lưu trữ quốc gia hải ngoại (Archives nationales d’outre-mer) ở thành phố Aix-en-Provence, miền Nam nước Pháp, lập năm 1966. Đây là nơi nhiều nhà nghiên cứu Việt Nam và quốc tế tìm đọc tư liệu về những năm bôn ba của Người."},{"t":"Đọc lá thư như một nhà sử học. Chỉ vài dòng khai báo, nhưng lá thư trả lời được mấy câu hỏi quan trọng. Nó xác nhận Người có mặt ở New York vào giữa tháng 12/1912, nghĩa là đã vượt Đại Tây Dương trước thời điểm ấy. Nó cho biết Người vẫn sống bằng nghề đi biển. Nó cho thấy Người chưa có chỗ ở cố định và vẫn gắn với các hải cảng nước Pháp. Từ một điểm mốc chắc chắn như thế, các nhà nghiên cứu mới có thể sắp xếp những chi tiết khác vào trước hoặc sau. Nhưng lá thư cũng im lặng về nhiều điều. Nó không nói Người đến Mỹ trên con tàu nào, từ bao giờ, định ở lại bao lâu. Nó không nhắc tới Boston hay khách sạn Parker House. Câu chuyện làm phụ bếp bánh ở Boston đến từ một nguồn khác: thư từ Người gửi cụ Phan Châu Trinh và những lời kể về sau. Nhà sử học phải đặt các nguồn ấy cạnh nhau, xem chúng khớp nhau đến đâu, và nói rõ chỗ nào là văn bản, chỗ nào là lời kể."},{"t":"Những khoảng trống còn lại. Ngoài lá thư, chặng Mỹ gần như không để lại văn bản độc lập nào. Hồ sơ nhân sự còn lại của khách sạn Parker House không có tên Người, và cho đến nay chưa có giấy tờ nào khác của nước Mỹ xác nhận sự có mặt ấy. Điều đó không quá lạ: người lao động nhập cư thời ấy, nhất là người châu Á, thường để lại rất ít giấy tờ, còn tên của họ lại dễ bị ghi sai hoặc thay bằng một bí danh. Vì thế, các nhà viết tiểu sử trong và ngoài nước đưa ra những mốc hơi khác nhau cho ngày rời nước Mỹ, phổ biến nhất là năm 1913. Những khoảng trống ấy không làm chặng Mỹ kém quan trọng. Chúng chỉ nhắc rằng lịch sử được dựng lên từ bằng chứng, và nơi nào thiếu bằng chứng thì phải chấp nhận để trống. Một chi tiết dù hợp lý đến đâu, nếu chưa có văn bản xác nhận, vẫn chỉ được trình bày là khả năng. Chính sự thận trọng ấy làm cho những gì đã được xác nhận, như lá thư ngày 15/12/1912, càng có giá trị."},{"t":"Từ người thủy thủ vô danh. Lá thư ngày 15/12/1912 nhắc người xem hôm nay một điều giản dị: hành trình tìm đường cứu nước không bắt đầu bằng những sự kiện lớn, mà bằng những ngày lao động vô danh nơi đất khách. Người thủy thủ khai nghề trong lá thư ấy, chưa đầy bảy năm sau, sẽ ký tên Nguyễn Ái Quốc dưới bản Yêu sách của nhân dân An Nam. Gần ba mươi ba năm sau, Người sẽ đứng trên lễ đài Ba Đình đọc Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Ngày nay, các văn bản của thời kỳ này phần lớn nằm trong những kho lưu trữ của Pháp. Nội dung của chúng đã được các nhà nghiên cứu khai thác, ghi lại trong bộ Hồ Chí Minh – Biên niên tiểu sử và nhiều công trình khác, để người đọc hôm nay có thể lần theo từng bước chân của Người. Đứng trước bảng này, người xem được mời làm việc của một nhà sử học: đọc chậm từng chữ, phân biệt điều đã biết với điều còn phải tìm, và trân trọng cả những dấu vết nhỏ nhất."}],"so_chu":2169},{"i":2,"tieu_de_bang":"Từ Harlem đến bài báo “Hành hình kiểu Linsơ”","tieu_de":"“Hành hình kiểu Linsơ”: bản cáo trạng viết sau mười một năm","sapo":"Năm 1924, giữa những trang tin về các đại hội và phong trào cách mạng, độc giả tập san của Quốc tế Cộng sản bắt gặp một lời mời lạnh người: “Các bạn hãy tưởng tượng…”. Tác giả là Nguyễn Ái Quốc, người thanh niên từng làm thuê trên đất Mỹ hơn mười năm trước. Bài báo “Hành hình kiểu Linsơ” đã biến những điều người thợ phụ năm nào chứng kiến thành một bản cáo trạng bằng hình ảnh và con số.","bia":{"src":"textures/bai/G07_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"“Các bạn hãy tưởng tượng…”","text":"Bài báo mở ra bằng một nhận định thẳng thắn: chủng tộc da đen là chủng tộc bị áp bức, bóc lột nặng nề bậc nhất. Trong mọi nỗi khổ họ phải chịu trên đất Mỹ, tục hành hình kiểu Linsơ là tàn ác nhất, ghê tởm nhất. Rồi tác giả chuyển sang một đoạn văn có tiêu đề “Các bạn hãy tưởng tượng…”. Người đọc bị đặt vào giữa một đám đông cuồng nộ đang vây bắt một người da đen, hành hạ và giết hại người ấy trong tiếng reo hò của những kẻ đứng xem.\n\nBài báo mang tiêu đề phụ “Một phương diện ít người biết của nền văn minh Mỹ”, ký tên Nguyễn Ái Quốc. Nó được đăng năm 1924 trên tập san tiếng Pháp La Correspondance Internationale, tức Thư tín quốc tế, số 59, cơ quan thông tin của Quốc tế Cộng sản. Không cần lời kêu gọi dài dòng, bài viết để cho cảnh tượng và con số tự lên tiếng. Chính sự điềm tĩnh ấy khiến người đọc rùng mình, và nhận ra rằng đằng sau những tòa nhà chọc trời vẫn còn một nước Mỹ khác.","doc":1},{"loai":"doan","tieu_de":"Nước Mỹ mà người thợ phụ đi qua","text":"Hơn mười năm trước khi viết bài báo, người thanh niên Nguyễn Tất Thành đã sống giữa lòng nước Mỹ. Đó là thời kỳ mà người Mỹ gốc Phi, dù chế độ nô lệ đã bị bãi bỏ từ năm 1865, vẫn bị đối xử như công dân hạng hai. Ở các bang miền Nam, những đạo luật phân biệt chủng tộc buộc họ đi toa tàu riêng, học trường riêng, ngồi ở khu riêng nơi công cộng; phần lớn bị tước quyền bầu cử. Năm 1896, Tòa án Tối cao Mỹ còn hợp thức hóa sự phân biệt ấy bằng nguyên tắc “tách biệt nhưng bình đẳng”.\n\nỞ miền Bắc, người da đen bị phân biệt trong việc làm và nhà ở. Năm 1913, chính quyền của Tổng thống Wilson bắt đầu tách riêng nhân viên da đen ở một số cơ quan liên bang tại Washington. Cũng trong những năm ấy, người Mỹ gốc Phi tụ về khu Harlem của New York ngày một đông (xem chuyên đề New York và Harlem). Theo lời kể của chính Người và các tư liệu sau này, người thanh niên Việt Nam đã đến Harlem, dự các buổi diễn thuyết và chứng kiến cảnh phân biệt chủng tộc.","doc":2},{"loai":"anh","src":"textures/bang_w/G07_2_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Từ Harlem đến bài báo “Hành hình kiểu Linsơ””, nhìn từ xa."},{"loai":"doan","tieu_de":"Một chữ mang tên người","text":"“Linsơ” là cách phiên âm tiếng Việt của chữ lynch trong tiếng Anh. Theo cách giải thích phổ biến, chữ này bắt nguồn từ tên Charles Lynch, một điền chủ kiêm thẩm phán hòa giải ở bang Virginia. Trong thời kỳ cách mạng Mỹ, ông lập những phiên tòa ngoài pháp luật để trừng trị những người bị coi là chống đối. Từ đó xuất hiện cụm từ “luật Lynch”, chỉ việc trừng phạt không qua xét xử.\n\nSau cuộc Nội chiến, nhất là từ thập niên 1880, “luật Lynch” mang một nghĩa ghê rợn hơn. Những đám đông người da trắng tự tay treo cổ, bắn chết, thậm chí thiêu sống người da đen, nhiều khi chỉ vì một lời tố cáo không hề được kiểm chứng. Nạn nhân không được ra tòa, còn kẻ giết người hầu như không bao giờ bị trừng phạt. Có những vụ hành hình diễn ra giữa ban ngày trước hàng nghìn người xem; ảnh chụp cảnh tượng còn được in thành bưu thiếp. Đó chính là thứ “văn minh” mà bài báo năm 1924 đem ra ánh sáng.","doc":3},{"loai":"ban_co_biet","text":"Theo số liệu lưu trữ của Viện Tuskegee ở bang Alabama, từ năm 1882 đến năm 1968 nước Mỹ ghi nhận 4.743 người bị hành hình kiểu linsơ, trong đó 3.446 người là người da đen. Đó mới chỉ là những vụ được ghi chép lại.","nguon_ten":"Số liệu lưu trữ của Viện Tuskegee (nay là Đại học Tuskegee), Alabama, Hoa Kỳ","doc":4},{"loai":"doan","tieu_de":"Những con số trong bài báo","text":"Sau cảnh tượng, bài báo chuyển sang phần “Một chút thống kê”. Theo số liệu Nguyễn Ái Quốc dẫn ra, trong ba mươi năm từ 1889 đến 1919, có 2.600 người da đen bị hành hình kiểu Linsơ, trong đó có 51 phụ nữ. Cùng thời gian ấy, 708 người da trắng cũng bị hành hình, trong đó có 11 phụ nữ; theo bài báo, họ bị giết vì tổ chức bãi công hoặc ủng hộ cuộc đấu tranh của người da đen. Riêng năm 1919 có 78 vụ, với 11 nạn nhân bị thiêu sống. Những năm sau con số giảm dần nhưng chưa dứt: 50 vụ năm 1920, 28 vụ năm 1923.\n\nPhần tiếp theo mang tên “Vài chi tiết”, dẫn lại những mẩu tin trên chính báo chí Mỹ, như tờ New Orleans States số ra ngày 26/6/1919. Dùng tài liệu của đối phương để tố cáo đối phương là thủ pháp quen thuộc trong ngòi bút chính luận Nguyễn Ái Quốc. Người không cần thêm nhiều lời bình, vì những dòng tin do chính báo chí Mỹ đăng tải đã đủ sức kết tội.","doc":5},{"loai":"trich","text":"Hành hình kiểu Linsơ thật đáng chiếm một vị trí vinh dự trong bộ sưu tập toàn bộ những tội ác của nền “văn minh” Mỹ.","nguoi":"Nguyễn Ái Quốc, câu kết bài “Hành hình kiểu Linsơ” (1924)","nguon_ten":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia; Bảo tàng Hồ Chí Minh","doc":6},{"loai":"doan","tieu_de":"Bài báo viết từ Mátxcơva","text":"Năm 1924, Nguyễn Ái Quốc không còn ở Paris. Tháng 6/1923, Người bí mật rời nước Pháp sang Liên Xô, học tập và làm việc ở Mátxcơva. Tháng 10/1923, Người dự Hội nghị Quốc tế Nông dân lần thứ nhất và được bầu vào cơ quan lãnh đạo của tổ chức này. Mùa hè 1924, tại Đại hội V Quốc tế Cộng sản, Người phát biểu về vấn đề thuộc địa. Người nhắc các đảng cộng sản ở chính quốc rằng vận mệnh của giai cấp vô sản gắn chặt với vận mệnh các dân tộc bị áp bức.\n\nTrong những tháng ấy, Người viết đều đặn cho tập san Thư tín quốc tế, vốn phát hành bằng nhiều thứ tiếng như Đức, Pháp, Anh để đến với những người cộng sản khắp thế giới. “Hành hình kiểu Linsơ” vì thế không chỉ dành cho người Pháp hay người Việt. Nó hướng tới độc giả quốc tế, đưa thân phận người da đen ở Mỹ vào mối quan tâm chung của phong trào cách mạng thế giới. Tháng 11/1924, Người rời Mátxcơva đến Quảng Châu, bắt đầu một chặng hoạt động mới gần Tổ quốc hơn.","doc":7},{"loai":"ban_co_biet","text":"Bảo tàng Hồ Chí Minh ở Hà Nội đang lưu giữ một bản bài báo “Hành hình kiểu Linsơ” in trên tờ nhật báo Dieweltribune, số ra ngày 9/10/1924. Điều đó cho thấy bài viết đã được in lại ngoài tập san Thư tín quốc tế.","nguon_ten":"Bảo tàng Hồ Chí Minh, hồ sơ hiện vật: https://baotanghochiminh.vn/bai-bao-cua-nguyen-ai-quoc-nhan-de-hanh-hinh-kieu-linso-dang-tren-nhat-bao-dieweltribune.htm","doc":8},{"loai":"anh","src":"textures/bang_w/G07_2_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Từ Harlem đến bài báo “Hành hình kiểu Linsơ””, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Ku Klux Klan: những chiếc mũ trùm trở lại","text":"Cũng trong năm 1924, Nguyễn Ái Quốc viết một bài báo về Ku Klux Klan, tổ chức khủng bố phân biệt chủng tộc khét tiếng nhất nước Mỹ. Tổ chức này ra đời năm 1865 ở bang Tennessee, ngay sau cuộc Nội chiến, chuyên dùng bạo lực để khủng bố những người da đen vừa được giải phóng. Bị đàn áp mạnh vào đầu thập niên 1870, nó tưởng như đã tan rã.\n\nNăm 1915, Ku Klux Klan được lập lại trên núi Stone Mountain, bang Georgia, đúng năm bộ phim “Sự ra đời của một quốc gia” tô vẽ cho nó được trình chiếu khắp nước Mỹ. Trong thập niên 1920, tổ chức này lan rộng cả ra miền Bắc, thu hút hàng triệu hội viên, thù ghét không chỉ người da đen mà cả người Công giáo, người Do Thái và người nhập cư. Như vậy, Nguyễn Ái Quốc viết về Ku Klux Klan đúng lúc nó đang ở đỉnh cao thế lực. Năm 1925, hàng vạn thành viên đội mũ trùm trắng còn diễu hành công khai giữa thủ đô Washington.","doc":9},{"loai":"doan","tieu_de":"Người da đen và người thuộc địa: cùng một cảnh ngộ","text":"Sức nặng của những bài báo năm 1924 không chỉ ở sự phẫn nộ. Nguyễn Ái Quốc đặt thân phận người da đen ở Mỹ bên cạnh thân phận người dân các xứ thuộc địa: cùng bị coi là thấp kém, cùng bị tước đoạt những quyền mà các bản tuyên ngôn long trọng đã hứa hẹn. Cách nhìn ấy đã hình thành từ những năm ở Paris. Năm 1921, Người cùng những người yêu nước từ các thuộc địa Pháp lập Hội Liên hiệp thuộc địa; ngày 1/4/1922, số đầu tờ báo Người cùng khổ (Le Paria) của Hội ra đời.\n\nTác phẩm Bản án chế độ thực dân Pháp, xuất bản tại Paris năm 1925, tiếp tục mạch tố cáo ấy. Chương đầu của cuốn sách mang tên “Thuế máu”, kể việc hàng vạn người dân thuộc địa bị đưa sang chiến trường châu Âu trong Chiến tranh thế giới thứ nhất. Từ người da đen bị treo cổ ở miền Nam nước Mỹ đến người lính thuộc địa bỏ mạng trên đất Pháp, Nguyễn Ái Quốc nhìn thấy cùng một cơ chế áp bức. Với Người, những người bị áp bức ở khắp nơi cần hiểu nhau và đoàn kết với nhau.","doc":10},{"loai":"ban_co_biet","text":"Ngày 13/6/2005, Thượng viện Mỹ thông qua nghị quyết chính thức xin lỗi các nạn nhân hành hình và con cháu họ. Lý do: trong nửa đầu thế kỷ XX, Thượng viện đã không thông qua được luật chống hành hình, dù gần 200 dự luật như vậy từng được đưa ra Quốc hội.","nguon_ten":"Quốc hội Hoa Kỳ, Nghị quyết Thượng viện S.Res.39 (2005)","doc":11},{"loai":"anh","src":"textures/bang_w/G07_2_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Từ Harlem đến bài báo “Hành hình kiểu Linsơ””, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Tiếng vọng một thế kỷ","text":"Khi Nguyễn Ái Quốc viết bài báo, cuộc đấu tranh chống nạn hành hình ở Mỹ đã kéo dài nhiều năm. Từ năm 1892, nữ nhà báo da đen Ida B. Wells đã in những tập sách nhỏ tố cáo “luật Lynch”. Hội Quốc gia vì sự tiến bộ của người da màu, thành lập năm 1909 ở New York, liên tục công bố số liệu và vận động Quốc hội. Tháng 1/1922, dự luật chống hành hình do nghị sĩ Leonidas Dyer đề xuất được Hạ viện thông qua, nhưng bị chặn lại ở Thượng viện.\n\nPhải mất gần một thế kỷ, nước Mỹ mới trả lời trọn vẹn câu hỏi mà bài báo năm 1924 đặt ra. Năm 1955, cậu bé da đen mười bốn tuổi Emmett Till bị sát hại dã man ở bang Mississippi, làm chấn động dư luận và thúc đẩy phong trào dân quyền. Ngày 29/3/2022, đạo luật chống hành hình mang tên Emmett Till được ký ban hành, chính thức coi hành hình là tội ác thù ghét theo luật liên bang. Lời tố cáo của người thợ phụ năm xưa, rốt cuộc, đã được lịch sử xác nhận.","doc":12},{"loai":"anh","src":"textures/bai/G07_v5.jpg","chu_thich":"Một góc không gian 3D tái hiện gian Nước Mỹ – Boston và New York.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, “Hành hình kiểu Linsơ” cùng bài viết về Ku Klux Klan được in trong bộ Hồ Chí Minh Toàn tập, để người đọc Việt Nam có thể tìm đọc trọn vẹn. Bảo tàng Hồ Chí Minh ở Hà Nội lưu giữ một bản in bài báo năm 1924 như một hiện vật về những năm hoạt động báo chí của Người. Muốn hiểu thêm bối cảnh khu Harlem thời ấy, người xem có thể đọc chuyên đề New York và Harlem trong cùng gian.\n\nỞ nước Mỹ, ký ức về nạn hành hình cũng đã được đối diện công khai. Tháng 4/2018, Đài tưởng niệm Quốc gia vì Hòa bình và Công lý khánh thành ở thành phố Montgomery, bang Alabama. Hơn tám trăm khối thép treo lơ lửng, mỗi khối mang tên một hạt và tên những nạn nhân bị hành hình ở đó; tổng cộng hơn bốn nghìn cái tên. Đứng giữa những khối thép ấy, người ta hiểu vì sao từ năm 1924, một người Việt Nam đã gọi tội ác này là một phương diện ít người biết của nền văn minh Mỹ.","doc":13}],"nguon":["Nguyễn Ái Quốc, “Hành hình kiểu Linsơ”, La Correspondance Internationale (Inprekorr), bản tiếng Pháp, số 59, 1924 – in trong Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","Bảo tàng Hồ Chí Minh, hiện vật “Bài báo của Nguyễn Ái Quốc, nhan đề Hành hình kiểu Linsơ”: https://baotanghochiminh.vn/bai-bao-cua-nguyen-ai-quoc-nhan-de-hanh-hinh-kieu-linso-dang-tren-nhat-bao-dieweltribune.htm","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Số liệu lưu trữ về hành hình của Viện Tuskegee (Đại học Tuskegee), Alabama","Quốc hội Hoa Kỳ: Nghị quyết Thượng viện S.Res.39 (2005); Đạo luật chống hành hình Emmett Till (2022)","Equal Justice Initiative – Đài tưởng niệm Quốc gia vì Hòa bình và Công lý, Montgomery, Alabama"],"doc":[{"t":"“Hành hình kiểu Linsơ”: bản cáo trạng viết sau mười một năm. Năm 1924, giữa những trang tin về các đại hội và phong trào cách mạng, độc giả tập san của Quốc tế Cộng sản bắt gặp một lời mời lạnh người: “Các bạn hãy tưởng tượng…”. Tác giả là Nguyễn Ái Quốc, người thanh niên từng làm thuê trên đất Mỹ hơn mười năm trước. Bài báo “Hành hình kiểu Linsơ” đã biến những điều người thợ phụ năm nào chứng kiến thành một bản cáo trạng bằng hình ảnh và con số."},{"t":"“Các bạn hãy tưởng tượng…”. Bài báo mở ra bằng một nhận định thẳng thắn: chủng tộc da đen là chủng tộc bị áp bức, bóc lột nặng nề bậc nhất. Trong mọi nỗi khổ họ phải chịu trên đất Mỹ, tục hành hình kiểu Linsơ là tàn ác nhất, ghê tởm nhất. Rồi tác giả chuyển sang một đoạn văn có tiêu đề “Các bạn hãy tưởng tượng…”. Người đọc bị đặt vào giữa một đám đông cuồng nộ đang vây bắt một người da đen, hành hạ và giết hại người ấy trong tiếng reo hò của những kẻ đứng xem. Bài báo mang tiêu đề phụ “Một phương diện ít người biết của nền văn minh Mỹ”, ký tên Nguyễn Ái Quốc. Nó được đăng năm 1924 trên tập san tiếng Pháp La Correspondance Internationale, tức Thư tín quốc tế, số 59, cơ quan thông tin của Quốc tế Cộng sản. Không cần lời kêu gọi dài dòng, bài viết để cho cảnh tượng và con số tự lên tiếng. Chính sự điềm tĩnh ấy khiến người đọc rùng mình, và nhận ra rằng đằng sau những tòa nhà chọc trời vẫn còn một nước Mỹ khác."},{"t":"Nước Mỹ mà người thợ phụ đi qua. Hơn mười năm trước khi viết bài báo, người thanh niên Nguyễn Tất Thành đã sống giữa lòng nước Mỹ. Đó là thời kỳ mà người Mỹ gốc Phi, dù chế độ nô lệ đã bị bãi bỏ từ năm 1865, vẫn bị đối xử như công dân hạng hai. Ở các bang miền Nam, những đạo luật phân biệt chủng tộc buộc họ đi toa tàu riêng, học trường riêng, ngồi ở khu riêng nơi công cộng; phần lớn bị tước quyền bầu cử. Năm 1896, Tòa án Tối cao Mỹ còn hợp thức hóa sự phân biệt ấy bằng nguyên tắc “tách biệt nhưng bình đẳng”. Ở miền Bắc, người da đen bị phân biệt trong việc làm và nhà ở. Năm 1913, chính quyền của Tổng thống Wilson bắt đầu tách riêng nhân viên da đen ở một số cơ quan liên bang tại Washington. Cũng trong những năm ấy, người Mỹ gốc Phi tụ về khu Harlem của New York ngày một đông (xem chuyên đề New York và Harlem). Theo lời kể của chính Người và các tư liệu sau này, người thanh niên Việt Nam đã đến Harlem, dự các buổi diễn thuyết và chứng kiến cảnh phân biệt chủng tộc."},{"t":"Một chữ mang tên người. “Linsơ” là cách phiên âm tiếng Việt của chữ lynch trong tiếng Anh. Theo cách giải thích phổ biến, chữ này bắt nguồn từ tên Charles Lynch, một điền chủ kiêm thẩm phán hòa giải ở bang Virginia. Trong thời kỳ cách mạng Mỹ, ông lập những phiên tòa ngoài pháp luật để trừng trị những người bị coi là chống đối. Từ đó xuất hiện cụm từ “luật Lynch”, chỉ việc trừng phạt không qua xét xử. Sau cuộc Nội chiến, nhất là từ thập niên 1880, “luật Lynch” mang một nghĩa ghê rợn hơn. Những đám đông người da trắng tự tay treo cổ, bắn chết, thậm chí thiêu sống người da đen, nhiều khi chỉ vì một lời tố cáo không hề được kiểm chứng. Nạn nhân không được ra tòa, còn kẻ giết người hầu như không bao giờ bị trừng phạt. Có những vụ hành hình diễn ra giữa ban ngày trước hàng nghìn người xem; ảnh chụp cảnh tượng còn được in thành bưu thiếp. Đó chính là thứ “văn minh” mà bài báo năm 1924 đem ra ánh sáng."},{"t":"Bạn có biết? Theo số liệu lưu trữ của Viện Tuskegee ở bang Alabama, từ năm 1882 đến năm 1968 nước Mỹ ghi nhận 4.743 người bị hành hình kiểu linsơ, trong đó 3.446 người là người da đen. Đó mới chỉ là những vụ được ghi chép lại."},{"t":"Những con số trong bài báo. Sau cảnh tượng, bài báo chuyển sang phần “Một chút thống kê”. Theo số liệu Nguyễn Ái Quốc dẫn ra, trong ba mươi năm từ 1889 đến 1919, có 2.600 người da đen bị hành hình kiểu Linsơ, trong đó có 51 phụ nữ. Cùng thời gian ấy, 708 người da trắng cũng bị hành hình, trong đó có 11 phụ nữ; theo bài báo, họ bị giết vì tổ chức bãi công hoặc ủng hộ cuộc đấu tranh của người da đen. Riêng năm 1919 có 78 vụ, với 11 nạn nhân bị thiêu sống. Những năm sau con số giảm dần nhưng chưa dứt: 50 vụ năm 1920, 28 vụ năm 1923. Phần tiếp theo mang tên “Vài chi tiết”, dẫn lại những mẩu tin trên chính báo chí Mỹ, như tờ New Orleans States số ra ngày 26/6/1919. Dùng tài liệu của đối phương để tố cáo đối phương là thủ pháp quen thuộc trong ngòi bút chính luận Nguyễn Ái Quốc. Người không cần thêm nhiều lời bình, vì những dòng tin do chính báo chí Mỹ đăng tải đã đủ sức kết tội."},{"t":"Hành hình kiểu Linsơ thật đáng chiếm một vị trí vinh dự trong bộ sưu tập toàn bộ những tội ác của nền “văn minh” Mỹ. — Nguyễn Ái Quốc, câu kết bài “Hành hình kiểu Linsơ” (1924)"},{"t":"Bài báo viết từ Mátxcơva. Năm 1924, Nguyễn Ái Quốc không còn ở Paris. Tháng 6/1923, Người bí mật rời nước Pháp sang Liên Xô, học tập và làm việc ở Mátxcơva. Tháng 10/1923, Người dự Hội nghị Quốc tế Nông dân lần thứ nhất và được bầu vào cơ quan lãnh đạo của tổ chức này. Mùa hè 1924, tại Đại hội V Quốc tế Cộng sản, Người phát biểu về vấn đề thuộc địa. Người nhắc các đảng cộng sản ở chính quốc rằng vận mệnh của giai cấp vô sản gắn chặt với vận mệnh các dân tộc bị áp bức. Trong những tháng ấy, Người viết đều đặn cho tập san Thư tín quốc tế, vốn phát hành bằng nhiều thứ tiếng như Đức, Pháp, Anh để đến với những người cộng sản khắp thế giới. “Hành hình kiểu Linsơ” vì thế không chỉ dành cho người Pháp hay người Việt. Nó hướng tới độc giả quốc tế, đưa thân phận người da đen ở Mỹ vào mối quan tâm chung của phong trào cách mạng thế giới. Tháng 11/1924, Người rời Mátxcơva đến Quảng Châu, bắt đầu một chặng hoạt động mới gần Tổ quốc hơn."},{"t":"Bạn có biết? Bảo tàng Hồ Chí Minh ở Hà Nội đang lưu giữ một bản bài báo “Hành hình kiểu Linsơ” in trên tờ nhật báo Dieweltribune, số ra ngày 9/10/1924. Điều đó cho thấy bài viết đã được in lại ngoài tập san Thư tín quốc tế."},{"t":"Ku Klux Klan: những chiếc mũ trùm trở lại. Cũng trong năm 1924, Nguyễn Ái Quốc viết một bài báo về Ku Klux Klan, tổ chức khủng bố phân biệt chủng tộc khét tiếng nhất nước Mỹ. Tổ chức này ra đời năm 1865 ở bang Tennessee, ngay sau cuộc Nội chiến, chuyên dùng bạo lực để khủng bố những người da đen vừa được giải phóng. Bị đàn áp mạnh vào đầu thập niên 1870, nó tưởng như đã tan rã. Năm 1915, Ku Klux Klan được lập lại trên núi Stone Mountain, bang Georgia, đúng năm bộ phim “Sự ra đời của một quốc gia” tô vẽ cho nó được trình chiếu khắp nước Mỹ. Trong thập niên 1920, tổ chức này lan rộng cả ra miền Bắc, thu hút hàng triệu hội viên, thù ghét không chỉ người da đen mà cả người Công giáo, người Do Thái và người nhập cư. Như vậy, Nguyễn Ái Quốc viết về Ku Klux Klan đúng lúc nó đang ở đỉnh cao thế lực. Năm 1925, hàng vạn thành viên đội mũ trùm trắng còn diễu hành công khai giữa thủ đô Washington."},{"t":"Người da đen và người thuộc địa: cùng một cảnh ngộ. Sức nặng của những bài báo năm 1924 không chỉ ở sự phẫn nộ. Nguyễn Ái Quốc đặt thân phận người da đen ở Mỹ bên cạnh thân phận người dân các xứ thuộc địa: cùng bị coi là thấp kém, cùng bị tước đoạt những quyền mà các bản tuyên ngôn long trọng đã hứa hẹn. Cách nhìn ấy đã hình thành từ những năm ở Paris. Năm 1921, Người cùng những người yêu nước từ các thuộc địa Pháp lập Hội Liên hiệp thuộc địa; ngày 1/4/1922, số đầu tờ báo Người cùng khổ (Le Paria) của Hội ra đời. Tác phẩm Bản án chế độ thực dân Pháp, xuất bản tại Paris năm 1925, tiếp tục mạch tố cáo ấy. Chương đầu của cuốn sách mang tên “Thuế máu”, kể việc hàng vạn người dân thuộc địa bị đưa sang chiến trường châu Âu trong Chiến tranh thế giới thứ nhất. Từ người da đen bị treo cổ ở miền Nam nước Mỹ đến người lính thuộc địa bỏ mạng trên đất Pháp, Nguyễn Ái Quốc nhìn thấy cùng một cơ chế áp bức. Với Người, những người bị áp bức ở khắp nơi cần hiểu nhau và đoàn kết với nhau."},{"t":"Bạn có biết? Ngày 13/6/2005, Thượng viện Mỹ thông qua nghị quyết chính thức xin lỗi các nạn nhân hành hình và con cháu họ. Lý do: trong nửa đầu thế kỷ XX, Thượng viện đã không thông qua được luật chống hành hình, dù gần 200 dự luật như vậy từng được đưa ra Quốc hội."},{"t":"Tiếng vọng một thế kỷ. Khi Nguyễn Ái Quốc viết bài báo, cuộc đấu tranh chống nạn hành hình ở Mỹ đã kéo dài nhiều năm. Từ năm 1892, nữ nhà báo da đen Ida B. Wells đã in những tập sách nhỏ tố cáo “luật Lynch”. Hội Quốc gia vì sự tiến bộ của người da màu, thành lập năm 1909 ở New York, liên tục công bố số liệu và vận động Quốc hội. Tháng 1/1922, dự luật chống hành hình do nghị sĩ Leonidas Dyer đề xuất được Hạ viện thông qua, nhưng bị chặn lại ở Thượng viện. Phải mất gần một thế kỷ, nước Mỹ mới trả lời trọn vẹn câu hỏi mà bài báo năm 1924 đặt ra. Năm 1955, cậu bé da đen mười bốn tuổi Emmett Till bị sát hại dã man ở bang Mississippi, làm chấn động dư luận và thúc đẩy phong trào dân quyền. Ngày 29/3/2022, đạo luật chống hành hình mang tên Emmett Till được ký ban hành, chính thức coi hành hình là tội ác thù ghét theo luật liên bang. Lời tố cáo của người thợ phụ năm xưa, rốt cuộc, đã được lịch sử xác nhận."},{"t":"Dấu tích hôm nay. Ngày nay, “Hành hình kiểu Linsơ” cùng bài viết về Ku Klux Klan được in trong bộ Hồ Chí Minh Toàn tập, để người đọc Việt Nam có thể tìm đọc trọn vẹn. Bảo tàng Hồ Chí Minh ở Hà Nội lưu giữ một bản in bài báo năm 1924 như một hiện vật về những năm hoạt động báo chí của Người. Muốn hiểu thêm bối cảnh khu Harlem thời ấy, người xem có thể đọc chuyên đề New York và Harlem trong cùng gian. Ở nước Mỹ, ký ức về nạn hành hình cũng đã được đối diện công khai. Tháng 4/2018, Đài tưởng niệm Quốc gia vì Hòa bình và Công lý khánh thành ở thành phố Montgomery, bang Alabama. Hơn tám trăm khối thép treo lơ lửng, mỗi khối mang tên một hạt và tên những nạn nhân bị hành hình ở đó; tổng cộng hơn bốn nghìn cái tên. Đứng giữa những khối thép ấy, người ta hiểu vì sao từ năm 1924, một người Việt Nam đã gọi tội ác này là một phương diện ít người biết của nền văn minh Mỹ."}],"so_chu":2001},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ bến Nhà Rồng đến Quảng trường Ba Đình: hai mươi chín mốc quanh chặng Mỹ","sapo":"Chặng Mỹ chỉ kéo dài chưa đầy một năm và để lại rất ít giấy tờ. Muốn hiểu nó, phải đặt nó vào một dòng thời gian dài hơn: từ bản Tuyên ngôn năm 1776 của nước Mỹ, qua những năm người phụ bếp Văn Ba lênh đênh trên biển, đến ngày Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập ở Ba Đình. Mỗi mốc dưới đây được đánh dấu rõ: đâu là văn bản, đâu là lời kể, đâu là bối cảnh.","bia":{"src":"textures/bai/G07_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Cách đọc dòng thời gian","text":"Dòng thời gian dưới đây có hai mươi chín mốc, trải từ năm 1776 đến năm 1946. Để người xem không nhầm lẫn giữa điều đã chắc chắn và điều còn là lời kể, nhiều mốc được đánh dấu theo nguồn gốc. Những mốc ghi “Văn bản” dựa trên giấy tờ đương thời còn lưu giữ, như lá đơn gửi từ Marseille hay lá thư đóng dấu New York. Những mốc ghi “Theo lời kể” đến từ hồi ức của chính Người và các tư liệu về sau, chưa có văn bản độc lập xác nhận. Những mốc ghi “Bối cảnh” không trực tiếp nói về Người, mà giúp hình dung nước Mỹ quanh chặng dừng chân ấy. Các mốc còn lại thuộc phần tiểu sử đã được xác lập vững chắc, ghi trong bộ Hồ Chí Minh – Biên niên tiểu sử.","doc":1},{"loai":"moc","items":[["4/7/1776","Bối cảnh: Tuyên ngôn Độc lập Hoa Kỳ được thông qua tại Philadelphia, khẳng định mọi người sinh ra bình đẳng, có quyền sống, quyền tự do và quyền mưu cầu hạnh phúc."],["1855","Bối cảnh: khách sạn Parker House do Harvey D. Parker sáng lập khai trương trên phố School, trung tâm Boston; về sau được coi là khách sạn hoạt động liên tục lâu đời nhất nước Mỹ."],["6/12/1865","Bối cảnh: Tu chính án thứ 13 của Hiến pháp Mỹ được phê chuẩn, bãi bỏ chế độ nô lệ; nhưng sự phân biệt đối xử với người da đen còn kéo dài nhiều thập kỷ."],["19/5/1890","Nguyễn Sinh Cung, tức Nguyễn Tất Thành sau này, chào đời tại làng Hoàng Trù, quê ngoại, ở Nam Đàn, Nghệ An."],["18/5/1896","Bối cảnh: Tòa án Tối cao Mỹ ra phán quyết trong vụ Plessy kiện Ferguson, hợp thức hóa sự phân biệt chủng tộc theo nguyên tắc “tách biệt nhưng bình đẳng”."],["1901","Cụ Nguyễn Sinh Sắc, thân phụ của Người, đỗ Phó bảng; danh vị ấy về sau được nhắc trong lá đơn Người gửi chính quyền Pháp năm 1911."],["1908","Đang học ở Trường Quốc học Huế, Nguyễn Tất Thành tham gia phong trào nông dân chống thuế ở Trung Kỳ và bắt đầu bị nhà cầm quyền để ý."],["1910","Cụ Nguyễn Sinh Sắc bị cách chức Tri huyện Bình Khê. Nguyễn Tất Thành vào Phan Thiết, dạy học ở Trường Dục Thanh."],["5/6/1911","Từ bến Nhà Rồng, Sài Gòn, Nguyễn Tất Thành ra đi trên tàu Amiral Latouche-Tréville, làm phụ bếp với tên Văn Ba."],["6/7/1911","Tàu cập cảng Marseille; lần đầu người thanh niên đặt chân lên đất Pháp."],["15/9/1911","Văn bản: từ Marseille, Người gửi đơn lên Tổng thống Cộng hòa Pháp xin vào học Trường Thuộc địa; lá đơn bị từ chối."],["1911 – 1912","Tiếp tục làm việc trên tàu biển, qua cảng Le Havre và nhiều hải cảng ở châu Phi, tận mắt thấy đời sống người dân các xứ thuộc địa."],["4/7/1912","Bối cảnh: quốc kỳ Mỹ 48 sao chính thức được sử dụng, sau khi New Mexico và Arizona gia nhập liên bang đầu năm ấy."],["5/11/1912","Bối cảnh: Woodrow Wilson đắc cử tổng thống Mỹ, sau cuộc bầu cử có bốn ứng cử viên lớn."],["Cuối năm 1912","Người vượt Đại Tây Dương sang nước Mỹ; đến nay chưa xác định được con tàu và ngày cập bến."],["15/12/1912","Văn bản: lá thư đóng dấu bưu điện New York gửi các quan chức thuộc địa Pháp, khai nghề thủy thủ, địa chỉ là thư lưu tại bưu điện Le Havre."],["1912 – 1913","Theo lời kể: làm phụ bếp bánh ở khách sạn Parker House, Boston; điều này được nhắc trong thư từ Người gửi cụ Phan Châu Trinh."],["1912 – 1913","Theo lời kể: sống, làm thuê ở New York, đi xem khu Harlem, dự các buổi diễn thuyết; có thể đã ở Harlem một thời gian."],["1913","Rời nước Mỹ sang nước Anh, tiếp tục sống bằng lao động chân tay và học tiếng Anh."],["Cuối năm 1917","Từ nước Anh trở lại nước Pháp, hoạt động trong phong trào của những người Việt yêu nước ở Paris."],["18/6/1919","Ký tên Nguyễn Ái Quốc dưới bản Yêu sách của nhân dân An Nam gửi Hội nghị Versailles; bản Yêu sách được gửi tới các phái đoàn, trong đó có phái đoàn Mỹ."],["1/4/1922","Số đầu báo Người cùng khổ (Le Paria), cơ quan của Hội Liên hiệp thuộc địa, ra đời ở Paris."],["6/1923","Bí mật rời nước Pháp sang Liên Xô, học tập và làm việc ở Mátxcơva."],["1924","Văn bản: bài “Hành hình kiểu Linsơ” đăng trên tập san Thư tín quốc tế, số 59; cùng năm, Người viết bài về tổ chức Ku Klux Klan."],["1925","Tác phẩm Bản án chế độ thực dân Pháp được xuất bản tại Paris."],["1927","Bối cảnh: khách sạn Parker House được xây dựng lại phần lớn, thành tòa nhà cao tầng trên cùng địa điểm như ngày nay."],["28/1/1941","Sau ba mươi năm bôn ba, Người về nước qua cột mốc 108 ở biên giới Cao Bằng."],["2/9/1945","Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình, mở đầu bằng lời trích Tuyên ngôn Độc lập Hoa Kỳ năm 1776."],["1945 – 1946","Chủ tịch Hồ Chí Minh nhiều lần gửi thư, điện tới Tổng thống Mỹ Harry Truman, đề nghị ủng hộ nền độc lập của Việt Nam; không có hồi âm."]],"doc":2},{"loai":"doan","tieu_de":"Những năm chuẩn bị (1890 – 1911)","text":"Nhìn vào phần đầu dòng thời gian, có thể thấy người thanh niên đặt chân lên đất Mỹ không phải là một người lao động bình thường. Đó là con trai một vị Phó bảng, từng học Trường Quốc học Huế, từng tham gia phong trào chống thuế năm 1908 và từng đứng trên bục giảng Trường Dục Thanh. Người mang theo vốn chữ Hán, chữ quốc ngữ, tiếng Pháp học ở trường, và một câu hỏi lớn về vận mệnh đất nước. Khi rời bến Nhà Rồng năm 1911, Người chọn con đường khác với nhiều bậc tiền bối: không sang phương Đông cầu viện, mà sang phương Tây để tận mắt xem các nước ấy làm thế nào. Chặng Mỹ là một phần của lựa chọn đó.","doc":3},{"loai":"anh","src":"textures/bang_w/G07_3_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ xa."},{"loai":"doan","tieu_de":"Mười tám tháng trên biển","text":"Từ tháng 6/1911 đến cuối năm 1912, dòng thời gian gần như chỉ có tên những bến cảng. Đó là khoảng mười tám tháng người phụ bếp Văn Ba sống trên những con tàu, làm những công việc nặng nhọc nhất để đổi lấy mỗi hải trình. Mốc có ngày tháng chính xác nhất trong quãng này là lá đơn ngày 15/9/1911 gửi từ Marseille, xin vào học Trường Thuộc địa. Lá đơn bị từ chối, và người thanh niên lại xuống tàu. Qua Le Havre, qua nhiều hải cảng châu Phi, Người thấy người dân các thuộc địa cũng nghèo khổ, cũng bị áp bức như đồng bào mình. Những quan sát ấy chuẩn bị cho con mắt sẽ nhìn nước Mỹ: không chỉ thấy nhà cao, phố rộng, mà thấy cả thân phận con người.","doc":4},{"loai":"ban_co_biet","text":"Con tàu Amiral Latouche-Tréville mang tên một đô đốc hải quân Pháp thế kỷ XVIII, Louis-René Levassor de Latouche-Tréville, người từng chỉ huy hạm đội Pháp chống lại hải quân Anh trong các cuộc chiến tranh thời Napoléon.","nguon_ten":"Bách khoa toàn thư Larousse, mục Latouche-Tréville; Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh (Bến Nhà Rồng)","doc":5},{"loai":"doan","tieu_de":"Mùa đông 1912 – 1913: ba mốc, ba mức độ chắc chắn","text":"Phần giữa dòng thời gian là chặng Mỹ, và ở đây cách đánh dấu nguồn gốc trở nên đặc biệt quan trọng. Mốc chắc chắn nhất là ngày 15/12/1912, với lá thư đóng dấu bưu điện New York. Từ lá thư, có thể suy ra Người đã vượt Đại Tây Dương trước thời điểm ấy, nên mốc đến Mỹ được ghi là “cuối năm 1912”. Mốc làm phụ bếp ở khách sạn Parker House được nhắc trong thư từ Người gửi cụ Phan Châu Trinh và trong lời kể về sau, nhưng hồ sơ khách sạn không lưu tên Người. Mốc về khu Harlem còn mờ hơn: các nhà viết tiểu sử chỉ dùng chữ “có thể”. Ba mốc, ba mức độ chắc chắn, được đặt cạnh nhau mà không trộn lẫn vào nhau.","doc":6},{"loai":"anh","src":"textures/bang_w/G07_3_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Nước Mỹ quanh chặng dừng chân","text":"Những mốc “Bối cảnh” giúp đặt người thanh niên vào đúng thời điểm của nước Mỹ. Tháng 7/1912, lá cờ 48 sao bắt đầu tung bay. Tháng 11/1912, Woodrow Wilson đắc cử tổng thống, trong một cuộc bầu cử mà ứng cử viên xã hội chủ nghĩa cũng giành được hơn 900 nghìn phiếu. Xa hơn về trước là hai mốc đối nghịch nhau. Bản Tuyên ngôn năm 1776 nói mọi người sinh ra bình đẳng, còn phán quyết năm 1896 của Tòa án Tối cao lại hợp thức hóa sự phân biệt chủng tộc. Người thanh niên Việt Nam đến Mỹ đúng lúc khoảng cách giữa hai mốc ấy hiện ra rõ rệt trong đời sống hằng ngày (xem chuyên đề Từ Harlem đến bài báo “Hành hình kiểu Linsơ”).","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_omni_parker_house_54957839082.jpg","chu_thich":"Mặt tiền khách sạn Parker House ngày nay (ảnh chụp năm 2025) — tòa nhà dựng lại năm 1927, mốc cuối cùng của khách sạn trong dòng thời gian.","credit":"Ảnh: ajay_suresh · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Mười một năm để thành trang viết","text":"Phần sau của dòng thời gian cho thấy một khoảng lặng dài giữa quan sát và trang viết. Năm 1913, Người rời Mỹ sang Anh; cuối năm 1917 trở lại Pháp; năm 1919 xuất hiện trên chính trường với cái tên Nguyễn Ái Quốc. Phải đến năm 1924, khi đã ở Mátxcơva, Người mới viết những bài báo tố cáo nạn hành hình người da đen và tổ chức Ku Klux Klan. Từ mùa đông ở New York đến bài báo ấy là mười một năm. Khoảng cách ấy cho thấy những điều thấy ở Mỹ không bị quên đi, mà được nghiền ngẫm, đối chiếu với những gì Người thấy ở các thuộc địa, rồi mới thành lời tố cáo. Năm 1925, Bản án chế độ thực dân Pháp được xuất bản tại Paris, khi Người đã hoạt động ở Quảng Châu.","doc":8},{"loai":"doan","tieu_de":"Giữa hai bản tuyên ngôn","text":"Mốc đầu và gần cuối của dòng thời gian là hai bản tuyên ngôn độc lập, cách nhau một trăm sáu mươi chín năm. Bản thứ nhất ra đời ở Philadelphia năm 1776; bản thứ hai được đọc ở Quảng trường Ba Đình ngày 2/9/1945. Nối hai mốc ấy là cuộc đời của một người từng đi qua nước Mỹ khi còn là người thợ phụ vô danh. Khi soạn Tuyên ngôn Độc lập, Chủ tịch Hồ Chí Minh mở đầu bằng lời bản Tuyên ngôn Mỹ, rồi suy rộng ra thành quyền của mọi dân tộc (xem chuyên đề Lời Bác). Ngay sau đó, từ cuối năm 1945 sang năm 1946, Người nhiều lần gửi thư, điện tới Tổng thống Mỹ nhưng không có hồi âm. Mốc cuối cùng ấy nhắc rằng lý tưởng và thực tế vẫn còn cách nhau rất xa.","doc":9},{"loai":"anh","src":"textures/bang_w/G07_3_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Nhiều mốc trong dòng thời gian này vẫn có thể tìm thấy dấu tích. Ở Nghệ An, Khu di tích Kim Liên lưu giữ làng Hoàng Trù và làng Sen, nơi Người sinh ra và lớn lên. Bến Nhà Rồng nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh; ngày 5/6 hằng năm được kỷ niệm là ngày Bác ra đi tìm đường cứu nước. Ở Boston, khách sạn Parker House vẫn hoạt động ở góc phố School và phố Tremont, dù tòa nhà đã được dựng lại năm 1927. Ở Cao Bằng, cột mốc 108 và hang Cốc Bó ở Pác Bó đánh dấu ngày trở về. Ở Hà Nội, Quảng trường Ba Đình và Bảo tàng Hồ Chí Minh khép lại hành trình. Nối những địa điểm ấy trên bản đồ, đoạn đứt nét ngang Đại Tây Dương hiện ra như một mắt xích nhỏ nhưng không thể thiếu.","doc":10},{"loai":"ban_co_biet","text":"Tuyên ngôn Độc lập Hoa Kỳ có 56 người ký tên. Hai người trong số đó về sau trở thành tổng thống là John Adams và Thomas Jefferson; cả hai cùng qua đời đúng ngày 4/7/1826, tròn năm mươi năm sau ngày bản Tuyên ngôn được thông qua.","nguon_ten":"Cục Lưu trữ Quốc gia Hoa Kỳ (National Archives), tư liệu về Tuyên ngôn Độc lập","doc":11}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1 và tập 2, NXB Chính trị quốc gia","Bảo tàng Hồ Chí Minh; Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh (Bến Nhà Rồng)","Tuyên ngôn Độc lập nước Việt Nam Dân chủ Cộng hòa, 2/9/1945 – Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","William J. Duiker, Ho Chi Minh: A Life (2000)","Cục Lưu trữ Quốc gia Hoa Kỳ (National Archives): Tuyên ngôn Độc lập 1776, Tu chính án thứ 13, hồ sơ vụ Plessy kiện Ferguson"],"doc":[{"t":"Từ bến Nhà Rồng đến Quảng trường Ba Đình: hai mươi chín mốc quanh chặng Mỹ. Chặng Mỹ chỉ kéo dài chưa đầy một năm và để lại rất ít giấy tờ. Muốn hiểu nó, phải đặt nó vào một dòng thời gian dài hơn: từ bản Tuyên ngôn năm 1776 của nước Mỹ, qua những năm người phụ bếp Văn Ba lênh đênh trên biển, đến ngày Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập ở Ba Đình. Mỗi mốc dưới đây được đánh dấu rõ: đâu là văn bản, đâu là lời kể, đâu là bối cảnh."},{"t":"Cách đọc dòng thời gian. Dòng thời gian dưới đây có hai mươi chín mốc, trải từ năm 1776 đến năm 1946. Để người xem không nhầm lẫn giữa điều đã chắc chắn và điều còn là lời kể, nhiều mốc được đánh dấu theo nguồn gốc. Những mốc ghi “Văn bản” dựa trên giấy tờ đương thời còn lưu giữ, như lá đơn gửi từ Marseille hay lá thư đóng dấu New York. Những mốc ghi “Theo lời kể” đến từ hồi ức của chính Người và các tư liệu về sau, chưa có văn bản độc lập xác nhận. Những mốc ghi “Bối cảnh” không trực tiếp nói về Người, mà giúp hình dung nước Mỹ quanh chặng dừng chân ấy. Các mốc còn lại thuộc phần tiểu sử đã được xác lập vững chắc, ghi trong bộ Hồ Chí Minh – Biên niên tiểu sử."},{"t":"Các mốc thời gian. 4/7/1776: Bối cảnh: Tuyên ngôn Độc lập Hoa Kỳ được thông qua tại Philadelphia, khẳng định mọi người sinh ra bình đẳng, có quyền sống, quyền tự do và quyền mưu cầu hạnh phúc. 1855: Bối cảnh: khách sạn Parker House do Harvey D. Parker sáng lập khai trương trên phố School, trung tâm Boston; về sau được coi là khách sạn hoạt động liên tục lâu đời nhất nước Mỹ. 6/12/1865: Bối cảnh: Tu chính án thứ 13 của Hiến pháp Mỹ được phê chuẩn, bãi bỏ chế độ nô lệ; nhưng sự phân biệt đối xử với người da đen còn kéo dài nhiều thập kỷ. 19/5/1890: Nguyễn Sinh Cung, tức Nguyễn Tất Thành sau này, chào đời tại làng Hoàng Trù, quê ngoại, ở Nam Đàn, Nghệ An. 18/5/1896: Bối cảnh: Tòa án Tối cao Mỹ ra phán quyết trong vụ Plessy kiện Ferguson, hợp thức hóa sự phân biệt chủng tộc theo nguyên tắc “tách biệt nhưng bình đẳng”. 1901: Cụ Nguyễn Sinh Sắc, thân phụ của Người, đỗ Phó bảng; danh vị ấy về sau được nhắc trong lá đơn Người gửi chính quyền Pháp năm 1911. 1908: Đang học ở Trường Quốc học Huế, Nguyễn Tất Thành tham gia phong trào nông dân chống thuế ở Trung Kỳ và bắt đầu bị nhà cầm quyền để ý. 1910: Cụ Nguyễn Sinh Sắc bị cách chức Tri huyện Bình Khê. Nguyễn Tất Thành vào Phan Thiết, dạy học ở Trường Dục Thanh. 5/6/1911: Từ bến Nhà Rồng, Sài Gòn, Nguyễn Tất Thành ra đi trên tàu Amiral Latouche-Tréville, làm phụ bếp với tên Văn Ba. 6/7/1911: Tàu cập cảng Marseille; lần đầu người thanh niên đặt chân lên đất Pháp. 15/9/1911: Văn bản: từ Marseille, Người gửi đơn lên Tổng thống Cộng hòa Pháp xin vào học Trường Thuộc địa; lá đơn bị từ chối. 1911 – 1912: Tiếp tục làm việc trên tàu biển, qua cảng Le Havre và nhiều hải cảng ở châu Phi, tận mắt thấy đời sống người dân các xứ thuộc địa. 4/7/1912: Bối cảnh: quốc kỳ Mỹ 48 sao chính thức được sử dụng, sau khi New Mexico và Arizona gia nhập liên bang đầu năm ấy. 5/11/1912: Bối cảnh: Woodrow Wilson đắc cử tổng thống Mỹ, sau cuộc bầu cử có bốn ứng cử viên lớn. Cuối năm 1912: Người vượt Đại Tây Dương sang nước Mỹ; đến nay chưa xác định được con tàu và ngày cập bến. 15/12/1912: Văn bản: lá thư đóng dấu bưu điện New York gửi các quan chức thuộc địa Pháp, khai nghề thủy thủ, địa chỉ là thư lưu tại bưu điện Le Havre. 1912 – 1913: Theo lời kể: làm phụ bếp bánh ở khách sạn Parker House, Boston; điều này được nhắc trong thư từ Người gửi cụ Phan Châu Trinh. 1912 – 1913: Theo lời kể: sống, làm thuê ở New York, đi xem khu Harlem, dự các buổi diễn thuyết; có thể đã ở Harlem một thời gian. 1913: Rời nước Mỹ sang nước Anh, tiếp tục sống bằng lao động chân tay và học tiếng Anh. Cuối năm 1917: Từ nước Anh trở lại nước Pháp, hoạt động trong phong trào của những người Việt yêu nước ở Paris. 18/6/1919: Ký tên Nguyễn Ái Quốc dưới bản Yêu sách của nhân dân An Nam gửi Hội nghị Versailles; bản Yêu sách được gửi tới các phái đoàn, trong đó có phái đoàn Mỹ. 1/4/1922: Số đầu báo Người cùng khổ (Le Paria), cơ quan của Hội Liên hiệp thuộc địa, ra đời ở Paris. 6/1923: Bí mật rời nước Pháp sang Liên Xô, học tập và làm việc ở Mátxcơva. 1924: Văn bản: bài “Hành hình kiểu Linsơ” đăng trên tập san Thư tín quốc tế, số 59; cùng năm, Người viết bài về tổ chức Ku Klux Klan. 1925: Tác phẩm Bản án chế độ thực dân Pháp được xuất bản tại Paris. 1927: Bối cảnh: khách sạn Parker House được xây dựng lại phần lớn, thành tòa nhà cao tầng trên cùng địa điểm như ngày nay. 28/1/1941: Sau ba mươi năm bôn ba, Người về nước qua cột mốc 108 ở biên giới Cao Bằng. 2/9/1945: Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại Quảng trường Ba Đình, mở đầu bằng lời trích Tuyên ngôn Độc lập Hoa Kỳ năm 1776. 1945 – 1946: Chủ tịch Hồ Chí Minh nhiều lần gửi thư, điện tới Tổng thống Mỹ Harry Truman, đề nghị ủng hộ nền độc lập của Việt Nam; không có hồi âm."},{"t":"Những năm chuẩn bị (1890 – 1911). Nhìn vào phần đầu dòng thời gian, có thể thấy người thanh niên đặt chân lên đất Mỹ không phải là một người lao động bình thường. Đó là con trai một vị Phó bảng, từng học Trường Quốc học Huế, từng tham gia phong trào chống thuế năm 1908 và từng đứng trên bục giảng Trường Dục Thanh. Người mang theo vốn chữ Hán, chữ quốc ngữ, tiếng Pháp học ở trường, và một câu hỏi lớn về vận mệnh đất nước. Khi rời bến Nhà Rồng năm 1911, Người chọn con đường khác với nhiều bậc tiền bối: không sang phương Đông cầu viện, mà sang phương Tây để tận mắt xem các nước ấy làm thế nào. Chặng Mỹ là một phần của lựa chọn đó."},{"t":"Mười tám tháng trên biển. Từ tháng 6/1911 đến cuối năm 1912, dòng thời gian gần như chỉ có tên những bến cảng. Đó là khoảng mười tám tháng người phụ bếp Văn Ba sống trên những con tàu, làm những công việc nặng nhọc nhất để đổi lấy mỗi hải trình. Mốc có ngày tháng chính xác nhất trong quãng này là lá đơn ngày 15/9/1911 gửi từ Marseille, xin vào học Trường Thuộc địa. Lá đơn bị từ chối, và người thanh niên lại xuống tàu. Qua Le Havre, qua nhiều hải cảng châu Phi, Người thấy người dân các thuộc địa cũng nghèo khổ, cũng bị áp bức như đồng bào mình. Những quan sát ấy chuẩn bị cho con mắt sẽ nhìn nước Mỹ: không chỉ thấy nhà cao, phố rộng, mà thấy cả thân phận con người."},{"t":"Bạn có biết? Con tàu Amiral Latouche-Tréville mang tên một đô đốc hải quân Pháp thế kỷ XVIII, Louis-René Levassor de Latouche-Tréville, người từng chỉ huy hạm đội Pháp chống lại hải quân Anh trong các cuộc chiến tranh thời Napoléon."},{"t":"Mùa đông 1912 – 1913: ba mốc, ba mức độ chắc chắn. Phần giữa dòng thời gian là chặng Mỹ, và ở đây cách đánh dấu nguồn gốc trở nên đặc biệt quan trọng. Mốc chắc chắn nhất là ngày 15/12/1912, với lá thư đóng dấu bưu điện New York. Từ lá thư, có thể suy ra Người đã vượt Đại Tây Dương trước thời điểm ấy, nên mốc đến Mỹ được ghi là “cuối năm 1912”. Mốc làm phụ bếp ở khách sạn Parker House được nhắc trong thư từ Người gửi cụ Phan Châu Trinh và trong lời kể về sau, nhưng hồ sơ khách sạn không lưu tên Người. Mốc về khu Harlem còn mờ hơn: các nhà viết tiểu sử chỉ dùng chữ “có thể”. Ba mốc, ba mức độ chắc chắn, được đặt cạnh nhau mà không trộn lẫn vào nhau."},{"t":"Nước Mỹ quanh chặng dừng chân. Những mốc “Bối cảnh” giúp đặt người thanh niên vào đúng thời điểm của nước Mỹ. Tháng 7/1912, lá cờ 48 sao bắt đầu tung bay. Tháng 11/1912, Woodrow Wilson đắc cử tổng thống, trong một cuộc bầu cử mà ứng cử viên xã hội chủ nghĩa cũng giành được hơn 900 nghìn phiếu. Xa hơn về trước là hai mốc đối nghịch nhau. Bản Tuyên ngôn năm 1776 nói mọi người sinh ra bình đẳng, còn phán quyết năm 1896 của Tòa án Tối cao lại hợp thức hóa sự phân biệt chủng tộc. Người thanh niên Việt Nam đến Mỹ đúng lúc khoảng cách giữa hai mốc ấy hiện ra rõ rệt trong đời sống hằng ngày (xem chuyên đề Từ Harlem đến bài báo “Hành hình kiểu Linsơ”)."},{"t":"Mười một năm để thành trang viết. Phần sau của dòng thời gian cho thấy một khoảng lặng dài giữa quan sát và trang viết. Năm 1913, Người rời Mỹ sang Anh; cuối năm 1917 trở lại Pháp; năm 1919 xuất hiện trên chính trường với cái tên Nguyễn Ái Quốc. Phải đến năm 1924, khi đã ở Mátxcơva, Người mới viết những bài báo tố cáo nạn hành hình người da đen và tổ chức Ku Klux Klan. Từ mùa đông ở New York đến bài báo ấy là mười một năm. Khoảng cách ấy cho thấy những điều thấy ở Mỹ không bị quên đi, mà được nghiền ngẫm, đối chiếu với những gì Người thấy ở các thuộc địa, rồi mới thành lời tố cáo. Năm 1925, Bản án chế độ thực dân Pháp được xuất bản tại Paris, khi Người đã hoạt động ở Quảng Châu."},{"t":"Giữa hai bản tuyên ngôn. Mốc đầu và gần cuối của dòng thời gian là hai bản tuyên ngôn độc lập, cách nhau một trăm sáu mươi chín năm. Bản thứ nhất ra đời ở Philadelphia năm 1776; bản thứ hai được đọc ở Quảng trường Ba Đình ngày 2/9/1945. Nối hai mốc ấy là cuộc đời của một người từng đi qua nước Mỹ khi còn là người thợ phụ vô danh. Khi soạn Tuyên ngôn Độc lập, Chủ tịch Hồ Chí Minh mở đầu bằng lời bản Tuyên ngôn Mỹ, rồi suy rộng ra thành quyền của mọi dân tộc (xem chuyên đề Lời Bác). Ngay sau đó, từ cuối năm 1945 sang năm 1946, Người nhiều lần gửi thư, điện tới Tổng thống Mỹ nhưng không có hồi âm. Mốc cuối cùng ấy nhắc rằng lý tưởng và thực tế vẫn còn cách nhau rất xa."},{"t":"Dấu tích hôm nay. Nhiều mốc trong dòng thời gian này vẫn có thể tìm thấy dấu tích. Ở Nghệ An, Khu di tích Kim Liên lưu giữ làng Hoàng Trù và làng Sen, nơi Người sinh ra và lớn lên. Bến Nhà Rồng nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh; ngày 5/6 hằng năm được kỷ niệm là ngày Bác ra đi tìm đường cứu nước. Ở Boston, khách sạn Parker House vẫn hoạt động ở góc phố School và phố Tremont, dù tòa nhà đã được dựng lại năm 1927. Ở Cao Bằng, cột mốc 108 và hang Cốc Bó ở Pác Bó đánh dấu ngày trở về. Ở Hà Nội, Quảng trường Ba Đình và Bảo tàng Hồ Chí Minh khép lại hành trình. Nối những địa điểm ấy trên bản đồ, đoạn đứt nét ngang Đại Tây Dương hiện ra như một mắt xích nhỏ nhưng không thể thiếu."},{"t":"Bạn có biết? Tuyên ngôn Độc lập Hoa Kỳ có 56 người ký tên. Hai người trong số đó về sau trở thành tổng thống là John Adams và Thomas Jefferson; cả hai cùng qua đời đúng ngày 4/7/1826, tròn năm mươi năm sau ngày bản Tuyên ngôn được thông qua."}],"so_chu":1289},{"i":4,"tieu_de_bang":"Khách sạn Parker House trên phố School, Boston","tieu_de":"Phố School, Boston: một góc phố, ba thế kỷ và địa chỉ cụ thể nhất của Bác trên đất Mỹ","sapo":"Đầu giờ chiều ngày 1/10/2013, một người chụp ảnh đến từ Canada hướng ống kính về khách sạn Parker House ở trung tâm Boston. Tấm ảnh du lịch ấy nay nằm trong một bảo tàng kể về cuộc đời Chủ tịch Hồ Chí Minh. Bởi trên chính khu đất này, theo lời kể, người thanh niên Nguyễn Tất Thành từng làm phụ bếp bánh trong mùa đông 1912–1913 — và con phố nhỏ quanh khách sạn còn giữ dấu vết của gần bốn thế kỷ lịch sử nước Mỹ.","bia":{"src":"textures/ht/ht_anh_omni_parker_house_school_st_boston_493545_110616.jpg","credit":"Ảnh: Robert Linsdell from St. Andrews, Canada · CC BY 2.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một tấm ảnh của người lữ khách","text":"Theo dữ liệu còn lưu cùng tệp ảnh, tấm ảnh được chụp lúc 13 giờ 21 phút ngày 1/10/2013. Người bấm máy ký tên Robert Linsdell, đến từ thị trấn St. Andrews của Canada. Ông chia sẻ ảnh theo giấy phép Creative Commons CC BY 2.0, cho phép bất kỳ ai sử dụng lại với điều kiện ghi tên tác giả. Nhờ vậy, một tấm ảnh du lịch bình thường đã có thể đi vào phòng trưng bày của bảo tàng.\n\nKhung hình hướng về khách sạn Parker House trên phố School, ngay chỗ con phố gặp phố Tremont, giữa khu trung tâm lịch sử của Boston. Cần nói ngay: tòa nhà trong ảnh là tòa nhà được xây dựng lại, hoàn thành năm 1927, chứ không phải tòa nhà mà người thanh niên Việt Nam có thể đã thấy trong mùa đông 1912–1913. Nhưng nền đất vẫn là nền đất ấy, và tên khách sạn vẫn là tên ấy. Lá thư hiếm hoi còn lại từ chặng Mỹ chỉ mang dấu bưu điện New York, không kèm một số nhà nào. Vì thế, trong tất cả những gì được kể về những tháng ngày của Bác trên đất Mỹ, góc phố này là địa chỉ cụ thể nhất có thể chỉ ra trên bản đồ.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_omni_parker_house_school_st_boston_493545_110616.jpg","chu_thich":"Khách sạn Parker House ở góc phố School và phố Tremont, Boston, ảnh chụp ngày 1/10/2013. Theo lời kể, trên khu đất này người thanh niên Nguyễn Tất Thành từng làm phụ bếp bánh mùa đông 1912–1913; tòa nhà trong ảnh được xây lại năm 1927. Ảnh: Robert Linsdell, CC BY 2.0.","credit":"Ảnh: Robert Linsdell from St. Andrews, Canada · CC BY 2.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Con phố mang tên một ngôi trường","text":"Phố School không dài, nối phố Tremont với phố Washington, hai trục đường cổ của trung tâm Boston. Tên phố có từ thời thuộc địa, gắn với Trường Latin Boston, ngôi trường từng đặt trên con phố này. Trường được thành lập ngày 23/4/1635, sớm hơn Đại học Harvard một năm, và được coi là trường công lập lâu đời nhất nước Mỹ. Ngôi trường về sau chuyển đi nơi khác và vẫn hoạt động đến ngày nay.\n\nTrên vỉa hè phố School hôm nay, một bức tranh ghép nhiều màu đánh dấu vị trí ngôi trường xưa, và du khách thường dừng chân ở đó. Ngay từ tên gọi, con phố nơi đặt khách sạn Parker House đã gắn với ý niệm trường học công cho trẻ em của cả cộng đồng. Ở xứ An Nam năm 1912, điều ấy còn rất xa vời: trường học là đặc quyền của số ít, và chương trình do chính quyền thuộc địa đặt ra. Người thanh niên Nguyễn Tất Thành hiểu điều đó hơn ai hết. Trước khi xuống tàu ra đi năm 1911, Người từng dạy học ở trường Dục Thanh, Phan Thiết, một ngôi trường do những nhà nho yêu nước lập nên.","doc":2},{"loai":"ban_co_biet","text":"Trong số 56 người ký tên dưới bản Tuyên ngôn Độc lập Hoa Kỳ năm 1776, có năm người từng là học sinh Trường Latin Boston: Samuel Adams, John Hancock, Benjamin Franklin, Robert Treat Paine và William Hooper. Riêng Franklin chỉ học ở đây một thời gian ngắn rồi phải nghỉ để phụ việc cho cha.","nguon_ten":"Trường Latin Boston (Boston Latin School); Tổ chức Con đường Tự do Boston (The Freedom Trail Foundation)","doc":3},{"loai":"doan","tieu_de":"Tòa thị chính cũ bên kia phố","text":"Bên kia phố School, cạnh nghĩa trang cổ của nhà thờ King’s Chapel, là Tòa thị chính cũ của Boston ở số 45. Tòa nhà được xây trong những năm 1862–1865, do hai kiến trúc sư Gridley J. F. Bryant và Arthur Gilman thiết kế theo phong cách Đế chế thứ hai của Pháp. Đặc trưng dễ nhận ra nhất là mái dốc kiểu Mansard với những ô cửa sổ nhô lên, rất thịnh hành ở Paris thời Napoléon III.\n\nTừ năm 1865 đến năm 1969, đây là trụ sở chính quyền thành phố. Như vậy, trong mùa đông 1912–1913, bộ máy cai quản cả thành phố Boston làm việc ngay trước mặt khách sạn Parker House. Một con phố nhỏ chứa trong nó cả những phòng làm việc của thị trưởng, hội đồng thành phố, lẫn những gian bếp nơi người làm thuê nhập cư kiếm sống. Năm 1969, chính quyền Boston chuyển sang tòa thị chính mới. Tòa nhà cũ không bị phá bỏ mà được cải tạo thành văn phòng và nhà hàng, cho nó một đời sống mới. Đó cũng là số phận chung của nhiều công trình quanh góc phố này: được giữ lại, được tiếp tục sử dụng, thay vì bị đóng băng thành hiện vật.","doc":4},{"loai":"anh","src":"textures/bang_w/G07_4_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Khách sạn Parker House trên phố School, Boston”, nhìn từ xa."},{"loai":"doan","tieu_de":"Bức tượng Franklin và câu văn về quyền bình đẳng","text":"Trước sân Tòa thị chính cũ là bức tượng đồng Benjamin Franklin, dựng năm 1856, do nhà điêu khắc Richard Saltonstall Greenough thực hiện. Bệ tượng gắn những tấm phù điêu kể lại các chặng đời ông, từ người thợ in đến nhà khoa học và nhà ngoại giao. Franklin sinh năm 1706 ngay tại Boston, trên phố Milk cách đó không xa, trong một gia đình làm nến và xà phòng.\n\nNăm 1776, ông là một trong năm người được Quốc hội Lục địa giao soạn thảo bản Tuyên ngôn Độc lập, rồi đặt bút ký dưới văn kiện ấy. Như vậy, chỉ cách cửa khách sạn một quãng ngắn là hình ảnh của một người đã góp tay viết nên câu văn nói rằng mọi người sinh ra đều bình đẳng. Hơn ba mươi năm sau mùa đông ở Boston, chính câu văn ấy sẽ vang lên ở Quảng trường Ba Đình (xem chuyên đề Lời Bác). Không có tư liệu nào cho biết người thợ phụ Nguyễn Tất Thành từng dừng chân trước bức tượng. Nhưng bức tượng thì đã đứng đó từ năm 1856, và vẫn đứng đó cho đến hôm nay.","doc":5},{"loai":"doan","tieu_de":"Hai đầu phố, ba thế kỷ","text":"Đi hết phố School về phía phố Washington, người ta gặp một ngôi nhà gạch nhỏ xây năm 1718, là một trong những tòa nhà cổ nhất còn lại ở trung tâm Boston. Ở thế kỷ XIX, đây là hiệu sách và trụ sở nhà xuất bản Ticknor and Fields, nay quen gọi là Hiệu sách Góc Cũ. Nơi này in sách của những tác giả lớn như Nathaniel Hawthorne, Henry Wadsworth Longfellow, Ralph Waldo Emerson. Chính những nhà văn ấy cũng thường họp mặt ở khách sạn Parker House, đầu kia con phố (xem chuyên đề Khách sạn Parker House).\n\nỞ đầu phố phía Tremont, đối diện khách sạn, là nhà thờ đá King’s Chapel cùng nghĩa trang cổ bên cạnh (xem chuyên đề Nhà thờ King’s Chapel). Chỉ trong vài phút đi bộ, người qua đường đi ngang những công trình của thế kỷ XVIII, XIX và XX. Nếu quả thật làm việc ở Parker House như lời kể, người thanh niên Việt Nam đã sống những tháng mùa đông giữa chính khung cảnh ấy. Đó là một thành phố giữ ký ức về cuộc đấu tranh giành độc lập của mình ở từng góc phố.","doc":6},{"loai":"anh","src":"textures/bang_w/G07_4_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Khách sạn Parker House trên phố School, Boston”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Phía sau những mặt tiền","text":"Khách sạn Parker House năm 1912 là nơi lui tới của chính khách, luật sư, thương gia và giới văn chương Boston. Nằm sát tòa thị chính, cách Tòa nghị viện bang Massachusetts trên đồi Beacon chỉ một quãng đi bộ, khách sạn là chỗ người ta hẹn gặp, bàn chuyện chính trường và làm ăn. Phía sau những phòng ăn sang trọng ấy là cả một thế giới khác: bếp nấu, bếp bánh, kho hàng, nơi làm việc của những người phụ bếp, rửa bát, khuân vác. Ở Boston thời ấy, phần lớn những công việc này do người nhập cư đảm nhận.\n\nTheo lời kể về sau, người thanh niên Nguyễn Tất Thành làm phụ việc trong bếp bánh của khách sạn; công việc hằng ngày ở đó được kể ở chuyên đề Gian bếp bánh. Tấm ảnh năm 2013 chỉ cho thấy mặt tiền. Nhưng chính khoảng cách giữa mặt tiền và gian bếp mới làm nên ý nghĩa của địa chỉ này trong hành trình của Bác. Ở đây, một người dân xứ thuộc địa nhìn nền cộng hòa từ phía những người phục vụ nó, chứ không từ phía những người được phục vụ.","doc":7},{"loai":"ban_co_biet","text":"Mùa đông 1912–1913, người làm việc trong Tòa thị chính cũ đối diện khách sạn Parker House là Thị trưởng John F. Fitzgerald, con trai một gia đình nhập cư gốc Ireland. Ông giữ chức thị trưởng Boston hai lần, lần thứ hai từ năm 1910 đến năm 1914, và là ông ngoại của Tổng thống Mỹ John F. Kennedy sau này.","nguon_ten":"Lưu trữ Thành phố Boston (City of Boston Archives), danh sách các thị trưởng Boston","doc":8},{"loai":"doan","tieu_de":"Đọc một địa chỉ như đọc một tư liệu","text":"Một tấm ảnh chụp địa điểm không phải là bằng chứng cho sự kiện. Tấm ảnh năm 2013 xác nhận rằng khách sạn Parker House có thật, ở đúng góc phố ấy, và đã hoạt động từ năm 1855. Nó không thể xác nhận rằng người thanh niên Nguyễn Tất Thành đã làm việc bên trong. Điều đó được biết qua lời kể của chính Người về sau và qua một bức thư Người gửi cụ Phan Châu Trinh; còn hồ sơ nhân sự của khách sạn không lưu tên Người.\n\nVì vậy, bảo tàng dùng tấm ảnh như một tấm bản đồ, chứ không như một tờ chứng nhận. Nó giúp người xem đặt câu chuyện vào một không gian có thật: một con phố cụ thể, những công trình cụ thể, một thành phố cụ thể của năm 1912. Cách làm ấy cũng là cách các nhà viết tiểu sử nghiêm túc, trong và ngoài nước, vẫn trình bày chặng Mỹ. Điều gì có văn bản thì khẳng định; điều gì chỉ là lời kể thì ghi rõ là lời kể; và nơi chốn thì được mô tả đúng như nó đã và đang tồn tại.","doc":9},{"loai":"anh","src":"textures/bang_w/G07_4_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Khách sạn Parker House trên phố School, Boston”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Người đến Boston hôm nay có thể đứng đúng ở góc phố trong tấm ảnh. Khách sạn vẫn hoạt động dưới tên Omni Parker House, cửa chính mở ra phố School. Bên kia phố là Tòa thị chính cũ với bức tượng Franklin trước sân, cạnh đó là nghĩa trang cổ và nhà thờ King’s Chapel. Đi thêm một đoạn là bức tranh ghép đánh dấu nền Trường Latin Boston, rồi đến Hiệu sách Góc Cũ ở góc phố Washington. Vạch gạch đỏ của Con đường Tự do, tuyến đi bộ nối các di tích thời cách mạng Mỹ, chạy dọc con phố này.\n\nTrong không gian 3D của bảo tàng, góc phố được tái hiện theo diện mạo đầu thế kỷ XX: tuyết phủ mặt đường, đường ray xe điện giữa phố, đèn đường thắp sáng trong chiều tà. Đó là hình dung dựa trên tư liệu chung về Boston thời ấy, không phải bản sao của một tấm ảnh chụp đúng ngày Người có mặt. Đặt cạnh tấm ảnh năm 2013, mô hình ấy giúp người xem thấy cùng một góc phố qua hơn một trăm năm: nhà cửa đã đổi thay, nhưng địa chỉ và câu chuyện vẫn còn.","doc":10}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","William J. Duiker, Ho Chi Minh: A Life (2000)","Tổ chức Con đường Tự do Boston (The Freedom Trail Foundation), tư liệu về các di tích trên phố School","Tư liệu lịch sử Tòa thị chính cũ Boston (Old City Hall)","Omni Parker House – Wikipedia tiếng Anh, https://en.wikipedia.org/wiki/Omni_Parker_House","Ảnh: Robert Linsdell, 1/10/2013, giấy phép CC BY 2.0"],"doc":[{"t":"Phố School, Boston: một góc phố, ba thế kỷ và địa chỉ cụ thể nhất của Bác trên đất Mỹ. Đầu giờ chiều ngày 1/10/2013, một người chụp ảnh đến từ Canada hướng ống kính về khách sạn Parker House ở trung tâm Boston. Tấm ảnh du lịch ấy nay nằm trong một bảo tàng kể về cuộc đời Chủ tịch Hồ Chí Minh. Bởi trên chính khu đất này, theo lời kể, người thanh niên Nguyễn Tất Thành từng làm phụ bếp bánh trong mùa đông 1912–1913 — và con phố nhỏ quanh khách sạn còn giữ dấu vết của gần bốn thế kỷ lịch sử nước Mỹ."},{"t":"Một tấm ảnh của người lữ khách. Theo dữ liệu còn lưu cùng tệp ảnh, tấm ảnh được chụp lúc 13 giờ 21 phút ngày 1/10/2013. Người bấm máy ký tên Robert Linsdell, đến từ thị trấn St. Andrews của Canada. Ông chia sẻ ảnh theo giấy phép Creative Commons CC BY 2.0, cho phép bất kỳ ai sử dụng lại với điều kiện ghi tên tác giả. Nhờ vậy, một tấm ảnh du lịch bình thường đã có thể đi vào phòng trưng bày của bảo tàng. Khung hình hướng về khách sạn Parker House trên phố School, ngay chỗ con phố gặp phố Tremont, giữa khu trung tâm lịch sử của Boston. Cần nói ngay: tòa nhà trong ảnh là tòa nhà được xây dựng lại, hoàn thành năm 1927, chứ không phải tòa nhà mà người thanh niên Việt Nam có thể đã thấy trong mùa đông 1912–1913. Nhưng nền đất vẫn là nền đất ấy, và tên khách sạn vẫn là tên ấy. Lá thư hiếm hoi còn lại từ chặng Mỹ chỉ mang dấu bưu điện New York, không kèm một số nhà nào. Vì thế, trong tất cả những gì được kể về những tháng ngày của Bác trên đất Mỹ, góc phố này là địa chỉ cụ thể nhất có thể chỉ ra trên bản đồ."},{"t":"Con phố mang tên một ngôi trường. Phố School không dài, nối phố Tremont với phố Washington, hai trục đường cổ của trung tâm Boston. Tên phố có từ thời thuộc địa, gắn với Trường Latin Boston, ngôi trường từng đặt trên con phố này. Trường được thành lập ngày 23/4/1635, sớm hơn Đại học Harvard một năm, và được coi là trường công lập lâu đời nhất nước Mỹ. Ngôi trường về sau chuyển đi nơi khác và vẫn hoạt động đến ngày nay. Trên vỉa hè phố School hôm nay, một bức tranh ghép nhiều màu đánh dấu vị trí ngôi trường xưa, và du khách thường dừng chân ở đó. Ngay từ tên gọi, con phố nơi đặt khách sạn Parker House đã gắn với ý niệm trường học công cho trẻ em của cả cộng đồng. Ở xứ An Nam năm 1912, điều ấy còn rất xa vời: trường học là đặc quyền của số ít, và chương trình do chính quyền thuộc địa đặt ra. Người thanh niên Nguyễn Tất Thành hiểu điều đó hơn ai hết. Trước khi xuống tàu ra đi năm 1911, Người từng dạy học ở trường Dục Thanh, Phan Thiết, một ngôi trường do những nhà nho yêu nước lập nên."},{"t":"Bạn có biết? Trong số 56 người ký tên dưới bản Tuyên ngôn Độc lập Hoa Kỳ năm 1776, có năm người từng là học sinh Trường Latin Boston: Samuel Adams, John Hancock, Benjamin Franklin, Robert Treat Paine và William Hooper. Riêng Franklin chỉ học ở đây một thời gian ngắn rồi phải nghỉ để phụ việc cho cha."},{"t":"Tòa thị chính cũ bên kia phố. Bên kia phố School, cạnh nghĩa trang cổ của nhà thờ King’s Chapel, là Tòa thị chính cũ của Boston ở số 45. Tòa nhà được xây trong những năm 1862–1865, do hai kiến trúc sư Gridley J. F. Bryant và Arthur Gilman thiết kế theo phong cách Đế chế thứ hai của Pháp. Đặc trưng dễ nhận ra nhất là mái dốc kiểu Mansard với những ô cửa sổ nhô lên, rất thịnh hành ở Paris thời Napoléon III. Từ năm 1865 đến năm 1969, đây là trụ sở chính quyền thành phố. Như vậy, trong mùa đông 1912–1913, bộ máy cai quản cả thành phố Boston làm việc ngay trước mặt khách sạn Parker House. Một con phố nhỏ chứa trong nó cả những phòng làm việc của thị trưởng, hội đồng thành phố, lẫn những gian bếp nơi người làm thuê nhập cư kiếm sống. Năm 1969, chính quyền Boston chuyển sang tòa thị chính mới. Tòa nhà cũ không bị phá bỏ mà được cải tạo thành văn phòng và nhà hàng, cho nó một đời sống mới. Đó cũng là số phận chung của nhiều công trình quanh góc phố này: được giữ lại, được tiếp tục sử dụng, thay vì bị đóng băng thành hiện vật."},{"t":"Bức tượng Franklin và câu văn về quyền bình đẳng. Trước sân Tòa thị chính cũ là bức tượng đồng Benjamin Franklin, dựng năm 1856, do nhà điêu khắc Richard Saltonstall Greenough thực hiện. Bệ tượng gắn những tấm phù điêu kể lại các chặng đời ông, từ người thợ in đến nhà khoa học và nhà ngoại giao. Franklin sinh năm 1706 ngay tại Boston, trên phố Milk cách đó không xa, trong một gia đình làm nến và xà phòng. Năm 1776, ông là một trong năm người được Quốc hội Lục địa giao soạn thảo bản Tuyên ngôn Độc lập, rồi đặt bút ký dưới văn kiện ấy. Như vậy, chỉ cách cửa khách sạn một quãng ngắn là hình ảnh của một người đã góp tay viết nên câu văn nói rằng mọi người sinh ra đều bình đẳng. Hơn ba mươi năm sau mùa đông ở Boston, chính câu văn ấy sẽ vang lên ở Quảng trường Ba Đình (xem chuyên đề Lời Bác). Không có tư liệu nào cho biết người thợ phụ Nguyễn Tất Thành từng dừng chân trước bức tượng. Nhưng bức tượng thì đã đứng đó từ năm 1856, và vẫn đứng đó cho đến hôm nay."},{"t":"Hai đầu phố, ba thế kỷ. Đi hết phố School về phía phố Washington, người ta gặp một ngôi nhà gạch nhỏ xây năm 1718, là một trong những tòa nhà cổ nhất còn lại ở trung tâm Boston. Ở thế kỷ XIX, đây là hiệu sách và trụ sở nhà xuất bản Ticknor and Fields, nay quen gọi là Hiệu sách Góc Cũ. Nơi này in sách của những tác giả lớn như Nathaniel Hawthorne, Henry Wadsworth Longfellow, Ralph Waldo Emerson. Chính những nhà văn ấy cũng thường họp mặt ở khách sạn Parker House, đầu kia con phố (xem chuyên đề Khách sạn Parker House). Ở đầu phố phía Tremont, đối diện khách sạn, là nhà thờ đá King’s Chapel cùng nghĩa trang cổ bên cạnh (xem chuyên đề Nhà thờ King’s Chapel). Chỉ trong vài phút đi bộ, người qua đường đi ngang những công trình của thế kỷ XVIII, XIX và XX. Nếu quả thật làm việc ở Parker House như lời kể, người thanh niên Việt Nam đã sống những tháng mùa đông giữa chính khung cảnh ấy. Đó là một thành phố giữ ký ức về cuộc đấu tranh giành độc lập của mình ở từng góc phố."},{"t":"Phía sau những mặt tiền. Khách sạn Parker House năm 1912 là nơi lui tới của chính khách, luật sư, thương gia và giới văn chương Boston. Nằm sát tòa thị chính, cách Tòa nghị viện bang Massachusetts trên đồi Beacon chỉ một quãng đi bộ, khách sạn là chỗ người ta hẹn gặp, bàn chuyện chính trường và làm ăn. Phía sau những phòng ăn sang trọng ấy là cả một thế giới khác: bếp nấu, bếp bánh, kho hàng, nơi làm việc của những người phụ bếp, rửa bát, khuân vác. Ở Boston thời ấy, phần lớn những công việc này do người nhập cư đảm nhận. Theo lời kể về sau, người thanh niên Nguyễn Tất Thành làm phụ việc trong bếp bánh của khách sạn; công việc hằng ngày ở đó được kể ở chuyên đề Gian bếp bánh. Tấm ảnh năm 2013 chỉ cho thấy mặt tiền. Nhưng chính khoảng cách giữa mặt tiền và gian bếp mới làm nên ý nghĩa của địa chỉ này trong hành trình của Bác. Ở đây, một người dân xứ thuộc địa nhìn nền cộng hòa từ phía những người phục vụ nó, chứ không từ phía những người được phục vụ."},{"t":"Bạn có biết? Mùa đông 1912–1913, người làm việc trong Tòa thị chính cũ đối diện khách sạn Parker House là Thị trưởng John F. Fitzgerald, con trai một gia đình nhập cư gốc Ireland. Ông giữ chức thị trưởng Boston hai lần, lần thứ hai từ năm 1910 đến năm 1914, và là ông ngoại của Tổng thống Mỹ John F. Kennedy sau này."},{"t":"Đọc một địa chỉ như đọc một tư liệu. Một tấm ảnh chụp địa điểm không phải là bằng chứng cho sự kiện. Tấm ảnh năm 2013 xác nhận rằng khách sạn Parker House có thật, ở đúng góc phố ấy, và đã hoạt động từ năm 1855. Nó không thể xác nhận rằng người thanh niên Nguyễn Tất Thành đã làm việc bên trong. Điều đó được biết qua lời kể của chính Người về sau và qua một bức thư Người gửi cụ Phan Châu Trinh; còn hồ sơ nhân sự của khách sạn không lưu tên Người. Vì vậy, bảo tàng dùng tấm ảnh như một tấm bản đồ, chứ không như một tờ chứng nhận. Nó giúp người xem đặt câu chuyện vào một không gian có thật: một con phố cụ thể, những công trình cụ thể, một thành phố cụ thể của năm 1912. Cách làm ấy cũng là cách các nhà viết tiểu sử nghiêm túc, trong và ngoài nước, vẫn trình bày chặng Mỹ. Điều gì có văn bản thì khẳng định; điều gì chỉ là lời kể thì ghi rõ là lời kể; và nơi chốn thì được mô tả đúng như nó đã và đang tồn tại."},{"t":"Dấu tích hôm nay. Người đến Boston hôm nay có thể đứng đúng ở góc phố trong tấm ảnh. Khách sạn vẫn hoạt động dưới tên Omni Parker House, cửa chính mở ra phố School. Bên kia phố là Tòa thị chính cũ với bức tượng Franklin trước sân, cạnh đó là nghĩa trang cổ và nhà thờ King’s Chapel. Đi thêm một đoạn là bức tranh ghép đánh dấu nền Trường Latin Boston, rồi đến Hiệu sách Góc Cũ ở góc phố Washington. Vạch gạch đỏ của Con đường Tự do, tuyến đi bộ nối các di tích thời cách mạng Mỹ, chạy dọc con phố này. Trong không gian 3D của bảo tàng, góc phố được tái hiện theo diện mạo đầu thế kỷ XX: tuyết phủ mặt đường, đường ray xe điện giữa phố, đèn đường thắp sáng trong chiều tà. Đó là hình dung dựa trên tư liệu chung về Boston thời ấy, không phải bản sao của một tấm ảnh chụp đúng ngày Người có mặt. Đặt cạnh tấm ảnh năm 2013, mô hình ấy giúp người xem thấy cùng một góc phố qua hơn một trăm năm: nhà cửa đã đổi thay, nhưng địa chỉ và câu chuyện vẫn còn."}],"so_chu":1832},{"i":5,"tieu_de_bang":"Mặt tiền khách sạn Parker House ngày nay","tieu_de":"Parker House xưa và nay: một địa chỉ, hai tòa nhà, một trăm bảy mươi năm","sapo":"Tấm ảnh chụp tháng 11/2025 cho thấy mặt tiền một khách sạn vừa tròn một trăm bảy mươi năm tuổi. Nhưng tòa nhà trong ảnh chưa hề tồn tại khi người thợ phụ Nguyễn Tất Thành, theo lời kể, làm việc ở đây. Câu chuyện về hai tòa nhà trên cùng một nền đất giúp ta học cách nhìn một di tích đã đổi hình hài — và cảm nhận độ dài thật của thời gian lịch sử.","bia":{"src":"textures/ht/ht_anh_omni_parker_house_54957839082.jpg","credit":"Ảnh: ajay_suresh · CC BY 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một tấm ảnh tháng 11/2025","text":"Chiều ngày 7/11/2025, một người chụp ảnh ký tên ajay_suresh ghi lại mặt tiền khách sạn Parker House ở Boston và chia sẻ theo giấy phép Creative Commons CC BY 4.0. Thời điểm ấy, khách sạn vừa tròn một trăm bảy mươi năm kể từ ngày khai trương 8/10/1855. Nó cũng vừa khép lại một đợt cải tạo lớn, kéo dài từ tháng 11/2024 đến tháng 8/2025. Tấm ảnh vì thế là một trong những hình ảnh mới nhất của tòa nhà.\n\nĐiều người xem cần biết trước tiên: mặt tiền trong ảnh thuộc về tòa nhà được xây dựng lại, hoàn thành năm 1927. Khi người thanh niên Nguyễn Tất Thành, theo lời kể, làm phụ bếp bánh ở đây trong mùa đông 1912–1913, tòa nhà này chưa có. Người đã rời nước Mỹ khoảng mười bốn năm trước khi nó hoàn thành. Tấm ảnh do đó không cho ta thấy nơi Người từng làm việc, mà cho thấy công trình đã thay thế nơi ấy. Qua đó, nó đặt ra một câu hỏi quen thuộc với mọi bảo tàng: làm sao kể đúng về một di tích đã đổi hình hài?","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_omni_parker_house_54957839082.jpg","chu_thich":"Mặt tiền khách sạn Parker House (nay là Omni Parker House), Boston, ảnh chụp ngày 7/11/2025. Tòa nhà hiện tại được xây dựng lại và hoàn thành năm 1927, khoảng mười bốn năm sau khi Người rời nước Mỹ. Ảnh: ajay_suresh, CC BY 4.0.","credit":"Ảnh: ajay_suresh · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Tòa nhà mà người thợ phụ từng biết","text":"Khách sạn Parker House khai trương ngày 8/10/1855 trên phố School, giữa khu trung tâm Boston. Từ năm 1860, khách sạn liên tục được mở rộng bằng những khối nhà mới, dần chiếm trọn một khu đất giáp các phố Tremont, School, Bosworth và ngõ Chapman. Sau thời người sáng lập Harvey D. Parker và hai người kế nghiệp là Edward O. Punchard, Joseph H. Beckman, từ năm 1891 khách sạn thuộc quyền ông Joseph Reed Whipple. Ông điều hành nó suốt những thập niên đầu thế kỷ XX.\n\nNhư vậy, mùa đông 1912–1913, Parker House đã gần sáu mươi năm tuổi. Đó là một khách sạn thế kỷ XIX thực thụ, gồm những khối nhà ghép lại qua nhiều đợt xây, với gian bếp và lò bánh phục vụ những phòng ăn nổi tiếng nhất thành phố. Không có bức ảnh nào cho thấy người thợ phụ Việt Nam bên trong tòa nhà ấy, cũng không có sổ lương nào ghi tên Người. Những gì còn lại là lời kể về sau của chính Người và một bức thư gửi cụ Phan Châu Trinh. Chừng ấy đủ để gắn câu chuyện với địa chỉ này, nhưng chưa đủ để khẳng định từng chi tiết.","doc":2},{"loai":"doan","tieu_de":"Boston quanh khách sạn năm 1912","text":"Tòa nhà cũ của Parker House khi ấy nằm giữa một thành phố đang hiện đại hóa nhanh. Theo điều tra dân số năm 1910, Boston có khoảng 670.000 dân, là thành phố lớn thứ năm nước Mỹ. Ngay dưới phố Tremont, cách khách sạn vài bước chân, chạy tuyến tàu điện ngầm Tremont khai trương ngày 1/9/1897. Trên mặt phố, xe điện chạy dọc các trục đường lớn, nối trung tâm với các khu dân cư và bến cảng.\n\nBoston cũng là thành phố của người nhập cư. Người Ireland đông nhất, rồi đến người Ý, người Do Thái từ Đông Âu, tìm việc trong nhà máy, bến tàu, công trường và khách sạn. Đầu năm 1912, ở thành phố dệt Lawrence cách Boston không xa, hàng vạn công nhân nhập cư đã bãi công khoảng hai tháng để phản đối việc bị cắt lương. Cuộc bãi công ấy làm chấn động cả nước Mỹ. Một thanh niên châu Á làm phụ bếp trong một khách sạn lớn, như lời kể về Nguyễn Tất Thành, là một phần nhỏ trong bức tranh lao động nhập cư rộng lớn đó.","doc":3},{"loai":"ban_co_biet","text":"Tuyến tàu điện ngầm Tremont chạy ngay gần khách sạn Parker House là tuyến tàu điện ngầm đầu tiên của nước Mỹ, khai trương năm 1897. Hai ga Park Street và Boylston của tuyến này vẫn đón khách đến ngày nay, là những ga tàu điện ngầm cổ nhất nước Mỹ còn hoạt động.","nguon_ten":"Cục Công viên Quốc gia Hoa Kỳ (National Park Service), hồ sơ Di tích lịch sử quốc gia Tremont Street Subway","doc":4},{"loai":"doan","tieu_de":"Mười bốn năm, hai cuộc đổi thay","text":"Giữa thập niên 1920, những khối nhà cũ của Parker House lần lượt bị phá dỡ để nhường chỗ cho một tòa nhà mới, hoàn thành năm 1927 trên cùng khu đất. Mặt tiền trong tấm ảnh năm 2025 là của tòa nhà ấy.\n\nĐặt cạnh cuộc đời người thợ phụ năm nào, quãng mười bốn năm từ mùa đông 1912–1913 đến năm 1927 là một quãng đổi thay lớn. Rời nước Mỹ sang nước Anh năm 1913, rồi sang Pháp, năm 1919 Người ký tên Nguyễn Ái Quốc dưới bản Yêu sách của nhân dân An Nam. Tháng 6/1925, ở Quảng Châu, Người lập Hội Việt Nam Cách mạng Thanh niên. Năm 1927, những bài giảng của Người cho các lớp huấn luyện cán bộ được in thành cuốn Đường Kách mệnh. Khi tòa nhà mới của Parker House mở cửa đón khách, người phụ bếp vô danh trong câu chuyện cũ đã là một nhà cách mạng mà mật thám Pháp ráo riết theo dõi. Hai cuộc đổi thay ấy không liên quan gì với nhau. Nhưng đặt cạnh nhau, chúng giúp người xem cảm nhận được độ dài thật của thời gian lịch sử.","doc":5},{"loai":"anh","src":"textures/bang_w/G07_5_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mặt tiền khách sạn Parker House ngày nay”, nhìn từ xa."},{"loai":"doan","tieu_de":"Qua Đại khủng hoảng và những đời chủ mới","text":"Tòa nhà mới đón khách chưa được bao lâu thì nước Mỹ rơi vào cuộc Đại khủng hoảng kinh tế, bắt đầu từ cuối năm 1929. Năm 1933, giữa những năm khó khăn nhất, khách sạn được ông Glenwood Sherrard mua lại. Cuối thập niên 1960, Parker House về tay gia đình Dunfey, chủ một chuỗi khách sạn, và được cải tạo. Năm 1983, công ty Dunfey mua lại hãng khách sạn Omni rồi tổ chức lại dưới cái tên này. Năm 1996, khách sạn thuộc về tập đoàn TRT Holdings, và ngày nay mang tên Omni Parker House.\n\nQua bấy nhiêu đời chủ, có một điều không thay đổi: không ai bỏ cái tên Parker House. Với một khách sạn đã sống qua hơn một thế kỷ, cái tên ấy là tài sản quý nhất. Nó gắn với những vị khách, những món ăn và những câu chuyện đã thành một phần lịch sử Boston (xem chuyên đề Khách sạn Parker House). Chính nhờ cái tên được giữ nguyên mà câu chuyện về người thợ phụ Việt Nam năm 1912 vẫn tìm được đúng địa chỉ của mình sau hơn một trăm năm.","doc":6},{"loai":"ban_co_biet","text":"Khi khách sạn được xây lại trong thập niên 1920, một cánh nhà của thế kỷ XIX vẫn tiếp tục đón khách trong lúc phần còn lại bị phá dỡ và xây mới. Nhờ vậy, Parker House chưa từng ngừng hoạt động, và đến nay vẫn được giới thiệu là khách sạn hoạt động liên tục lâu đời nhất nước Mỹ.","nguon_ten":"Tư liệu lịch sử của khách sạn Omni Parker House, Boston","doc":7},{"loai":"doan","tieu_de":"Một di sản vẫn đang sống","text":"Ngày nay, Omni Parker House có 551 phòng nghỉ và dãy phòng, nằm trên khu đất rộng khoảng 3.800 mét vuông giáp bốn con phố và ngõ phố. Khách sạn có tên trong Danh mục quốc gia các địa điểm lịch sử của Hoa Kỳ. Nó cũng là thành viên của Hiệp hội Khách sạn lịch sử Hoa Kỳ, một chương trình của Quỹ Quốc gia Bảo tồn Di tích lịch sử. Năm 2009, Hiệp hội Ô tô Hoa Kỳ xếp khách sạn vào nhóm mười khách sạn lịch sử hàng đầu nước Mỹ. Đợt cải tạo gần nhất, từ tháng 11/2024 đến tháng 8/2025, có kinh phí khoảng 65 triệu USD.\n\nNhững con số ấy cho thấy một cách giữ di sản khá phổ biến ở Boston: không đóng băng công trình, mà để nó tiếp tục sống, tiếp tục phục vụ. Tòa nhà năm 1927 nay đã gần trăm tuổi, và chính nó cũng đã trở thành di sản. Người đứng trước mặt tiền hôm nay đang nhìn một công trình lịch sử thứ hai, dựng lên trên nền của công trình thứ nhất — nơi, theo lời kể, người thanh niên Nguyễn Tất Thành từng làm việc.","doc":8},{"loai":"anh","src":"textures/bang_w/G07_5_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mặt tiền khách sạn Parker House ngày nay”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Nhìn một di tích đã đổi hình hài","text":"Không phải nơi nào gắn với Bác cũng còn nguyên hình hài xưa. Có nơi được giữ gần như trọn vẹn; có nơi chỉ còn lại vị trí, cái tên và một câu chuyện cần được kể đúng, không tô vẽ thêm, cũng không bỏ quên. Parker House thuộc loại thứ hai. Với khách tham quan, tấm ảnh mặt tiền là một lời nhắc: đừng nhầm tòa nhà trước mắt với tòa nhà trong câu chuyện.\n\nChính vì thế, gian trưng bày này tái hiện Parker House trong không gian 3D theo diện mạo phố School đầu thế kỷ XX, chứ không theo tòa nhà ngày nay. Mô hình ấy là một hình dung dựa trên tư liệu chung về kiến trúc và đường phố Boston thời kỳ đó. Nó không phải bản sao chính xác của khách sạn năm 1912, vì không có bản vẽ hay tấm ảnh nào chụp đúng mùa đông năm ấy được dùng làm mẫu. Bảo tàng nói rõ điều này, để người xem phân biệt được đâu là tư liệu, đâu là phục dựng, và đâu là lời kể.","doc":9},{"loai":"anh","src":"textures/bang_w/G07_5_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mặt tiền khách sạn Parker House ngày nay”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Khách sạn vẫn hoạt động ở góc phố School và phố Tremont, đối diện nhà thờ đá King’s Chapel, bên kia phố là Tòa thị chính cũ. Du khách có thể bước vào sảnh, ngồi ở nhà hàng của khách sạn, hay đơn giản là đứng trên vỉa hè nhìn lên mặt tiền năm 1927 như trong tấm ảnh. Con đường Tự do, tuyến đi bộ qua các di tích thời cách mạng Mỹ, đi ngang góc phố này, vì vậy mỗi năm có rất đông người qua lại nơi đây.\n\nVới người Việt Nam, địa chỉ ấy mang thêm một lớp nghĩa riêng. Trong các tài liệu giới thiệu lịch sử của khách sạn, tên Hồ Chí Minh được nhắc đến bên cạnh những vị khách và người làm nổi tiếng khác. Nhưng điều đáng nhớ nhất không nằm ở tòa nhà. Nó nằm ở hành trình của người thợ phụ vô danh năm ấy, người đã rời góc phố này, đi qua nhiều năm lao động nơi đất khách, để rồi hơn ba mươi năm sau đọc bản Tuyên ngôn Độc lập của dân tộc mình.","doc":10}],"nguon":["Tư liệu lịch sử của khách sạn Omni Parker House, Boston","Omni Parker House – Wikipedia tiếng Anh, https://en.wikipedia.org/wiki/Omni_Parker_House","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","William J. Duiker, Ho Chi Minh: A Life (2000)","Cục Điều tra dân số Hoa Kỳ (U.S. Census Bureau), số liệu điều tra dân số năm 1910","Ảnh: ajay_suresh, 7/11/2025, giấy phép CC BY 4.0"],"doc":[{"t":"Parker House xưa và nay: một địa chỉ, hai tòa nhà, một trăm bảy mươi năm. Tấm ảnh chụp tháng 11/2025 cho thấy mặt tiền một khách sạn vừa tròn một trăm bảy mươi năm tuổi. Nhưng tòa nhà trong ảnh chưa hề tồn tại khi người thợ phụ Nguyễn Tất Thành, theo lời kể, làm việc ở đây. Câu chuyện về hai tòa nhà trên cùng một nền đất giúp ta học cách nhìn một di tích đã đổi hình hài — và cảm nhận độ dài thật của thời gian lịch sử."},{"t":"Một tấm ảnh tháng 11/2025. Chiều ngày 7/11/2025, một người chụp ảnh ký tên ajay_suresh ghi lại mặt tiền khách sạn Parker House ở Boston và chia sẻ theo giấy phép Creative Commons CC BY 4.0. Thời điểm ấy, khách sạn vừa tròn một trăm bảy mươi năm kể từ ngày khai trương 8/10/1855. Nó cũng vừa khép lại một đợt cải tạo lớn, kéo dài từ tháng 11/2024 đến tháng 8/2025. Tấm ảnh vì thế là một trong những hình ảnh mới nhất của tòa nhà. Điều người xem cần biết trước tiên: mặt tiền trong ảnh thuộc về tòa nhà được xây dựng lại, hoàn thành năm 1927. Khi người thanh niên Nguyễn Tất Thành, theo lời kể, làm phụ bếp bánh ở đây trong mùa đông 1912–1913, tòa nhà này chưa có. Người đã rời nước Mỹ khoảng mười bốn năm trước khi nó hoàn thành. Tấm ảnh do đó không cho ta thấy nơi Người từng làm việc, mà cho thấy công trình đã thay thế nơi ấy. Qua đó, nó đặt ra một câu hỏi quen thuộc với mọi bảo tàng: làm sao kể đúng về một di tích đã đổi hình hài?"},{"t":"Tòa nhà mà người thợ phụ từng biết. Khách sạn Parker House khai trương ngày 8/10/1855 trên phố School, giữa khu trung tâm Boston. Từ năm 1860, khách sạn liên tục được mở rộng bằng những khối nhà mới, dần chiếm trọn một khu đất giáp các phố Tremont, School, Bosworth và ngõ Chapman. Sau thời người sáng lập Harvey D. Parker và hai người kế nghiệp là Edward O. Punchard, Joseph H. Beckman, từ năm 1891 khách sạn thuộc quyền ông Joseph Reed Whipple. Ông điều hành nó suốt những thập niên đầu thế kỷ XX. Như vậy, mùa đông 1912–1913, Parker House đã gần sáu mươi năm tuổi. Đó là một khách sạn thế kỷ XIX thực thụ, gồm những khối nhà ghép lại qua nhiều đợt xây, với gian bếp và lò bánh phục vụ những phòng ăn nổi tiếng nhất thành phố. Không có bức ảnh nào cho thấy người thợ phụ Việt Nam bên trong tòa nhà ấy, cũng không có sổ lương nào ghi tên Người. Những gì còn lại là lời kể về sau của chính Người và một bức thư gửi cụ Phan Châu Trinh. Chừng ấy đủ để gắn câu chuyện với địa chỉ này, nhưng chưa đủ để khẳng định từng chi tiết."},{"t":"Boston quanh khách sạn năm 1912. Tòa nhà cũ của Parker House khi ấy nằm giữa một thành phố đang hiện đại hóa nhanh. Theo điều tra dân số năm 1910, Boston có khoảng 670.000 dân, là thành phố lớn thứ năm nước Mỹ. Ngay dưới phố Tremont, cách khách sạn vài bước chân, chạy tuyến tàu điện ngầm Tremont khai trương ngày 1/9/1897. Trên mặt phố, xe điện chạy dọc các trục đường lớn, nối trung tâm với các khu dân cư và bến cảng. Boston cũng là thành phố của người nhập cư. Người Ireland đông nhất, rồi đến người Ý, người Do Thái từ Đông Âu, tìm việc trong nhà máy, bến tàu, công trường và khách sạn. Đầu năm 1912, ở thành phố dệt Lawrence cách Boston không xa, hàng vạn công nhân nhập cư đã bãi công khoảng hai tháng để phản đối việc bị cắt lương. Cuộc bãi công ấy làm chấn động cả nước Mỹ. Một thanh niên châu Á làm phụ bếp trong một khách sạn lớn, như lời kể về Nguyễn Tất Thành, là một phần nhỏ trong bức tranh lao động nhập cư rộng lớn đó."},{"t":"Bạn có biết? Tuyến tàu điện ngầm Tremont chạy ngay gần khách sạn Parker House là tuyến tàu điện ngầm đầu tiên của nước Mỹ, khai trương năm 1897. Hai ga Park Street và Boylston của tuyến này vẫn đón khách đến ngày nay, là những ga tàu điện ngầm cổ nhất nước Mỹ còn hoạt động."},{"t":"Mười bốn năm, hai cuộc đổi thay. Giữa thập niên 1920, những khối nhà cũ của Parker House lần lượt bị phá dỡ để nhường chỗ cho một tòa nhà mới, hoàn thành năm 1927 trên cùng khu đất. Mặt tiền trong tấm ảnh năm 2025 là của tòa nhà ấy. Đặt cạnh cuộc đời người thợ phụ năm nào, quãng mười bốn năm từ mùa đông 1912–1913 đến năm 1927 là một quãng đổi thay lớn. Rời nước Mỹ sang nước Anh năm 1913, rồi sang Pháp, năm 1919 Người ký tên Nguyễn Ái Quốc dưới bản Yêu sách của nhân dân An Nam. Tháng 6/1925, ở Quảng Châu, Người lập Hội Việt Nam Cách mạng Thanh niên. Năm 1927, những bài giảng của Người cho các lớp huấn luyện cán bộ được in thành cuốn Đường Kách mệnh. Khi tòa nhà mới của Parker House mở cửa đón khách, người phụ bếp vô danh trong câu chuyện cũ đã là một nhà cách mạng mà mật thám Pháp ráo riết theo dõi. Hai cuộc đổi thay ấy không liên quan gì với nhau. Nhưng đặt cạnh nhau, chúng giúp người xem cảm nhận được độ dài thật của thời gian lịch sử."},{"t":"Qua Đại khủng hoảng và những đời chủ mới. Tòa nhà mới đón khách chưa được bao lâu thì nước Mỹ rơi vào cuộc Đại khủng hoảng kinh tế, bắt đầu từ cuối năm 1929. Năm 1933, giữa những năm khó khăn nhất, khách sạn được ông Glenwood Sherrard mua lại. Cuối thập niên 1960, Parker House về tay gia đình Dunfey, chủ một chuỗi khách sạn, và được cải tạo. Năm 1983, công ty Dunfey mua lại hãng khách sạn Omni rồi tổ chức lại dưới cái tên này. Năm 1996, khách sạn thuộc về tập đoàn TRT Holdings, và ngày nay mang tên Omni Parker House. Qua bấy nhiêu đời chủ, có một điều không thay đổi: không ai bỏ cái tên Parker House. Với một khách sạn đã sống qua hơn một thế kỷ, cái tên ấy là tài sản quý nhất. Nó gắn với những vị khách, những món ăn và những câu chuyện đã thành một phần lịch sử Boston (xem chuyên đề Khách sạn Parker House). Chính nhờ cái tên được giữ nguyên mà câu chuyện về người thợ phụ Việt Nam năm 1912 vẫn tìm được đúng địa chỉ của mình sau hơn một trăm năm."},{"t":"Bạn có biết? Khi khách sạn được xây lại trong thập niên 1920, một cánh nhà của thế kỷ XIX vẫn tiếp tục đón khách trong lúc phần còn lại bị phá dỡ và xây mới. Nhờ vậy, Parker House chưa từng ngừng hoạt động, và đến nay vẫn được giới thiệu là khách sạn hoạt động liên tục lâu đời nhất nước Mỹ."},{"t":"Một di sản vẫn đang sống. Ngày nay, Omni Parker House có 551 phòng nghỉ và dãy phòng, nằm trên khu đất rộng khoảng 3.800 mét vuông giáp bốn con phố và ngõ phố. Khách sạn có tên trong Danh mục quốc gia các địa điểm lịch sử của Hoa Kỳ. Nó cũng là thành viên của Hiệp hội Khách sạn lịch sử Hoa Kỳ, một chương trình của Quỹ Quốc gia Bảo tồn Di tích lịch sử. Năm 2009, Hiệp hội Ô tô Hoa Kỳ xếp khách sạn vào nhóm mười khách sạn lịch sử hàng đầu nước Mỹ. Đợt cải tạo gần nhất, từ tháng 11/2024 đến tháng 8/2025, có kinh phí khoảng 65 triệu USD. Những con số ấy cho thấy một cách giữ di sản khá phổ biến ở Boston: không đóng băng công trình, mà để nó tiếp tục sống, tiếp tục phục vụ. Tòa nhà năm 1927 nay đã gần trăm tuổi, và chính nó cũng đã trở thành di sản. Người đứng trước mặt tiền hôm nay đang nhìn một công trình lịch sử thứ hai, dựng lên trên nền của công trình thứ nhất — nơi, theo lời kể, người thanh niên Nguyễn Tất Thành từng làm việc."},{"t":"Nhìn một di tích đã đổi hình hài. Không phải nơi nào gắn với Bác cũng còn nguyên hình hài xưa. Có nơi được giữ gần như trọn vẹn; có nơi chỉ còn lại vị trí, cái tên và một câu chuyện cần được kể đúng, không tô vẽ thêm, cũng không bỏ quên. Parker House thuộc loại thứ hai. Với khách tham quan, tấm ảnh mặt tiền là một lời nhắc: đừng nhầm tòa nhà trước mắt với tòa nhà trong câu chuyện. Chính vì thế, gian trưng bày này tái hiện Parker House trong không gian 3D theo diện mạo phố School đầu thế kỷ XX, chứ không theo tòa nhà ngày nay. Mô hình ấy là một hình dung dựa trên tư liệu chung về kiến trúc và đường phố Boston thời kỳ đó. Nó không phải bản sao chính xác của khách sạn năm 1912, vì không có bản vẽ hay tấm ảnh nào chụp đúng mùa đông năm ấy được dùng làm mẫu. Bảo tàng nói rõ điều này, để người xem phân biệt được đâu là tư liệu, đâu là phục dựng, và đâu là lời kể."},{"t":"Dấu tích hôm nay. Khách sạn vẫn hoạt động ở góc phố School và phố Tremont, đối diện nhà thờ đá King’s Chapel, bên kia phố là Tòa thị chính cũ. Du khách có thể bước vào sảnh, ngồi ở nhà hàng của khách sạn, hay đơn giản là đứng trên vỉa hè nhìn lên mặt tiền năm 1927 như trong tấm ảnh. Con đường Tự do, tuyến đi bộ qua các di tích thời cách mạng Mỹ, đi ngang góc phố này, vì vậy mỗi năm có rất đông người qua lại nơi đây. Với người Việt Nam, địa chỉ ấy mang thêm một lớp nghĩa riêng. Trong các tài liệu giới thiệu lịch sử của khách sạn, tên Hồ Chí Minh được nhắc đến bên cạnh những vị khách và người làm nổi tiếng khác. Nhưng điều đáng nhớ nhất không nằm ở tòa nhà. Nó nằm ở hành trình của người thợ phụ vô danh năm ấy, người đã rời góc phố này, đi qua nhiều năm lao động nơi đất khách, để rồi hơn ba mươi năm sau đọc bản Tuyên ngôn Độc lập của dân tộc mình."}],"so_chu":1745},{"i":6,"tieu_de_bang":"Tất cả mọi người đều sinh ra có quyền bình đẳng","tieu_de":"Từ Philadelphia 1776 đến Ba Đình 1945: hành trình của một câu Tuyên ngôn","sapo":"Chiều 2/9/1945, trước hàng chục vạn đồng bào ở Quảng trường Ba Đình, câu đầu tiên Chủ tịch Hồ Chí Minh đọc sau lời gọi quốc dân lại là một câu văn của nước Mỹ. Câu ấy được viết ở Philadelphia từ năm 1776. Chỉ hai chữ “suy rộng ra” tiếp theo đã biến quyền của mỗi con người thành quyền của mọi dân tộc. Bảy mươi mốt năm sau, chính một Tổng thống Mỹ đã đọc lại câu văn ấy giữa Hà Nội.","bia":{"src":"textures/bai/G07_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Hai giờ chiều ở Ba Đình","text":"Hai giờ chiều ngày 2/9/1945, Quảng trường Ba Đình ở Hà Nội rợp cờ đỏ sao vàng. Hàng chục vạn người đã tề tựu từ sáng: công nhân, nông dân, thanh niên, học sinh, các đội tự vệ, cùng đồng bào từ khắp các vùng quanh Hà Nội. Trên lễ đài dựng giữa quảng trường, Chủ tịch Chính phủ lâm thời Hồ Chí Minh, trong bộ quần áo ka ki giản dị, bước ra trước micro.\n\nNgười bắt đầu bằng lời gọi “Hỡi đồng bào cả nước”, rồi đọc câu mở đầu bản Tuyên ngôn Độc lập. Đang đọc, Người dừng lại và hỏi: “Tôi nói đồng bào nghe rõ không?” Tiếng đáp vang dội cả quảng trường, một khoảnh khắc được nhiều nhân chứng kể lại. Khoảng ba giờ rưỡi chiều, toàn thể đồng bào dự lễ đồng thanh tuyên thệ ủng hộ Chính phủ, giữ vững nền độc lập vừa giành được.","doc":1},{"loai":"trich","text":"Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc. Lời bất hủ ấy ở trong bản Tuyên ngôn Độc lập năm 1776 của nước Mỹ.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Tuyên ngôn Độc lập nước Việt Nam Dân chủ Cộng hòa, Quảng trường Ba Đình, 2/9/1945","doc":2},{"loai":"doan","tieu_de":"Bốn ngày trên căn gác Hàng Ngang","text":"Bản Tuyên ngôn ra đời trong những ngày gấp gáp. Ngày 25/8/1945, Chủ tịch Hồ Chí Minh từ Tân Trào về đến Hà Nội và ở tại ngôi nhà số 48 phố Hàng Ngang, nhà của gia đình ông Trịnh Văn Bô. Ngày 26/8, Người chủ trì cuộc họp Ban Thường vụ Trung ương Đảng ngay tại đây, bàn những việc cấp bách của chính quyền mới. Ngày 27/8, Ủy ban Dân tộc giải phóng được cải tổ thành Chính phủ lâm thời.\n\nTrong hai ngày 28 và 29/8, bên chiếc bàn ăn ở tầng hai, Người viết bản Tuyên ngôn Độc lập. Ngày 30/8, Người mời một số người đến góp ý; ngày 31/8, Người sửa chữa lần cuối. Văn bản không dài, nhưng phải làm hai việc cùng lúc. Nó tuyên bố với quốc dân sự ra đời của một nhà nước mới. Và nó nói với thế giới, trước hết là các nước Đồng minh vừa thắng trận, rằng nền độc lập ấy là chính đáng. Câu mở đầu được chọn chính là để làm việc thứ hai.","doc":3},{"loai":"anh","src":"textures/bang_w/G07_6_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tất cả mọi người đều sinh ra có quyền bình đẳng”, nhìn từ xa."},{"loai":"doan","tieu_de":"Câu văn của Jefferson","text":"Câu văn Người trích đã được viết từ một trăm sáu mươi chín năm trước. Tháng 6/1776, Quốc hội Lục địa của mười ba thuộc địa Bắc Mỹ giao cho năm người soạn thảo bản tuyên ngôn tách khỏi nước Anh: Thomas Jefferson, John Adams, Benjamin Franklin, Roger Sherman và Robert Livingston. Người cầm bút chính là Jefferson, khi ấy ba mươi ba tuổi. Ngày 4/7/1776, bản Tuyên ngôn được thông qua tại Philadelphia.\n\nCâu văn nổi tiếng nhất của nó khẳng định mọi người được tạo ra bình đẳng, được Tạo hóa ban cho những quyền không thể tước bỏ, trong đó có quyền sống, quyền tự do và quyền mưu cầu hạnh phúc. Bản dịch của Chủ tịch Hồ Chí Minh vừa sát nghĩa vừa gần gũi với người Việt. Chữ “Creator” thành “Tạo hóa”, một từ quen thuộc trong tiếng Việt. Cụm “unalienable Rights” thành “những quyền không ai có thể xâm phạm được”. Còn “created equal” được diễn thành “sinh ra có quyền bình đẳng”, nhấn mạnh vào quyền, đúng với tinh thần của cả bản Tuyên ngôn năm 1945.","doc":4},{"loai":"doan","tieu_de":"Sức nặng của hai chữ “suy rộng ra”","text":"Nếu chỉ dẫn lời Jefferson, bản Tuyên ngôn mới dừng ở chỗ trân trọng một lý tưởng. Bước quyết định nằm ở câu tiếp theo. “Suy rộng ra, câu ấy có ý nghĩa là: tất cả các dân tộc trên thế giới đều sinh ra bình đẳng, dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do.”\n\nBản Tuyên ngôn năm 1776 nói về quyền của từng con người. Chủ tịch Hồ Chí Minh nâng nó lên thành quyền của các dân tộc, từ quyền con người đến quyền dân tộc tự quyết. Đó vừa là một bước phát triển tư tưởng, vừa là một lập luận chặt chẽ: một dân tộc bị nô lệ thì mỗi con người trong dân tộc ấy cũng không thể có quyền sống, quyền tự do. Ngay sau đó, Người dẫn lời Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp: “Người ta sinh ra tự do và bình đẳng về quyền lợi; và phải luôn luôn được tự do và bình đẳng về quyền lợi.” Rồi Người kết luận ngắn gọn: “Đó là những lẽ phải không ai chối cãi được.”","doc":5},{"loai":"ban_co_biet","text":"Bản Tuyên ngôn Độc lập ghi văn kiện của Cách mạng Pháp là Tuyên ngôn Nhân quyền và Dân quyền “năm 1791”, dù văn kiện này được thông qua tháng 8/1789. Năm 1791 là năm bản Tuyên ngôn ấy được đặt ở phần mở đầu bản Hiến pháp thành văn đầu tiên của nước Pháp, ban hành tháng 9/1791.","nguon_ten":"Hiến pháp Pháp ngày 3/9/1791; Hội đồng Bảo hiến Pháp (Conseil constitutionnel)","doc":6},{"loai":"doan","tieu_de":"Một lập luận gửi các nước Đồng minh","text":"Chọn mở đầu bằng hai bản tuyên ngôn của Mỹ và Pháp là một lựa chọn có tính toán. Cuối tháng 8/1945, nền độc lập vừa giành được đứng trước nguy cơ lớn. Theo quyết định của các nước Đồng minh, quân đội Trung Hoa Dân quốc sắp vào miền Bắc, quân Anh vào miền Nam để giải giáp quân Nhật, còn thực dân Pháp thì tìm cách quay lại.\n\nNói với thế giới bằng chính những văn kiện lập quốc của Mỹ và Pháp, bản Tuyên ngôn đặt các nước ấy trước một câu hỏi khó né tránh. Nếu tôn trọng lý tưởng của chính mình, làm sao họ có thể phủ nhận quyền độc lập của dân tộc Việt Nam? Người vạch rõ hơn tám mươi năm nay, thực dân Pháp đã “lợi dụng lá cờ tự do, bình đẳng, bác ái, đến cướp đất nước ta, áp bức đồng bào ta”. Người cũng nhắc rằng các nước Đồng minh đã công nhận những nguyên tắc dân tộc bình đẳng ở các hội nghị Tê-hê-răng và Cựu Kim Sơn, nên “quyết không thể không công nhận quyền độc lập của dân Việt Nam”.","doc":7},{"loai":"anh","src":"textures/bang_w/G07_6_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tất cả mọi người đều sinh ra có quyền bình đẳng”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Người sĩ quan Mỹ nghe đọc bản thảo","text":"Những ngày cuối tháng 8/1945, ở Hà Nội có một nhóm sĩ quan tình báo Mỹ thuộc Cơ quan Tình báo chiến lược, thường gọi tắt là OSS. Người đứng đầu là thiếu tá Archimedes Patti, đến Hà Nội ngày 22/8 và nhiều lần gặp Chủ tịch Hồ Chí Minh cùng các cán bộ Việt Minh.\n\nTrong hồi ký “Why Viet Nam?” xuất bản năm 1980, Patti kể rằng ông đã được Chủ tịch Hồ Chí Minh đọc cho nghe một bản thảo Tuyên ngôn. Ông thấy nó nghe rất giống bản Tuyên ngôn Độc lập của nước Mỹ. Một số tư liệu nước ngoài còn cho biết, khi mời mọi người góp ý cho bản Tuyên ngôn ngày 30/8, Người cũng mời cả vài sĩ quan OSS. Những chi tiết này cần được đọc như lời kể của một nhân chứng. Nhưng chúng cho thấy người Mỹ có mặt ở Hà Nội khi ấy đã nhận ra ngay tiếng vọng của văn kiện lập quốc nước mình.","doc":8},{"loai":"doan","tieu_de":"Người thanh niên từng sống ở nước Mỹ","text":"Khi viết câu mở đầu ấy, Chủ tịch Hồ Chí Minh không trích một lý tưởng xa lạ. Hơn ba mươi năm trước, người thanh niên Nguyễn Tất Thành đã sống và làm thuê ở Boston, New York, giữa lòng nền cộng hòa đã sinh ra câu văn đó. Người thấy niềm tự hào của người Mỹ về bản Tuyên ngôn của họ. Người cũng thấy khoảng cách giữa lời tuyên bố và số phận người Mỹ gốc Phi ngay trên đất nước ấy, điều Người sẽ viết thành những bài báo tố cáo năm 1924 (xem chuyên đề “Hành hình kiểu Linsơ”).\n\nVì thế, câu trích dẫn năm 1945 mang hai lớp nghĩa. Lớp thứ nhất là sự trân trọng một giá trị phổ quát mà mọi người, mọi dân tộc đều có thể nhận làm của mình. Lớp thứ hai là một lời nhắc nhẹ nhàng mà kiên quyết: lý tưởng chỉ trọn vẹn khi được thực hiện cho tất cả, chứ không dành riêng cho những dân tộc mạnh.","doc":9},{"loai":"anh","src":"textures/bai/G07_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện gian Nước Mỹ – Boston và New York, nơi đặt bảng Lời Bác.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Những lá thư không được hồi âm","text":"Ngay sau ngày độc lập, trong những tháng cuối năm 1945 và đầu năm 1946, Chủ tịch Hồ Chí Minh nhiều lần gửi thư, điện cho Tổng thống Mỹ Harry Truman và Chính phủ Mỹ. Trong bức thư đề ngày 16/2/1946, Người viết rằng mục tiêu của Việt Nam là độc lập hoàn toàn và hợp tác đầy đủ với Hoa Kỳ. Những lá thư ấy không nhận được hồi âm, và lịch sử đã đi một con đường khác, đau thương hơn nhiều.\n\nGần bảy mươi năm sau, ngày 25/7/2013, tại Nhà Trắng, Chủ tịch nước Trương Tấn Sang trao tặng Tổng thống Barack Obama bản sao bức thư Chủ tịch Hồ Chí Minh gửi Tổng thống Truman. Sau cuộc hội đàm, Tổng thống Obama nói rằng Hồ Chí Minh đã được truyền cảm hứng từ Tuyên ngôn Độc lập và Hiến pháp Hoa Kỳ, từ những lời của Thomas Jefferson.","doc":10},{"loai":"ban_co_biet","text":"Ngày 24/5/2016, tại Trung tâm Hội nghị Quốc gia ở Hà Nội, Tổng thống Mỹ Barack Obama nhắc lại rằng trong ngày Việt Nam tuyên bố độc lập, Hồ Chí Minh đã viện dẫn Tuyên ngôn Độc lập của nước Mỹ. Rồi ông đọc lại trước khán phòng chính câu văn mà Chủ tịch Hồ Chí Minh đã dẫn ở Ba Đình năm 1945.","nguon_ten":"Remarks by President Obama in Address to the People of Vietnam, 24/5/2016, https://obamawhitehouse.archives.gov/the-press-office/2016/05/24/remarks-president-obama-address-people-vietnam","doc":11},{"loai":"doan","tieu_de":"Tiếng vọng của hai chữ “dân tộc”","text":"Ý tưởng “suy rộng ra” của năm 1945 về sau được cộng đồng quốc tế ghi thành văn kiện. Năm 1966, hai Công ước quốc tế, về các quyền dân sự, chính trị và về các quyền kinh tế, xã hội, văn hóa, cùng mở đầu bằng Điều 1: tất cả các dân tộc đều có quyền tự quyết.\n\nKhông thể nói những văn kiện ấy chịu ảnh hưởng trực tiếp từ bản Tuyên ngôn Việt Nam. Nhưng chúng cho thấy lập luận của Chủ tịch Hồ Chí Minh đã đi trước và thuận với dòng chảy của thời đại, khi hàng loạt dân tộc châu Á, châu Phi lần lượt giành độc lập. Ngày nay, du khách có thể đến ngôi nhà 48 Hàng Ngang, nơi Người viết bản Tuyên ngôn, và đứng giữa Quảng trường Ba Đình, nơi câu văn từ Philadelphia từng vang lên lần đầu bằng tiếng Việt.","doc":12},{"loai":"anh","src":"textures/bang_w/G07_6_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tất cả mọi người đều sinh ra có quyền bình đẳng”, nhìn từ trên cao."},{"loai":"trich","text":"Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do độc lập. Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Tuyên ngôn Độc lập nước Việt Nam Dân chủ Cộng hòa, 2/9/1945 – Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","doc":13}],"nguon":["Tuyên ngôn Độc lập nước Việt Nam Dân chủ Cộng hòa, 2/9/1945 – Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Báo Nhân Dân, chuyên đề “Tuyên ngôn Độc lập: Thời khắc lịch sử và ý nghĩa trường tồn”, https://nhandan.vn/special/tuyenngondoclap_ynghia/index.html","Tuyên ngôn Độc lập Hoa Kỳ, 4/7/1776","Archimedes L. A. Patti, Why Viet Nam? Prelude to America’s Albatross (1980)","Remarks by President Obama in Address to the People of Vietnam, 24/5/2016, https://obamawhitehouse.archives.gov/the-press-office/2016/05/24/remarks-president-obama-address-people-vietnam"],"doc":[{"t":"Từ Philadelphia 1776 đến Ba Đình 1945: hành trình của một câu Tuyên ngôn. Chiều 2/9/1945, trước hàng chục vạn đồng bào ở Quảng trường Ba Đình, câu đầu tiên Chủ tịch Hồ Chí Minh đọc sau lời gọi quốc dân lại là một câu văn của nước Mỹ. Câu ấy được viết ở Philadelphia từ năm 1776. Chỉ hai chữ “suy rộng ra” tiếp theo đã biến quyền của mỗi con người thành quyền của mọi dân tộc. Bảy mươi mốt năm sau, chính một Tổng thống Mỹ đã đọc lại câu văn ấy giữa Hà Nội."},{"t":"Hai giờ chiều ở Ba Đình. Hai giờ chiều ngày 2/9/1945, Quảng trường Ba Đình ở Hà Nội rợp cờ đỏ sao vàng. Hàng chục vạn người đã tề tựu từ sáng: công nhân, nông dân, thanh niên, học sinh, các đội tự vệ, cùng đồng bào từ khắp các vùng quanh Hà Nội. Trên lễ đài dựng giữa quảng trường, Chủ tịch Chính phủ lâm thời Hồ Chí Minh, trong bộ quần áo ka ki giản dị, bước ra trước micro. Người bắt đầu bằng lời gọi “Hỡi đồng bào cả nước”, rồi đọc câu mở đầu bản Tuyên ngôn Độc lập. Đang đọc, Người dừng lại và hỏi: “Tôi nói đồng bào nghe rõ không?” Tiếng đáp vang dội cả quảng trường, một khoảnh khắc được nhiều nhân chứng kể lại. Khoảng ba giờ rưỡi chiều, toàn thể đồng bào dự lễ đồng thanh tuyên thệ ủng hộ Chính phủ, giữ vững nền độc lập vừa giành được."},{"t":"Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc. Lời bất hủ ấy ở trong bản Tuyên ngôn Độc lập năm 1776 của nước Mỹ. — Chủ tịch Hồ Chí Minh"},{"t":"Bốn ngày trên căn gác Hàng Ngang. Bản Tuyên ngôn ra đời trong những ngày gấp gáp. Ngày 25/8/1945, Chủ tịch Hồ Chí Minh từ Tân Trào về đến Hà Nội và ở tại ngôi nhà số 48 phố Hàng Ngang, nhà của gia đình ông Trịnh Văn Bô. Ngày 26/8, Người chủ trì cuộc họp Ban Thường vụ Trung ương Đảng ngay tại đây, bàn những việc cấp bách của chính quyền mới. Ngày 27/8, Ủy ban Dân tộc giải phóng được cải tổ thành Chính phủ lâm thời. Trong hai ngày 28 và 29/8, bên chiếc bàn ăn ở tầng hai, Người viết bản Tuyên ngôn Độc lập. Ngày 30/8, Người mời một số người đến góp ý; ngày 31/8, Người sửa chữa lần cuối. Văn bản không dài, nhưng phải làm hai việc cùng lúc. Nó tuyên bố với quốc dân sự ra đời của một nhà nước mới. Và nó nói với thế giới, trước hết là các nước Đồng minh vừa thắng trận, rằng nền độc lập ấy là chính đáng. Câu mở đầu được chọn chính là để làm việc thứ hai."},{"t":"Câu văn của Jefferson. Câu văn Người trích đã được viết từ một trăm sáu mươi chín năm trước. Tháng 6/1776, Quốc hội Lục địa của mười ba thuộc địa Bắc Mỹ giao cho năm người soạn thảo bản tuyên ngôn tách khỏi nước Anh: Thomas Jefferson, John Adams, Benjamin Franklin, Roger Sherman và Robert Livingston. Người cầm bút chính là Jefferson, khi ấy ba mươi ba tuổi. Ngày 4/7/1776, bản Tuyên ngôn được thông qua tại Philadelphia. Câu văn nổi tiếng nhất của nó khẳng định mọi người được tạo ra bình đẳng, được Tạo hóa ban cho những quyền không thể tước bỏ, trong đó có quyền sống, quyền tự do và quyền mưu cầu hạnh phúc. Bản dịch của Chủ tịch Hồ Chí Minh vừa sát nghĩa vừa gần gũi với người Việt. Chữ “Creator” thành “Tạo hóa”, một từ quen thuộc trong tiếng Việt. Cụm “unalienable Rights” thành “những quyền không ai có thể xâm phạm được”. Còn “created equal” được diễn thành “sinh ra có quyền bình đẳng”, nhấn mạnh vào quyền, đúng với tinh thần của cả bản Tuyên ngôn năm 1945."},{"t":"Sức nặng của hai chữ “suy rộng ra”. Nếu chỉ dẫn lời Jefferson, bản Tuyên ngôn mới dừng ở chỗ trân trọng một lý tưởng. Bước quyết định nằm ở câu tiếp theo. “Suy rộng ra, câu ấy có ý nghĩa là: tất cả các dân tộc trên thế giới đều sinh ra bình đẳng, dân tộc nào cũng có quyền sống, quyền sung sướng và quyền tự do.” Bản Tuyên ngôn năm 1776 nói về quyền của từng con người. Chủ tịch Hồ Chí Minh nâng nó lên thành quyền của các dân tộc, từ quyền con người đến quyền dân tộc tự quyết. Đó vừa là một bước phát triển tư tưởng, vừa là một lập luận chặt chẽ: một dân tộc bị nô lệ thì mỗi con người trong dân tộc ấy cũng không thể có quyền sống, quyền tự do. Ngay sau đó, Người dẫn lời Tuyên ngôn Nhân quyền và Dân quyền của Cách mạng Pháp: “Người ta sinh ra tự do và bình đẳng về quyền lợi; và phải luôn luôn được tự do và bình đẳng về quyền lợi.” Rồi Người kết luận ngắn gọn: “Đó là những lẽ phải không ai chối cãi được.”"},{"t":"Bạn có biết? Bản Tuyên ngôn Độc lập ghi văn kiện của Cách mạng Pháp là Tuyên ngôn Nhân quyền và Dân quyền “năm 1791”, dù văn kiện này được thông qua tháng 8/1789. Năm 1791 là năm bản Tuyên ngôn ấy được đặt ở phần mở đầu bản Hiến pháp thành văn đầu tiên của nước Pháp, ban hành tháng 9/1791."},{"t":"Một lập luận gửi các nước Đồng minh. Chọn mở đầu bằng hai bản tuyên ngôn của Mỹ và Pháp là một lựa chọn có tính toán. Cuối tháng 8/1945, nền độc lập vừa giành được đứng trước nguy cơ lớn. Theo quyết định của các nước Đồng minh, quân đội Trung Hoa Dân quốc sắp vào miền Bắc, quân Anh vào miền Nam để giải giáp quân Nhật, còn thực dân Pháp thì tìm cách quay lại. Nói với thế giới bằng chính những văn kiện lập quốc của Mỹ và Pháp, bản Tuyên ngôn đặt các nước ấy trước một câu hỏi khó né tránh. Nếu tôn trọng lý tưởng của chính mình, làm sao họ có thể phủ nhận quyền độc lập của dân tộc Việt Nam? Người vạch rõ hơn tám mươi năm nay, thực dân Pháp đã “lợi dụng lá cờ tự do, bình đẳng, bác ái, đến cướp đất nước ta, áp bức đồng bào ta”. Người cũng nhắc rằng các nước Đồng minh đã công nhận những nguyên tắc dân tộc bình đẳng ở các hội nghị Tê-hê-răng và Cựu Kim Sơn, nên “quyết không thể không công nhận quyền độc lập của dân Việt Nam”."},{"t":"Người sĩ quan Mỹ nghe đọc bản thảo. Những ngày cuối tháng 8/1945, ở Hà Nội có một nhóm sĩ quan tình báo Mỹ thuộc Cơ quan Tình báo chiến lược, thường gọi tắt là OSS. Người đứng đầu là thiếu tá Archimedes Patti, đến Hà Nội ngày 22/8 và nhiều lần gặp Chủ tịch Hồ Chí Minh cùng các cán bộ Việt Minh. Trong hồi ký “Why Viet Nam?” xuất bản năm 1980, Patti kể rằng ông đã được Chủ tịch Hồ Chí Minh đọc cho nghe một bản thảo Tuyên ngôn. Ông thấy nó nghe rất giống bản Tuyên ngôn Độc lập của nước Mỹ. Một số tư liệu nước ngoài còn cho biết, khi mời mọi người góp ý cho bản Tuyên ngôn ngày 30/8, Người cũng mời cả vài sĩ quan OSS. Những chi tiết này cần được đọc như lời kể của một nhân chứng. Nhưng chúng cho thấy người Mỹ có mặt ở Hà Nội khi ấy đã nhận ra ngay tiếng vọng của văn kiện lập quốc nước mình."},{"t":"Người thanh niên từng sống ở nước Mỹ. Khi viết câu mở đầu ấy, Chủ tịch Hồ Chí Minh không trích một lý tưởng xa lạ. Hơn ba mươi năm trước, người thanh niên Nguyễn Tất Thành đã sống và làm thuê ở Boston, New York, giữa lòng nền cộng hòa đã sinh ra câu văn đó. Người thấy niềm tự hào của người Mỹ về bản Tuyên ngôn của họ. Người cũng thấy khoảng cách giữa lời tuyên bố và số phận người Mỹ gốc Phi ngay trên đất nước ấy, điều Người sẽ viết thành những bài báo tố cáo năm 1924 (xem chuyên đề “Hành hình kiểu Linsơ”). Vì thế, câu trích dẫn năm 1945 mang hai lớp nghĩa. Lớp thứ nhất là sự trân trọng một giá trị phổ quát mà mọi người, mọi dân tộc đều có thể nhận làm của mình. Lớp thứ hai là một lời nhắc nhẹ nhàng mà kiên quyết: lý tưởng chỉ trọn vẹn khi được thực hiện cho tất cả, chứ không dành riêng cho những dân tộc mạnh."},{"t":"Những lá thư không được hồi âm. Ngay sau ngày độc lập, trong những tháng cuối năm 1945 và đầu năm 1946, Chủ tịch Hồ Chí Minh nhiều lần gửi thư, điện cho Tổng thống Mỹ Harry Truman và Chính phủ Mỹ. Trong bức thư đề ngày 16/2/1946, Người viết rằng mục tiêu của Việt Nam là độc lập hoàn toàn và hợp tác đầy đủ với Hoa Kỳ. Những lá thư ấy không nhận được hồi âm, và lịch sử đã đi một con đường khác, đau thương hơn nhiều. Gần bảy mươi năm sau, ngày 25/7/2013, tại Nhà Trắng, Chủ tịch nước Trương Tấn Sang trao tặng Tổng thống Barack Obama bản sao bức thư Chủ tịch Hồ Chí Minh gửi Tổng thống Truman. Sau cuộc hội đàm, Tổng thống Obama nói rằng Hồ Chí Minh đã được truyền cảm hứng từ Tuyên ngôn Độc lập và Hiến pháp Hoa Kỳ, từ những lời của Thomas Jefferson."},{"t":"Bạn có biết? Ngày 24/5/2016, tại Trung tâm Hội nghị Quốc gia ở Hà Nội, Tổng thống Mỹ Barack Obama nhắc lại rằng trong ngày Việt Nam tuyên bố độc lập, Hồ Chí Minh đã viện dẫn Tuyên ngôn Độc lập của nước Mỹ. Rồi ông đọc lại trước khán phòng chính câu văn mà Chủ tịch Hồ Chí Minh đã dẫn ở Ba Đình năm 1945."},{"t":"Tiếng vọng của hai chữ “dân tộc”. Ý tưởng “suy rộng ra” của năm 1945 về sau được cộng đồng quốc tế ghi thành văn kiện. Năm 1966, hai Công ước quốc tế, về các quyền dân sự, chính trị và về các quyền kinh tế, xã hội, văn hóa, cùng mở đầu bằng Điều 1: tất cả các dân tộc đều có quyền tự quyết. Không thể nói những văn kiện ấy chịu ảnh hưởng trực tiếp từ bản Tuyên ngôn Việt Nam. Nhưng chúng cho thấy lập luận của Chủ tịch Hồ Chí Minh đã đi trước và thuận với dòng chảy của thời đại, khi hàng loạt dân tộc châu Á, châu Phi lần lượt giành độc lập. Ngày nay, du khách có thể đến ngôi nhà 48 Hàng Ngang, nơi Người viết bản Tuyên ngôn, và đứng giữa Quảng trường Ba Đình, nơi câu văn từ Philadelphia từng vang lên lần đầu bằng tiếng Việt."},{"t":"Nước Việt Nam có quyền hưởng tự do và độc lập, và sự thật đã thành một nước tự do độc lập. Toàn thể dân tộc Việt Nam quyết đem tất cả tinh thần và lực lượng, tính mạng và của cải để giữ vững quyền tự do, độc lập ấy. — Chủ tịch Hồ Chí Minh"}],"so_chu":1867},{"i":7,"tieu_de_bang":"Khách sạn Parker House","tieu_de":"Parker House: nơi nhà văn họp mặt, món bánh ra đời và một người thợ phụ Việt Nam","sapo":"Trước khi gắn với câu chuyện về người thanh niên Nguyễn Tất Thành, Parker House đã là một huyền thoại của Boston. Ở đây, các nhà văn lớn của nước Mỹ họp mặt mỗi tháng, Charles Dickens tập đọc truyện trước tấm gương, và những món bánh mang tên khách sạn lan ra khắp nước Mỹ. Trong danh sách dài những con người gắn với khách sạn, có tên một người phụ bếp châu Á vô danh — người về sau trở thành Chủ tịch nước Việt Nam Dân chủ Cộng hòa.","bia":{"src":"textures/ht/ht_anh_omni_parker_house_school_st_boston_493545_110616.jpg","credit":"Ảnh: Robert Linsdell from St. Andrews, Canada · CC BY 2.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Người đánh xe ngựa và căn quán dưới hầm","text":"Câu chuyện Parker House bắt đầu từ một căn quán ăn dưới tầng hầm. Harvey D. Parker, sinh năm 1805, thuở trẻ làm người đánh xe ngựa cho một bà chủ ở thị trấn Watertown gần Boston. Năm 1832, ông mua lại một quán cà phê nhỏ nằm dưới hầm với giá 432 đô la và đổi tên thành Nhà hàng Parker. Căn quán làm ăn ngày một khá, và người chủ quán bắt đầu nghĩ đến một dự định lớn hơn.\n\nHơn hai mươi năm sau, ngày 8/10/1855, ông khai trương khách sạn Parker House trên phố School, ngay giữa trung tâm Boston. Vị trí ấy được chọn rất khéo: ngay giữa khu hành chính và buôn bán của thành phố, gần trụ sở chính quyền, gần tòa nghị viện bang và những con phố sầm uất nhất. Parker điều hành khách sạn cho đến cuối đời và mất năm 1884. Từ một căn quán hầm đến một khách sạn danh tiếng, con đường của ông là một câu chuyện điển hình của Boston thế kỷ XIX, thành phố của những người tự lập thân bằng đôi tay mình. Những đời chủ tiếp theo và các lần xây lại của khách sạn được kể ở chuyên đề Mặt tiền khách sạn Parker House ngày nay.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_omni_parker_house_school_st_boston_493545_110616.jpg","chu_thich":"Khách sạn Parker House ở phố School, Boston, ảnh chụp năm 2013. Khai trương năm 1855, đây là nơi các nhà văn lớn của nước Mỹ họp mặt, nơi ra đời bánh mì Parker House và bánh kem Boston. Ảnh: Robert Linsdell, CC BY 2.0.","credit":"Ảnh: Robert Linsdell from St. Andrews, Canada · CC BY 2.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Câu lạc bộ Thứ Bảy","text":"Chỉ vài năm sau ngày khai trương, Parker House đã trở thành nơi họp mặt của giới trí thức Boston. Câu lạc bộ Thứ Bảy chọn khách sạn làm chỗ họp mỗi tháng một lần vào ngày thứ Bảy, trừ những tháng hè. Quanh bàn ăn là những tên tuổi lớn của văn chương và tư tưởng Mỹ thế kỷ XIX. Đó là nhà tư tưởng Ralph Waldo Emerson, các nhà thơ Henry Wadsworth Longfellow, James Russell Lowell, John Greenleaf Whittier, nhà văn Nathaniel Hawthorne. Cùng ngồi với họ còn có nhà văn kiêm thầy thuốc Oliver Wendell Holmes, nhà sử học Francis Parkman, nhà giáo dục Amos Bronson Alcott và nhà ngoại giao Charles Francis Adams.\n\nTừ những cuộc gặp gỡ trong giới này, tạp chí The Atlantic Monthly ra đời ở Boston năm 1857, với Lowell là tổng biên tập đầu tiên. Không ít thành viên câu lạc bộ là những người phản đối chế độ nô lệ; Whittier là nhà thơ nổi tiếng của phong trào bãi nô. Như vậy, từ nửa thế kỷ trước khi có câu chuyện về người thợ phụ Việt Nam, các phòng ăn của Parker House đã nghe nhiều cuộc bàn luận về tự do và phẩm giá con người.","doc":2},{"loai":"doan","tieu_de":"Charles Dickens và tấm gương","text":"Vị khách nổi tiếng nhất của Parker House thế kỷ XIX có lẽ là nhà văn Anh Charles Dickens. Trong chuyến đi đọc tác phẩm trước công chúng ở Mỹ những năm 1867–1868, Dickens lưu trú tại khách sạn trong một dãy phòng riêng. Theo tư liệu của khách sạn, ông đã đọc truyện “Bài ca Giáng sinh” cho các thành viên Câu lạc bộ Thứ Bảy nghe ngay tại Parker House. Sau đó ông mới đọc trước công chúng ở hội trường Tremont Temple gần đó.\n\nDickens chuẩn bị các buổi đọc rất kỹ, luyện giọng và nét mặt trước gương như một diễn viên. Khách sạn đến nay vẫn giữ cánh cửa căn phòng Dickens từng ở và tấm gương ông dùng để tập đọc. Đó là những hiện vật thật mà du khách có thể tận mắt nhìn thấy. Dickens là tác giả của “Oliver Twist”, “Những kỳ vọng lớn lao”, nhà văn đã viết nhiều về thân phận trẻ em nghèo và người lao động ở London thời công nghiệp. Đó cũng là thế giới người thanh niên Nguyễn Tất Thành sẽ bước vào khi rời nước Mỹ sang nước Anh năm 1913.","doc":3},{"loai":"ban_co_biet","text":"Parker House còn gắn với một trang u tối của lịch sử nước Mỹ. Diễn viên John Wilkes Booth từng ở khách sạn trong hai ngày 5 và 6/4/1865, và được thấy tập bắn ở một trường bắn gần đó. Tám ngày sau, ngày 14/4/1865, Booth ám sát Tổng thống Abraham Lincoln tại Washington.","nguon_ten":"Tư liệu lịch sử của khách sạn Omni Parker House, Boston","doc":4},{"loai":"doan","tieu_de":"Những món bánh mang tên khách sạn","text":"Nếu các nhà văn làm nên danh tiếng cho phòng khách của Parker House, thì chính gian bếp làm nên danh tiếng cho bàn ăn của nó. Năm 1856, chỉ một năm sau ngày khai trương, một đầu bếp người Pháp của khách sạn tạo ra món bánh gồm hai lớp bánh bông lan kẹp kem sữa trứng, phủ sô-cô-la bên trên. Món bánh về sau được gọi là bánh kem Boston, và năm 1996 được bang Massachusetts chọn làm món tráng miệng chính thức của bang.\n\nNổi tiếng không kém là bánh mì Parker House: những chiếc bánh mì mềm, gấp đôi lại như chiếc ví nhỏ, ra đời trong bếp khách sạn vào nửa sau thế kỷ XIX. Tương truyền, một người thợ làm bánh gốc Đức đang bực bội đã ném mẻ bánh chưa nặn xong vào lò. Khi lấy ra, những chiếc bánh có hình gấp đôi đặc trưng. Theo tư liệu của khách sạn, công thức bánh được giữ kín suốt nhiều thập niên. Chỉ đến năm 1933, khi Tổng thống Franklin D. Roosevelt muốn có món bánh này cho một bữa tiệc ở Nhà Trắng, công thức mới được trao ra ngoài.","doc":5},{"loai":"anh","src":"textures/bang_w/G07_7_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Khách sạn Parker House”, nhìn từ xa."},{"loai":"doan","tieu_de":"Gian bếp của những người làm thuê","text":"Một khách sạn lớn với những phòng ăn nổi tiếng như thế cần một đội ngũ đông đảo thợ bếp, thợ bánh và người phụ việc. Đầu thế kỷ XX, phần lớn lao động phục vụ trong các khách sạn Boston là người nhập cư (xem chuyên đề Mặt tiền khách sạn Parker House ngày nay). Họ làm việc trong những gian bếp mà thực khách ở phòng ăn không bao giờ nhìn thấy.\n\nTheo lời kể về sau của chính Người và một bức thư gửi cụ Phan Châu Trinh, người thanh niên Nguyễn Tất Thành đã là một trong những người thợ phụ trong bếp bánh của Parker House vào mùa đông 1912–1913. Những việc cụ thể của người thợ phụ bánh thời ấy được kể ở chuyên đề Gian bếp bánh. Ở đây chỉ cần nhớ một điều. Nếu lời kể ấy đúng, thì những mẻ bánh mì Parker House mùa đông năm ấy, món bánh đã nổi tiếng khắp nước Mỹ, có công của một người thanh niên Việt Nam hai mươi hai tuổi. Khi ấy, không ai trong khách sạn biết người thợ phụ lặng lẽ ấy rồi sẽ trở thành ai.","doc":6},{"loai":"doan","tieu_de":"Những người làm công trở thành huyền thoại","text":"Ngày nay, khi kể lịch sử của mình, Parker House thường nhắc đến những người từng làm việc trong bếp và phòng ăn của khách sạn, về sau trở nên nổi tiếng theo những cách rất khác nhau. Người thứ nhất là Hồ Chí Minh, người theo lời kể đã làm thợ phụ bánh ở đây trong những năm 1912–1913. Người thứ hai là Malcolm Little, một thanh niên da đen làm bồi bàn ở khách sạn vào thập niên 1940. Về sau, ông trở thành Malcolm X, nhà hoạt động nổi tiếng trong cuộc đấu tranh vì quyền của người Mỹ gốc Phi. Người thứ ba là Emeril Lagasse, làm bếp phó ở đây những năm 1979–1981, sau trở thành một trong những đầu bếp nổi tiếng nhất nước Mỹ.\n\nHai cái tên đầu đặc biệt đáng suy ngẫm. Cách nhau khoảng ba mươi năm, một người thanh niên xứ thuộc địa và một người thanh niên da đen đã làm những công việc phục vụ giản đơn nhất trong cùng một khách sạn sang trọng. Rồi cả hai cùng dấn thân đấu tranh cho những con người bị áp bức, mỗi người trên con đường của mình.","doc":7},{"loai":"ban_co_biet","text":"Theo tư liệu của khách sạn, chính Parker House đã đặt ra từ “scrod” trong thực đơn. Đó không phải tên một loài cá, mà là cách gọi món cá thịt trắng tươi nhất, non nhất đánh bắt trong ngày. Từ này về sau trở nên quen thuộc trong các nhà hàng vùng New England.","nguon_ten":"Tư liệu lịch sử của khách sạn Omni Parker House, Boston","doc":8},{"loai":"doan","tieu_de":"Gia đình Kennedy và bàn số 40","text":"Thế kỷ XX tiếp tục đưa đến Parker House những vị khách gắn với lịch sử nước Mỹ. Năm 1946, John F. Kennedy, khi ấy là một cựu binh trẻ vừa trở về từ Chiến tranh thế giới thứ hai, chọn khách sạn để tuyên bố ra tranh cử vào Hạ viện Mỹ. Năm 1953, bữa tiệc chia tay đời độc thân của ông được tổ chức trong Phòng Báo chí của khách sạn. Tương truyền, ông đã cầu hôn Jacqueline Bouvier tại bàn số 40 trong nhà hàng Parker’s của khách sạn.\n\nMối duyên của gia đình Kennedy với góc phố này còn có từ trước. Ông ngoại của ông, John F. Fitzgerald, là Thị trưởng Boston làm việc ở Tòa thị chính cũ bên kia phố, đúng vào mùa đông 1912–1913 (xem chuyên đề Khách sạn Parker House trên phố School, Boston). Những câu chuyện ấy cho thấy Parker House không chỉ là nơi nghỉ chân. Suốt hơn một thế kỷ, khách sạn là một phần đời sống chính trị và xã hội của Boston, nơi những quyết định và những cuộc gặp gỡ quan trọng diễn ra quanh bàn ăn.","doc":9},{"loai":"anh","src":"textures/bang_w/G07_7_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Khách sạn Parker House”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Tên Hồ Chí Minh trong lịch sử khách sạn","text":"Trong các tài liệu giới thiệu lịch sử Parker House, tên Hồ Chí Minh thường được nhắc bên cạnh Dickens, Emerson hay Kennedy. Người đọc cần hiểu chi tiết ấy một cách chính xác. Câu chuyện Người làm thợ phụ bánh ở đây được biết qua lời kể của chính Người về sau và qua một bức thư gửi cụ Phan Châu Trinh. Còn hồ sơ nhân sự của khách sạn thì không lưu tên Người. Các nhà viết tiểu sử nghiêm túc, trong và ngoài nước, vì thế đều trình bày chi tiết này kèm những chữ “theo lời kể”.\n\nĐiều đó không làm câu chuyện kém giá trị. Nó chỉ nhắc rằng một người thợ phụ châu Á năm 1912 là người vô danh, không ai nghĩ phải ghi chép về người ấy. Chính sự vô danh ấy là một phần của câu chuyện. Con đường tìm đường cứu nước của Người đi qua những nơi mà người đời chỉ thấy phòng ăn sang trọng, còn gian bếp thì bị lãng quên. Hơn một thế kỷ sau, khi khách sạn nhắc tên Người trong lịch sử của mình, gian bếp ấy đã được nhớ đến.","doc":10},{"loai":"anh","src":"textures/bang_w/G07_7_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Khách sạn Parker House”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Khách sạn ngày nay mang tên Omni Parker House, vẫn hoạt động ở góc phố School và phố Tremont, đối diện nhà thờ King’s Chapel. Du khách có thể bước vào sảnh, ghé nhà hàng Parker’s để nếm thử bánh mì Parker House và bánh kem Boston ngay tại nơi chúng ra đời. Tấm gương của Dickens vẫn được khách sạn gìn giữ và trưng bày. Khách sạn là thành viên của Hiệp hội Khách sạn lịch sử Hoa Kỳ và có tên trong Danh mục quốc gia các địa điểm lịch sử.\n\nTrong không gian 3D của bảo tàng, Parker House được tái hiện theo diện mạo phố School đầu thế kỷ XX. Gian bếp bánh bên cạnh được phục dựng theo hình dung chung về một bếp bánh thời ấy, với lò gạch, bàn nhồi bột và khay bánh. Đó không phải bản sao một căn phòng đã được ghi chép, và bảo tàng nói rõ điều này. Đứng trước mô hình, người xem có thể hình dung một buổi sáng mùa đông ở Boston hơn một thế kỷ trước, khi, theo lời kể, một người thanh niên Việt Nam làm việc giữa hơi nóng của lò bánh.","doc":11}],"nguon":["Tư liệu lịch sử của khách sạn Omni Parker House, Boston","Omni Parker House – Wikipedia tiếng Anh, https://en.wikipedia.org/wiki/Omni_Parker_House","William J. Duiker, Ho Chi Minh: A Life (2000)","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hiệp hội Khách sạn lịch sử Hoa Kỳ (Historic Hotels of America)"],"doc":[{"t":"Parker House: nơi nhà văn họp mặt, món bánh ra đời và một người thợ phụ Việt Nam. Trước khi gắn với câu chuyện về người thanh niên Nguyễn Tất Thành, Parker House đã là một huyền thoại của Boston. Ở đây, các nhà văn lớn của nước Mỹ họp mặt mỗi tháng, Charles Dickens tập đọc truyện trước tấm gương, và những món bánh mang tên khách sạn lan ra khắp nước Mỹ. Trong danh sách dài những con người gắn với khách sạn, có tên một người phụ bếp châu Á vô danh — người về sau trở thành Chủ tịch nước Việt Nam Dân chủ Cộng hòa."},{"t":"Người đánh xe ngựa và căn quán dưới hầm. Câu chuyện Parker House bắt đầu từ một căn quán ăn dưới tầng hầm. Harvey D. Parker, sinh năm 1805, thuở trẻ làm người đánh xe ngựa cho một bà chủ ở thị trấn Watertown gần Boston. Năm 1832, ông mua lại một quán cà phê nhỏ nằm dưới hầm với giá 432 đô la và đổi tên thành Nhà hàng Parker. Căn quán làm ăn ngày một khá, và người chủ quán bắt đầu nghĩ đến một dự định lớn hơn. Hơn hai mươi năm sau, ngày 8/10/1855, ông khai trương khách sạn Parker House trên phố School, ngay giữa trung tâm Boston. Vị trí ấy được chọn rất khéo: ngay giữa khu hành chính và buôn bán của thành phố, gần trụ sở chính quyền, gần tòa nghị viện bang và những con phố sầm uất nhất. Parker điều hành khách sạn cho đến cuối đời và mất năm 1884. Từ một căn quán hầm đến một khách sạn danh tiếng, con đường của ông là một câu chuyện điển hình của Boston thế kỷ XIX, thành phố của những người tự lập thân bằng đôi tay mình. Những đời chủ tiếp theo và các lần xây lại của khách sạn được kể ở chuyên đề Mặt tiền khách sạn Parker House ngày nay."},{"t":"Câu lạc bộ Thứ Bảy. Chỉ vài năm sau ngày khai trương, Parker House đã trở thành nơi họp mặt của giới trí thức Boston. Câu lạc bộ Thứ Bảy chọn khách sạn làm chỗ họp mỗi tháng một lần vào ngày thứ Bảy, trừ những tháng hè. Quanh bàn ăn là những tên tuổi lớn của văn chương và tư tưởng Mỹ thế kỷ XIX. Đó là nhà tư tưởng Ralph Waldo Emerson, các nhà thơ Henry Wadsworth Longfellow, James Russell Lowell, John Greenleaf Whittier, nhà văn Nathaniel Hawthorne. Cùng ngồi với họ còn có nhà văn kiêm thầy thuốc Oliver Wendell Holmes, nhà sử học Francis Parkman, nhà giáo dục Amos Bronson Alcott và nhà ngoại giao Charles Francis Adams. Từ những cuộc gặp gỡ trong giới này, tạp chí The Atlantic Monthly ra đời ở Boston năm 1857, với Lowell là tổng biên tập đầu tiên. Không ít thành viên câu lạc bộ là những người phản đối chế độ nô lệ; Whittier là nhà thơ nổi tiếng của phong trào bãi nô. Như vậy, từ nửa thế kỷ trước khi có câu chuyện về người thợ phụ Việt Nam, các phòng ăn của Parker House đã nghe nhiều cuộc bàn luận về tự do và phẩm giá con người."},{"t":"Charles Dickens và tấm gương. Vị khách nổi tiếng nhất của Parker House thế kỷ XIX có lẽ là nhà văn Anh Charles Dickens. Trong chuyến đi đọc tác phẩm trước công chúng ở Mỹ những năm 1867–1868, Dickens lưu trú tại khách sạn trong một dãy phòng riêng. Theo tư liệu của khách sạn, ông đã đọc truyện “Bài ca Giáng sinh” cho các thành viên Câu lạc bộ Thứ Bảy nghe ngay tại Parker House. Sau đó ông mới đọc trước công chúng ở hội trường Tremont Temple gần đó. Dickens chuẩn bị các buổi đọc rất kỹ, luyện giọng và nét mặt trước gương như một diễn viên. Khách sạn đến nay vẫn giữ cánh cửa căn phòng Dickens từng ở và tấm gương ông dùng để tập đọc. Đó là những hiện vật thật mà du khách có thể tận mắt nhìn thấy. Dickens là tác giả của “Oliver Twist”, “Những kỳ vọng lớn lao”, nhà văn đã viết nhiều về thân phận trẻ em nghèo và người lao động ở London thời công nghiệp. Đó cũng là thế giới người thanh niên Nguyễn Tất Thành sẽ bước vào khi rời nước Mỹ sang nước Anh năm 1913."},{"t":"Bạn có biết? Parker House còn gắn với một trang u tối của lịch sử nước Mỹ. Diễn viên John Wilkes Booth từng ở khách sạn trong hai ngày 5 và 6/4/1865, và được thấy tập bắn ở một trường bắn gần đó. Tám ngày sau, ngày 14/4/1865, Booth ám sát Tổng thống Abraham Lincoln tại Washington."},{"t":"Những món bánh mang tên khách sạn. Nếu các nhà văn làm nên danh tiếng cho phòng khách của Parker House, thì chính gian bếp làm nên danh tiếng cho bàn ăn của nó. Năm 1856, chỉ một năm sau ngày khai trương, một đầu bếp người Pháp của khách sạn tạo ra món bánh gồm hai lớp bánh bông lan kẹp kem sữa trứng, phủ sô-cô-la bên trên. Món bánh về sau được gọi là bánh kem Boston, và năm 1996 được bang Massachusetts chọn làm món tráng miệng chính thức của bang. Nổi tiếng không kém là bánh mì Parker House: những chiếc bánh mì mềm, gấp đôi lại như chiếc ví nhỏ, ra đời trong bếp khách sạn vào nửa sau thế kỷ XIX. Tương truyền, một người thợ làm bánh gốc Đức đang bực bội đã ném mẻ bánh chưa nặn xong vào lò. Khi lấy ra, những chiếc bánh có hình gấp đôi đặc trưng. Theo tư liệu của khách sạn, công thức bánh được giữ kín suốt nhiều thập niên. Chỉ đến năm 1933, khi Tổng thống Franklin D. Roosevelt muốn có món bánh này cho một bữa tiệc ở Nhà Trắng, công thức mới được trao ra ngoài."},{"t":"Gian bếp của những người làm thuê. Một khách sạn lớn với những phòng ăn nổi tiếng như thế cần một đội ngũ đông đảo thợ bếp, thợ bánh và người phụ việc. Đầu thế kỷ XX, phần lớn lao động phục vụ trong các khách sạn Boston là người nhập cư (xem chuyên đề Mặt tiền khách sạn Parker House ngày nay). Họ làm việc trong những gian bếp mà thực khách ở phòng ăn không bao giờ nhìn thấy. Theo lời kể về sau của chính Người và một bức thư gửi cụ Phan Châu Trinh, người thanh niên Nguyễn Tất Thành đã là một trong những người thợ phụ trong bếp bánh của Parker House vào mùa đông 1912–1913. Những việc cụ thể của người thợ phụ bánh thời ấy được kể ở chuyên đề Gian bếp bánh. Ở đây chỉ cần nhớ một điều. Nếu lời kể ấy đúng, thì những mẻ bánh mì Parker House mùa đông năm ấy, món bánh đã nổi tiếng khắp nước Mỹ, có công của một người thanh niên Việt Nam hai mươi hai tuổi. Khi ấy, không ai trong khách sạn biết người thợ phụ lặng lẽ ấy rồi sẽ trở thành ai."},{"t":"Những người làm công trở thành huyền thoại. Ngày nay, khi kể lịch sử của mình, Parker House thường nhắc đến những người từng làm việc trong bếp và phòng ăn của khách sạn, về sau trở nên nổi tiếng theo những cách rất khác nhau. Người thứ nhất là Hồ Chí Minh, người theo lời kể đã làm thợ phụ bánh ở đây trong những năm 1912–1913. Người thứ hai là Malcolm Little, một thanh niên da đen làm bồi bàn ở khách sạn vào thập niên 1940. Về sau, ông trở thành Malcolm X, nhà hoạt động nổi tiếng trong cuộc đấu tranh vì quyền của người Mỹ gốc Phi. Người thứ ba là Emeril Lagasse, làm bếp phó ở đây những năm 1979–1981, sau trở thành một trong những đầu bếp nổi tiếng nhất nước Mỹ. Hai cái tên đầu đặc biệt đáng suy ngẫm. Cách nhau khoảng ba mươi năm, một người thanh niên xứ thuộc địa và một người thanh niên da đen đã làm những công việc phục vụ giản đơn nhất trong cùng một khách sạn sang trọng. Rồi cả hai cùng dấn thân đấu tranh cho những con người bị áp bức, mỗi người trên con đường của mình."},{"t":"Bạn có biết? Theo tư liệu của khách sạn, chính Parker House đã đặt ra từ “scrod” trong thực đơn. Đó không phải tên một loài cá, mà là cách gọi món cá thịt trắng tươi nhất, non nhất đánh bắt trong ngày. Từ này về sau trở nên quen thuộc trong các nhà hàng vùng New England."},{"t":"Gia đình Kennedy và bàn số 40. Thế kỷ XX tiếp tục đưa đến Parker House những vị khách gắn với lịch sử nước Mỹ. Năm 1946, John F. Kennedy, khi ấy là một cựu binh trẻ vừa trở về từ Chiến tranh thế giới thứ hai, chọn khách sạn để tuyên bố ra tranh cử vào Hạ viện Mỹ. Năm 1953, bữa tiệc chia tay đời độc thân của ông được tổ chức trong Phòng Báo chí của khách sạn. Tương truyền, ông đã cầu hôn Jacqueline Bouvier tại bàn số 40 trong nhà hàng Parker’s của khách sạn. Mối duyên của gia đình Kennedy với góc phố này còn có từ trước. Ông ngoại của ông, John F. Fitzgerald, là Thị trưởng Boston làm việc ở Tòa thị chính cũ bên kia phố, đúng vào mùa đông 1912–1913 (xem chuyên đề Khách sạn Parker House trên phố School, Boston). Những câu chuyện ấy cho thấy Parker House không chỉ là nơi nghỉ chân. Suốt hơn một thế kỷ, khách sạn là một phần đời sống chính trị và xã hội của Boston, nơi những quyết định và những cuộc gặp gỡ quan trọng diễn ra quanh bàn ăn."},{"t":"Tên Hồ Chí Minh trong lịch sử khách sạn. Trong các tài liệu giới thiệu lịch sử Parker House, tên Hồ Chí Minh thường được nhắc bên cạnh Dickens, Emerson hay Kennedy. Người đọc cần hiểu chi tiết ấy một cách chính xác. Câu chuyện Người làm thợ phụ bánh ở đây được biết qua lời kể của chính Người về sau và qua một bức thư gửi cụ Phan Châu Trinh. Còn hồ sơ nhân sự của khách sạn thì không lưu tên Người. Các nhà viết tiểu sử nghiêm túc, trong và ngoài nước, vì thế đều trình bày chi tiết này kèm những chữ “theo lời kể”. Điều đó không làm câu chuyện kém giá trị. Nó chỉ nhắc rằng một người thợ phụ châu Á năm 1912 là người vô danh, không ai nghĩ phải ghi chép về người ấy. Chính sự vô danh ấy là một phần của câu chuyện. Con đường tìm đường cứu nước của Người đi qua những nơi mà người đời chỉ thấy phòng ăn sang trọng, còn gian bếp thì bị lãng quên. Hơn một thế kỷ sau, khi khách sạn nhắc tên Người trong lịch sử của mình, gian bếp ấy đã được nhớ đến."},{"t":"Dấu tích hôm nay. Khách sạn ngày nay mang tên Omni Parker House, vẫn hoạt động ở góc phố School và phố Tremont, đối diện nhà thờ King’s Chapel. Du khách có thể bước vào sảnh, ghé nhà hàng Parker’s để nếm thử bánh mì Parker House và bánh kem Boston ngay tại nơi chúng ra đời. Tấm gương của Dickens vẫn được khách sạn gìn giữ và trưng bày. Khách sạn là thành viên của Hiệp hội Khách sạn lịch sử Hoa Kỳ và có tên trong Danh mục quốc gia các địa điểm lịch sử. Trong không gian 3D của bảo tàng, Parker House được tái hiện theo diện mạo phố School đầu thế kỷ XX. Gian bếp bánh bên cạnh được phục dựng theo hình dung chung về một bếp bánh thời ấy, với lò gạch, bàn nhồi bột và khay bánh. Đó không phải bản sao một căn phòng đã được ghi chép, và bảo tàng nói rõ điều này. Đứng trước mô hình, người xem có thể hình dung một buổi sáng mùa đông ở Boston hơn một thế kỷ trước, khi, theo lời kể, một người thanh niên Việt Nam làm việc giữa hơi nóng của lò bánh."}],"so_chu":2006},{"i":8,"tieu_de_bang":"Gian bếp bánh","tieu_de":"Gian bếp bánh ở Boston: bột, lửa và đôi tay người thợ phụ mùa đông 1912 – 1913","sapo":"Trước khi khách của khách sạn Parker House thức dậy, bánh mì trên bàn ăn sáng của họ đã phải được nhào, ủ và nướng xong. Theo lời kể về sau, trong mùa đông 1912 – 1913, giữa những người thợ làm việc từ lúc trời còn tối ấy có một thanh niên châu Á hai mươi hai tuổi. Gian bếp bánh phục dựng trong không gian 3D mời người xem bước vào công việc của anh: một nghề không tên tuổi, nhưng đã nuôi anh trên con đường tìm đường cứu nước.","bia":{"src":"textures/bai/G07_v5.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Trước khi trời sáng","text":"Bên ngoài là mùa đông Boston, gió lạnh thổi dọc những con phố, tuyết đọng thành vệt bên lề đường. Bên trong gian bếp bánh, lò gạch đã đỏ lửa từ nhiều giờ trước. Trên chiếc bàn gỗ dài, những khối bột được nhào, chia, cán mỏng; trên giá, từng khay bánh xếp chờ vào lò. Đó là cảnh người xem gặp khi bước vào gian bếp tái hiện trong không gian 3D.\n\nCần nói rõ ngay từ đầu: gian bếp này không phải bản sao của một căn phòng đã được ghi chép. Không có bản vẽ hay tấm ảnh nào cho biết bếp bánh của Parker House năm 1912 trông ra sao, và tòa nhà khách sạn khi ấy đã được xây lại phần lớn từ năm 1927. Người phục dựng dựa vào hình dung chung về bếp bánh của một khách sạn lớn đầu thế kỷ XX: lò gạch, bàn nhồi bột, âu trộn, khay nướng, đèn treo có lồng bảo vệ. Mục đích không phải để khẳng định một chi tiết kiến trúc, mà để giúp người xem cảm được nhịp làm việc của một người thợ phụ, người mà theo lời kể chính là Nguyễn Tất Thành.","doc":1},{"loai":"anh","src":"textures/bang_w/G07_8_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Gian bếp bánh”, nhìn từ xa."},{"loai":"doan","tieu_de":"Một câu chuyện đến từ lời kể","text":"Câu chuyện người thanh niên Việt Nam làm bánh ở Boston không đến từ sổ sách của khách sạn. Theo các nhà viết tiểu sử, nó đến từ lời kể của chính Người ở giai đoạn sau và từ một bức thư Người gửi nhà chí sĩ Phan Châu Trinh, trong đó có nhắc tới công việc phụ bếp bánh ở Parker House. Khi đối chiếu với hồ sơ nhân sự của khách sạn, người ta không tìm thấy tên Người. Điều đó không phủ nhận câu chuyện, chỉ cho biết chưa có văn bản độc lập nào xác nhận nó.\n\nVì thế các sử gia vẫn trình bày chi tiết này bằng những chữ “theo lời kể”. Dù vậy, câu chuyện đã được nhiều thế hệ ở cả hai nước ghi nhận và tìm hiểu thêm. Năm 2015, báo Nhân Dân thuật lại buổi trình bày tại khách sạn Omni Parker House của Kevin Bowen, nhà thơ, cựu chiến binh Mỹ, nguyên Giám đốc Trung tâm William Joiner thuộc Đại học Massachusetts. Ông là một trong những người Mỹ dành nhiều công sức tìm hiểu quãng thời gian người thanh niên Việt Nam sống ở Boston.","doc":2},{"loai":"doan","tieu_de":"Từ bếp tàu đến bếp khách sạn","text":"Trước khi đến Boston, người thanh niên đã quen với nghề bếp. Từ tháng 6/1911, Người làm phụ bếp trên tàu Amiral Latouche-Tréville với cái tên Văn Ba, rồi tiếp tục sống bằng công việc trên tàu biển qua nhiều hải cảng. Lời hứa sẽ làm bất cứ việc gì để sống và để đi, nói với người bạn ở Sài Gòn năm 1911, được giữ trọn trong những năm ấy (xem chuyên đề Hai bàn tay, gian Bến Nhà Rồng).\n\nVới một thanh niên châu Á không người đỡ đầu, không bằng cấp được công nhận ở nước ngoài, bếp là nơi dễ tìm việc nhất. Nhà bếp khách sạn, nhà hàng ở các thành phố lớn nước Mỹ khi ấy cần rất nhiều người phụ việc, và phần đông trong số họ là người nhập cư. Công việc nặng, lương thấp, nhưng có chỗ ăn, có tiền công đều đặn. Quan trọng hơn, nó cho phép người làm thuê ở lại thành phố, quan sát và học hỏi. Chiếc tạp dề của người thợ phụ vì thế là tấm vé để Người tiếp tục ở lại giữa đời sống thật của một đất nước xa lạ.","doc":3},{"loai":"trich","text":"Chúng ta sẽ làm việc. Chúng ta sẽ làm bất cứ việc gì để sống và để đi.","nguoi":"Nguyễn Tất Thành, nói với người bạn ở Sài Gòn năm 1911 (theo lời kể của Trần Dân Tiên)","nguon_ten":"Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","doc":4},{"loai":"doan","tieu_de":"Một ngày của người thợ phụ bánh","text":"Bếp bánh của một khách sạn lớn thường bắt đầu làm việc từ lúc nửa đêm hoặc trước bình minh. Bánh mì phải kịp ra lò cho bữa sáng, rồi lại được nướng thêm cho bữa trưa và bữa tối. Người thợ phụ thường nhận những việc nặng nhọc nhất. Họ khuân những bao bột lớn, rây bột, đong nước, nhóm và canh lò, bôi mỡ khay nướng, rồi cọ rửa khi mẻ bánh đã xong.\n\nLàm bánh mì là một công việc cần kiên nhẫn. Bột trộn với men và nước phải được nhào kỹ cho dẻo, rồi để ủ đến khi nở phồng. Sau đó bột được chia thành từng phần đều nhau, nặn hình, ủ lần nữa, rồi mới vào lò. Chỉ chậm một chút, mẻ bánh có thể nở quá hay cháy xém. Trong gian bếp, sức nóng của lò lửa và hơi nước bốc lên khác hẳn cái lạnh cắt da bên ngoài. Người làm bếp bánh quen với việc bước ra phố lúc trời vừa sáng, khi thành phố mới bắt đầu một ngày của nó. Đó là nhịp sống mà người thợ phụ châu Á ấy, theo lời kể, đã trải qua trong những tháng mùa đông ở Boston.","doc":5},{"loai":"ban_co_biet","text":"Nghề làm bánh ở Mỹ đầu thế kỷ XX nổi tiếng là vất vả. Năm 1895, bang New York ra luật giới hạn thợ làm bánh chỉ làm tối đa 10 giờ mỗi ngày và 60 giờ mỗi tuần. Năm 1905, trong vụ kiện Lochner kiện bang New York, Tòa án Tối cao Hoa Kỳ đã hủy bỏ giới hạn ấy với tỷ lệ phiếu năm – bốn.","nguon_ten":"Tòa án Tối cao Hoa Kỳ, vụ Lochner v. New York, 198 U.S. 45 (1905)","doc":6},{"loai":"doan","tieu_de":"Chiếc bánh gấp đôi mang tên khách sạn","text":"Bếp bánh của Parker House không phải một bếp bánh bình thường. Từ thế kỷ XIX, khách sạn đã nổi tiếng với loại bánh mì nhỏ, mềm, mang tên Parker House roll. Cách làm của nó khá riêng. Bột được cán mỏng, cắt thành những miếng tròn, phết bơ lên mặt, rồi gấp đôi lại trước khi nướng. Khi ra lò, chiếc bánh có vỏ vàng óng, ruột mềm và nếp gấp đặc trưng như một chiếc ví nhỏ.\n\nTương truyền, chiếc bánh ra đời từ một sự tình cờ trong bếp: một người thợ bánh đang bực bội đã ném những miếng bột chưa nặn xong vào lò, và chúng nở thành hình gấp đôi. Đó chỉ là giai thoại, nhưng cho thấy bếp bánh của khách sạn đã trở thành một phần danh tiếng của nó. Một bếp bánh như thế cần nhiều đôi tay, từ người thợ cả giữ bí quyết đến những người phụ việc chuẩn bị bột, canh lò. Người thanh niên Việt Nam, nếu như lời kể, đã góp đôi tay mình vào những mẻ bánh quen thuộc với khách của một trong những khách sạn danh tiếng nhất Boston.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_omni_parker_house_school_st_boston_493545_110616.jpg","chu_thich":"Khách sạn Parker House trên phố School, Boston, ảnh chụp năm 2013. Tòa nhà được xây lại phần lớn từ năm 1927; gian bếp bánh mùa đông 1912 – 1913 nay không còn.","credit":"Ảnh: Robert Linsdell from St. Andrews, Canada · CC BY 2.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Bên chiếc bàn đá nhỏ","text":"Những người Mỹ tìm hiểu về quãng thời gian này đã cố hình dung công việc cụ thể của người thợ trẻ. Theo bài viết của báo Nhân Dân năm 2015 thuật lại phần trình bày của Kevin Bowen, người thanh niên làm việc bên một chiếc bàn đá nhỏ trong bếp bánh. Theo lời kể ấy, từ chân phụ việc, Người dần được giao làm bánh, trong đó có bánh kem Boston và bánh chanh phủ lòng trắng trứng đánh bông.\n\nĐây là những chi tiết do các nhà nghiên cứu Mỹ kể lại, chưa có văn bản gốc từ thời ấy xác nhận, nên cần được hiểu đúng như vậy. Nhưng chúng khớp với cách làm việc của bếp bánh thời ấy. Mặt bàn bằng đá mát và phẳng, rất hợp để cán bột làm vỏ bánh và nhào những khối bột mềm. Bánh kem Boston, món bánh gắn với lịch sử bếp Parker House, cũng là món quen thuộc của khách sạn (xem chuyên đề Mặt tiền khách sạn Parker House ngày nay). Từ những chi tiết nhỏ ấy, gian bếp tái hiện đặt chiếc bàn nhồi bột ở chính giữa, như trung tâm của một ngày lao động.","doc":8},{"loai":"anh","src":"textures/bang_w/G07_8_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Gian bếp bánh”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Boston của người lao động năm 1912","text":"Năm 1912 là một năm sôi động của giới lao động ở bang Massachusetts. Tháng 1/1912, ở thành phố dệt Lawrence, cách Boston không xa về phía bắc, khoảng hai vạn công nhân dệt bãi công khi đồng lương bị cắt giảm. Phần đông trong số họ là người nhập cư từ nhiều nước châu Âu. Cuộc bãi công kéo dài đến tháng 3/1912 và giành được việc tăng lương. Về sau, nó thường được nhắc tới với khẩu hiệu “Bánh mì và hoa hồng”, nghĩa là người lao động không chỉ cần miếng ăn mà còn cần một cuộc sống có phẩm giá.\n\nKhông có tư liệu nào cho biết người thợ phụ ở Parker House biết đến cuộc bãi công này. Nhưng nó cho thấy bầu không khí của vùng đất nơi Người sống: những người lao động nhập cư làm những việc nặng nhọc nhất, sống trong những khu nhà chật chội, và bắt đầu đoàn kết để đòi quyền lợi. Cũng giữa mùa đông ấy, trong gian bếp của một khách sạn sang trọng, một thanh niên thuộc địa đang tự mình nếm trải đời sống của người làm thuê trên đất Mỹ.","doc":9},{"loai":"ban_co_biet","text":"Công thức “Parker House rolls” đã có mặt trong cuốn sách dạy nấu ăn nổi tiếng của trường nấu ăn Boston do Fannie Farmer biên soạn, xuất bản năm 1896. Như vậy, khi người thanh niên Việt Nam đến Boston, chiếc bánh mang tên khách sạn đã quen thuộc trong nhiều gian bếp gia đình ở Mỹ.","nguon_ten":"Fannie Merritt Farmer, The Boston Cooking-School Cook Book, Boston, 1896","doc":10},{"loai":"doan","tieu_de":"Học từ trong bếp","text":"Những năm làm thuê không chỉ là kế sinh nhai. Làm việc bên cạnh những người thợ đến từ nhiều nước, người thanh niên có dịp nghe nhiều thứ tiếng, học cách sống của người lao động ở một nước công nghiệp. Người hiểu đồng lương của họ, giờ làm của họ, cả những lo toan và nỗi bất bình của họ. Đó là những bài học không có trong sách, và chỉ ai sống giữa họ mới học được.\n\nRời nước Mỹ năm 1913, Người sang nước Anh và tiếp tục sống bằng nghề bếp trong các khách sạn ở London (xem các chuyên đề của gian Nước Anh – London). Về sau ở Paris, Người làm thợ sửa ảnh. Suốt những năm ấy, Người luôn tự nuôi mình bằng lao động của chính mình. Nhiều năm sau, khi viết báo, viết sách tố cáo chế độ thực dân và kêu gọi người lao động các nước đoàn kết, Người viết như một người từng ở trong hàng ngũ ấy. Gian bếp bánh ở Boston là một chặng nhỏ trong quãng đời làm thuê dài, nhưng là chặng giúp ta hiểu điều đó rõ nhất.","doc":11},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Khách sạn ngày nay mang tên Omni Parker House, vẫn hoạt động ở số 60 phố School, trên chính khu đất xưa. Gian bếp bánh của năm 1912 không còn, vì tòa nhà đã được xây lại phần lớn từ năm 1927. Nhưng câu chuyện về người thợ làm bánh Việt Nam vẫn được khách sạn giới thiệu với du khách, bên cạnh những tên tuổi từng gắn bó với nơi này. Món bánh mì gấp đôi và bánh kem Boston vẫn được phục vụ trong nhà hàng của khách sạn.\n\nKhách sạn cũng trở thành điểm dừng chân của nhiều đoàn khách Việt Nam. Tháng 5/2022, trong chuyến công tác tại Hoa Kỳ, Thủ tướng Phạm Minh Chính và đoàn công tác đã đến thăm nơi Chủ tịch Hồ Chí Minh từng làm việc ở Boston. Với người xem trong bảo tàng, gian bếp tái hiện là cách gần nhất để hình dung một chặng đường không còn dấu vết vật chất. Hãy dừng lại bên chiếc bàn nhồi bột, nhìn ánh lửa trong lò, và nghĩ về người thợ phụ hai mươi hai tuổi. Người ấy làm việc lặng lẽ giữa mùa đông xứ lạ, mang theo một câu hỏi lớn về con đường giải phóng dân tộc mình.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","Văn Nghiệp Chúc, “Bài 3: Bác Hồ ở Boston”, báo Nhân Dân điện tử, 13/9/2015, https://nhandan.vn/bai-3-bac-ho-o-boston-post242486.html","William J. Duiker, Ho Chi Minh: A Life, Hyperion, New York, 2000","Báo Điện tử Chính phủ, “Chùm ảnh: Thủ tướng và đoàn công tác thăm nơi Chủ tịch Hồ Chí Minh từng làm việc tại Hoa Kỳ”, tháng 5/2022","Tòa án Tối cao Hoa Kỳ, Lochner v. New York (1905); Fannie Merritt Farmer, The Boston Cooking-School Cook Book (1896)"],"doc":[{"t":"Gian bếp bánh ở Boston: bột, lửa và đôi tay người thợ phụ mùa đông 1912 – 1913. Trước khi khách của khách sạn Parker House thức dậy, bánh mì trên bàn ăn sáng của họ đã phải được nhào, ủ và nướng xong. Theo lời kể về sau, trong mùa đông 1912 – 1913, giữa những người thợ làm việc từ lúc trời còn tối ấy có một thanh niên châu Á hai mươi hai tuổi. Gian bếp bánh phục dựng trong không gian 3D mời người xem bước vào công việc của anh: một nghề không tên tuổi, nhưng đã nuôi anh trên con đường tìm đường cứu nước."},{"t":"Trước khi trời sáng. Bên ngoài là mùa đông Boston, gió lạnh thổi dọc những con phố, tuyết đọng thành vệt bên lề đường. Bên trong gian bếp bánh, lò gạch đã đỏ lửa từ nhiều giờ trước. Trên chiếc bàn gỗ dài, những khối bột được nhào, chia, cán mỏng; trên giá, từng khay bánh xếp chờ vào lò. Đó là cảnh người xem gặp khi bước vào gian bếp tái hiện trong không gian 3D. Cần nói rõ ngay từ đầu: gian bếp này không phải bản sao của một căn phòng đã được ghi chép. Không có bản vẽ hay tấm ảnh nào cho biết bếp bánh của Parker House năm 1912 trông ra sao, và tòa nhà khách sạn khi ấy đã được xây lại phần lớn từ năm 1927. Người phục dựng dựa vào hình dung chung về bếp bánh của một khách sạn lớn đầu thế kỷ XX: lò gạch, bàn nhồi bột, âu trộn, khay nướng, đèn treo có lồng bảo vệ. Mục đích không phải để khẳng định một chi tiết kiến trúc, mà để giúp người xem cảm được nhịp làm việc của một người thợ phụ, người mà theo lời kể chính là Nguyễn Tất Thành."},{"t":"Một câu chuyện đến từ lời kể. Câu chuyện người thanh niên Việt Nam làm bánh ở Boston không đến từ sổ sách của khách sạn. Theo các nhà viết tiểu sử, nó đến từ lời kể của chính Người ở giai đoạn sau và từ một bức thư Người gửi nhà chí sĩ Phan Châu Trinh, trong đó có nhắc tới công việc phụ bếp bánh ở Parker House. Khi đối chiếu với hồ sơ nhân sự của khách sạn, người ta không tìm thấy tên Người. Điều đó không phủ nhận câu chuyện, chỉ cho biết chưa có văn bản độc lập nào xác nhận nó. Vì thế các sử gia vẫn trình bày chi tiết này bằng những chữ “theo lời kể”. Dù vậy, câu chuyện đã được nhiều thế hệ ở cả hai nước ghi nhận và tìm hiểu thêm. Năm 2015, báo Nhân Dân thuật lại buổi trình bày tại khách sạn Omni Parker House của Kevin Bowen, nhà thơ, cựu chiến binh Mỹ, nguyên Giám đốc Trung tâm William Joiner thuộc Đại học Massachusetts. Ông là một trong những người Mỹ dành nhiều công sức tìm hiểu quãng thời gian người thanh niên Việt Nam sống ở Boston."},{"t":"Từ bếp tàu đến bếp khách sạn. Trước khi đến Boston, người thanh niên đã quen với nghề bếp. Từ tháng 6/1911, Người làm phụ bếp trên tàu Amiral Latouche-Tréville với cái tên Văn Ba, rồi tiếp tục sống bằng công việc trên tàu biển qua nhiều hải cảng. Lời hứa sẽ làm bất cứ việc gì để sống và để đi, nói với người bạn ở Sài Gòn năm 1911, được giữ trọn trong những năm ấy (xem chuyên đề Hai bàn tay, gian Bến Nhà Rồng). Với một thanh niên châu Á không người đỡ đầu, không bằng cấp được công nhận ở nước ngoài, bếp là nơi dễ tìm việc nhất. Nhà bếp khách sạn, nhà hàng ở các thành phố lớn nước Mỹ khi ấy cần rất nhiều người phụ việc, và phần đông trong số họ là người nhập cư. Công việc nặng, lương thấp, nhưng có chỗ ăn, có tiền công đều đặn. Quan trọng hơn, nó cho phép người làm thuê ở lại thành phố, quan sát và học hỏi. Chiếc tạp dề của người thợ phụ vì thế là tấm vé để Người tiếp tục ở lại giữa đời sống thật của một đất nước xa lạ."},{"t":"Chúng ta sẽ làm việc. Chúng ta sẽ làm bất cứ việc gì để sống và để đi. — Nguyễn Tất Thành, nói với người bạn ở Sài Gòn năm 1911 (theo lời kể của Trần Dân Tiên)"},{"t":"Một ngày của người thợ phụ bánh. Bếp bánh của một khách sạn lớn thường bắt đầu làm việc từ lúc nửa đêm hoặc trước bình minh. Bánh mì phải kịp ra lò cho bữa sáng, rồi lại được nướng thêm cho bữa trưa và bữa tối. Người thợ phụ thường nhận những việc nặng nhọc nhất. Họ khuân những bao bột lớn, rây bột, đong nước, nhóm và canh lò, bôi mỡ khay nướng, rồi cọ rửa khi mẻ bánh đã xong. Làm bánh mì là một công việc cần kiên nhẫn. Bột trộn với men và nước phải được nhào kỹ cho dẻo, rồi để ủ đến khi nở phồng. Sau đó bột được chia thành từng phần đều nhau, nặn hình, ủ lần nữa, rồi mới vào lò. Chỉ chậm một chút, mẻ bánh có thể nở quá hay cháy xém. Trong gian bếp, sức nóng của lò lửa và hơi nước bốc lên khác hẳn cái lạnh cắt da bên ngoài. Người làm bếp bánh quen với việc bước ra phố lúc trời vừa sáng, khi thành phố mới bắt đầu một ngày của nó. Đó là nhịp sống mà người thợ phụ châu Á ấy, theo lời kể, đã trải qua trong những tháng mùa đông ở Boston."},{"t":"Bạn có biết? Nghề làm bánh ở Mỹ đầu thế kỷ XX nổi tiếng là vất vả. Năm 1895, bang New York ra luật giới hạn thợ làm bánh chỉ làm tối đa 10 giờ mỗi ngày và 60 giờ mỗi tuần. Năm 1905, trong vụ kiện Lochner kiện bang New York, Tòa án Tối cao Hoa Kỳ đã hủy bỏ giới hạn ấy với tỷ lệ phiếu năm – bốn."},{"t":"Chiếc bánh gấp đôi mang tên khách sạn. Bếp bánh của Parker House không phải một bếp bánh bình thường. Từ thế kỷ XIX, khách sạn đã nổi tiếng với loại bánh mì nhỏ, mềm, mang tên Parker House roll. Cách làm của nó khá riêng. Bột được cán mỏng, cắt thành những miếng tròn, phết bơ lên mặt, rồi gấp đôi lại trước khi nướng. Khi ra lò, chiếc bánh có vỏ vàng óng, ruột mềm và nếp gấp đặc trưng như một chiếc ví nhỏ. Tương truyền, chiếc bánh ra đời từ một sự tình cờ trong bếp: một người thợ bánh đang bực bội đã ném những miếng bột chưa nặn xong vào lò, và chúng nở thành hình gấp đôi. Đó chỉ là giai thoại, nhưng cho thấy bếp bánh của khách sạn đã trở thành một phần danh tiếng của nó. Một bếp bánh như thế cần nhiều đôi tay, từ người thợ cả giữ bí quyết đến những người phụ việc chuẩn bị bột, canh lò. Người thanh niên Việt Nam, nếu như lời kể, đã góp đôi tay mình vào những mẻ bánh quen thuộc với khách của một trong những khách sạn danh tiếng nhất Boston."},{"t":"Bên chiếc bàn đá nhỏ. Những người Mỹ tìm hiểu về quãng thời gian này đã cố hình dung công việc cụ thể của người thợ trẻ. Theo bài viết của báo Nhân Dân năm 2015 thuật lại phần trình bày của Kevin Bowen, người thanh niên làm việc bên một chiếc bàn đá nhỏ trong bếp bánh. Theo lời kể ấy, từ chân phụ việc, Người dần được giao làm bánh, trong đó có bánh kem Boston và bánh chanh phủ lòng trắng trứng đánh bông. Đây là những chi tiết do các nhà nghiên cứu Mỹ kể lại, chưa có văn bản gốc từ thời ấy xác nhận, nên cần được hiểu đúng như vậy. Nhưng chúng khớp với cách làm việc của bếp bánh thời ấy. Mặt bàn bằng đá mát và phẳng, rất hợp để cán bột làm vỏ bánh và nhào những khối bột mềm. Bánh kem Boston, món bánh gắn với lịch sử bếp Parker House, cũng là món quen thuộc của khách sạn (xem chuyên đề Mặt tiền khách sạn Parker House ngày nay). Từ những chi tiết nhỏ ấy, gian bếp tái hiện đặt chiếc bàn nhồi bột ở chính giữa, như trung tâm của một ngày lao động."},{"t":"Boston của người lao động năm 1912. Năm 1912 là một năm sôi động của giới lao động ở bang Massachusetts. Tháng 1/1912, ở thành phố dệt Lawrence, cách Boston không xa về phía bắc, khoảng hai vạn công nhân dệt bãi công khi đồng lương bị cắt giảm. Phần đông trong số họ là người nhập cư từ nhiều nước châu Âu. Cuộc bãi công kéo dài đến tháng 3/1912 và giành được việc tăng lương. Về sau, nó thường được nhắc tới với khẩu hiệu “Bánh mì và hoa hồng”, nghĩa là người lao động không chỉ cần miếng ăn mà còn cần một cuộc sống có phẩm giá. Không có tư liệu nào cho biết người thợ phụ ở Parker House biết đến cuộc bãi công này. Nhưng nó cho thấy bầu không khí của vùng đất nơi Người sống: những người lao động nhập cư làm những việc nặng nhọc nhất, sống trong những khu nhà chật chội, và bắt đầu đoàn kết để đòi quyền lợi. Cũng giữa mùa đông ấy, trong gian bếp của một khách sạn sang trọng, một thanh niên thuộc địa đang tự mình nếm trải đời sống của người làm thuê trên đất Mỹ."},{"t":"Bạn có biết? Công thức “Parker House rolls” đã có mặt trong cuốn sách dạy nấu ăn nổi tiếng của trường nấu ăn Boston do Fannie Farmer biên soạn, xuất bản năm 1896. Như vậy, khi người thanh niên Việt Nam đến Boston, chiếc bánh mang tên khách sạn đã quen thuộc trong nhiều gian bếp gia đình ở Mỹ."},{"t":"Học từ trong bếp. Những năm làm thuê không chỉ là kế sinh nhai. Làm việc bên cạnh những người thợ đến từ nhiều nước, người thanh niên có dịp nghe nhiều thứ tiếng, học cách sống của người lao động ở một nước công nghiệp. Người hiểu đồng lương của họ, giờ làm của họ, cả những lo toan và nỗi bất bình của họ. Đó là những bài học không có trong sách, và chỉ ai sống giữa họ mới học được. Rời nước Mỹ năm 1913, Người sang nước Anh và tiếp tục sống bằng nghề bếp trong các khách sạn ở London (xem các chuyên đề của gian Nước Anh – London). Về sau ở Paris, Người làm thợ sửa ảnh. Suốt những năm ấy, Người luôn tự nuôi mình bằng lao động của chính mình. Nhiều năm sau, khi viết báo, viết sách tố cáo chế độ thực dân và kêu gọi người lao động các nước đoàn kết, Người viết như một người từng ở trong hàng ngũ ấy. Gian bếp bánh ở Boston là một chặng nhỏ trong quãng đời làm thuê dài, nhưng là chặng giúp ta hiểu điều đó rõ nhất."},{"t":"Dấu tích hôm nay. Khách sạn ngày nay mang tên Omni Parker House, vẫn hoạt động ở số 60 phố School, trên chính khu đất xưa. Gian bếp bánh của năm 1912 không còn, vì tòa nhà đã được xây lại phần lớn từ năm 1927. Nhưng câu chuyện về người thợ làm bánh Việt Nam vẫn được khách sạn giới thiệu với du khách, bên cạnh những tên tuổi từng gắn bó với nơi này. Món bánh mì gấp đôi và bánh kem Boston vẫn được phục vụ trong nhà hàng của khách sạn. Khách sạn cũng trở thành điểm dừng chân của nhiều đoàn khách Việt Nam. Tháng 5/2022, trong chuyến công tác tại Hoa Kỳ, Thủ tướng Phạm Minh Chính và đoàn công tác đã đến thăm nơi Chủ tịch Hồ Chí Minh từng làm việc ở Boston. Với người xem trong bảo tàng, gian bếp tái hiện là cách gần nhất để hình dung một chặng đường không còn dấu vết vật chất. Hãy dừng lại bên chiếc bàn nhồi bột, nhìn ánh lửa trong lò, và nghĩ về người thợ phụ hai mươi hai tuổi. Người ấy làm việc lặng lẽ giữa mùa đông xứ lạ, mang theo một câu hỏi lớn về con đường giải phóng dân tộc mình."}],"so_chu":2041},{"i":9,"tieu_de_bang":"Nhà thờ King’s Chapel","tieu_de":"King’s Chapel: nhà thờ đá xám ở góc phố người thợ phụ đi qua, giữa thành phố của những lời tuyên ngôn","sapo":"Mùa đông 1912 – 1913, bước ra khỏi khách sạn Parker House, người ta sẽ thấy ngay ở góc phố Tremont một khối đá xám nặng nề với ngọn tháp vuông không có chóp nhọn. Nhà thờ King’s Chapel khi ấy đã đứng đó gần một trăm sáu mươi năm, chứng kiến Boston từ một thuộc địa trung thành với nhà vua nước Anh trở thành cái nôi của cuộc cách mạng Mỹ. Câu chuyện của nó giúp ta hiểu thành phố mà người thanh niên Việt Nam đã sống, và bài học về độc lập mà Người sẽ còn trở lại nhiều lần.","bia":{"src":"textures/bai/G07_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Khối đá xám ở góc phố","text":"Ở góc phố School và phố Tremont, giữa trung tâm Boston, có một công trình trông khác hẳn những tòa nhà xung quanh. Tường nhà thờ xây bằng những khối đá granit xám sẫm, to và thô, khai thác ở vùng Quincy gần Boston. Phía trước là hàng hiên với những cột lớn kiểu Ionic. Phía trên là một ngọn tháp vuông, thấp và vững chãi, trông như còn dang dở. Đó là nhà thờ King’s Chapel, xây dựng trong những năm 1749 – 1754.\n\nNhà thờ nằm ngay bên kia phố School, đối diện khách sạn Parker House. Nếu người thanh niên Nguyễn Tất Thành làm việc ở khách sạn như lời kể, thì hẳn Người đã nhiều lần nhìn thấy khối đá xám ấy trên đường đi làm. Không có tư liệu nào cho biết Người từng bước vào bên trong nhà thờ. Bảng trưng bày này không kể một sự kiện trong đời Người, mà kể về một nhân chứng đứng lặng lẽ bên con đường Người qua lại. Qua nó, người xem hiểu thêm về thành phố nơi một thuộc địa đã đứng lên giành độc lập.","doc":1},{"loai":"anh","src":"textures/bang_w/G07_9_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà thờ King’s Chapel”, nhìn từ xa."},{"loai":"doan","tieu_de":"Vì sao gọi là “Nhà thờ của nhà vua”","text":"Boston được những người Thanh giáo từ nước Anh lập nên năm 1630. Họ rời quê hương một phần vì không chấp nhận giáo hội chính thức của nước Anh, nên trong nửa thế kỷ đầu, thành phố không có nhà thờ Anh giáo nào. Mọi chuyện thay đổi khi nhà vua nước Anh siết chặt quyền cai quản các thuộc địa ở vùng New England. Năm 1686, giáo đoàn Anh giáo đầu tiên của Boston ra đời, gắn với các quan chức và binh lính do triều đình phái sang.\n\nNgôi nhà thờ đầu tiên của giáo đoàn chỉ là một nhà gỗ nhỏ, dựng trên một góc đất của khu nghĩa trang thành phố. Vì được triều đình bảo trợ, nó mang tên King’s Chapel, nghĩa là Nhà thờ của nhà vua. Với nhiều cư dân Boston thời ấy, ngôi nhà thờ là biểu tượng của quyền lực từ chính quốc bên kia đại dương. Cái tên ấy vì thế đã mang sẵn trong mình mâu thuẫn giữa thuộc địa và chính quốc, mâu thuẫn sẽ bùng nổ gần một thế kỷ sau.","doc":2},{"loai":"doan","tieu_de":"Nhà thờ mới dựng quanh nhà thờ cũ","text":"Giữa thế kỷ XVIII, ngôi nhà gỗ đã quá chật và cũ. Giáo đoàn quyết định xây một nhà thờ bằng đá, do kiến trúc sư Peter Harrison ở Rhode Island thiết kế. Công trình được khởi công năm 1749 và hoàn thành năm 1754. Cách xây rất đặc biệt: những bức tường đá mới được dựng bao quanh ngôi nhà gỗ cũ, để giáo dân vẫn có thể làm lễ trong suốt thời gian thi công. Khi phần vỏ đá đã hoàn chỉnh, ngôi nhà gỗ bên trong mới được tháo dỡ.\n\nTheo thiết kế, nhà thờ có một ngọn tháp chóp cao, nhưng vì thiếu kinh phí, chóp nhọn ấy chưa bao giờ được xây. Hàng hiên cột phía trước được làm thêm về sau, vào khoảng những năm 1785 – 1787. Những chiếc cột trông như đá, nhưng thực ra làm bằng gỗ và được sơn giả đá. Bên trong, không gian nhà thờ được Tổ chức Con đường Tự do Boston đánh giá là mẫu mực bậc nhất của kiến trúc Georgia ở Bắc Mỹ, với những hàng cột đôi thanh mảnh và những dãy ghế có vách ngăn.","doc":3},{"loai":"ban_co_biet","text":"Chiếc chuông của King’s Chapel được đúc ở nước Anh năm 1772 và bị nứt năm 1814. Năm 1816, nó được đúc lại bởi Paul Revere, người thợ bạc nổi tiếng với chuyến phi ngựa báo tin trong đêm mở đầu Chiến tranh Cách mạng Mỹ. Chiếc chuông ấy vẫn còn ngân vang đến ngày nay.","nguon_ten":"Tổ chức Con đường Tự do Boston (The Freedom Trail Foundation), https://www.thefreedomtrail.org/trail-sites/kings-chapel-burying-ground","doc":4},{"loai":"doan","tieu_de":"Từ “Nhà thờ của nhà vua” đến “Nhà thờ Đá”","text":"Khi cuộc đấu tranh giành độc lập nổ ra, King’s Chapel rơi vào thế khó. Giáo đoàn của nó vốn gắn với chính quyền nhà vua, và nhiều giáo dân trung thành với nước Anh đã rời Boston khi quân Anh rút khỏi thành phố vào tháng 3/1776. Theo Tổ chức Con đường Tự do Boston, trong thời kỳ cách mạng, nhà thờ từng tạm đổi tên thành “Stone Chapel”, tức Nhà thờ Đá. Việc bỏ chữ “nhà vua” khỏi tên gọi cho thấy không khí của một thành phố đang dứt khoát đoạn tuyệt với chính quốc.\n\nSau chiến tranh, năm 1785, dưới thời mục sư James Freeman, King’s Chapel trở thành nhà thờ đầu tiên ở Mỹ theo phái Nhất vị. Từ một nhà thờ Anh giáo của triều đình, nó đi theo một con đường riêng, phù hợp với tinh thần của nước cộng hòa mới. Nhiều nhân vật lớn của nước Mỹ đã đến đây, trong đó có George Washington, bà Abigail Adams và Paul Revere. Đến năm 1912, nhà thờ đã đi qua gần hai thế kỷ biến động và trở thành một phần ký ức của thành phố.","doc":5},{"loai":"anh","src":"textures/bai/G07_v0.jpg","chu_thich":"Toàn cảnh không gian 3D tái hiện gian Nước Mỹ – Boston và New York.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Nghĩa trang cổ nhất Boston","text":"Ngay bên cạnh nhà thờ là khu nghĩa trang King’s Chapel, lập từ năm 1630, bằng tuổi thành phố. Đây là nghĩa trang đầu tiên của khu Boston cổ. Người đầu tiên được an táng ở đây là Isaac Johnson, chủ nhân ban đầu của khu đất. Về sau, nơi đây còn có mộ của John Winthrop, thống đốc đầu tiên của thuộc địa Vịnh Massachusetts. Theo truyền thống, nơi đây còn có mộ bà Mary Chilton, được coi là người phụ nữ đầu tiên bước xuống từ con tàu Mayflower.\n\nNhững tấm bia đá phiến sẫm màu, nhiều tấm khắc hình đầu lâu có cánh theo lối trang trí của thế kỷ XVII – XVIII, vẫn đứng san sát giữa lòng thành phố hiện đại. Vào năm 1912, khu nghĩa trang nhỏ ấy nằm ngay cạnh những con phố tấp nập xe điện, cửa hiệu và công sở. Hình ảnh ấy là một nét rất riêng của Boston: quá khứ thời thuộc địa không bị xóa đi, mà được giữ lại ngay giữa đời sống thường ngày. Với người dân Boston, những ngôi mộ ấy nhắc lại lịch sử lập nên thành phố và cả những thế hệ đã đấu tranh để giành độc lập.","doc":6},{"loai":"anh","src":"textures/bang_w/G07_9_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà thờ King’s Chapel”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Boston – nơi cách mạng Mỹ bắt đầu","text":"Từ King’s Chapel đi bộ vài phút là tới những địa điểm gắn với những ngày đầu của cuộc cách mạng Mỹ. Ngày 5/3/1770, trước tòa nhà nay gọi là Old State House, lính Anh nổ súng vào đám đông, làm năm người chết. Sự kiện ấy đi vào lịch sử với tên gọi vụ thảm sát Boston. Đêm 16/12/1773, để phản đối thuế của nước Anh, những người dân Boston leo lên tàu và đổ 342 thùng chè xuống bến cảng. Đó là sự kiện Tiệc trà Boston nổi tiếng.\n\nNăm 1776, các thuộc địa tuyên bố độc lập. Ngày 18/7/1776, bản Tuyên ngôn Độc lập vừa thông qua ở Philadelphia được đọc lần đầu trước người dân Boston, từ ban công của chính tòa Old State House. Như vậy, chỉ cách khách sạn Parker House ít phút đi bộ là cả một chuỗi địa điểm kể lại câu chuyện một thuộc địa đứng lên chống lại chính quốc. Câu mở đầu nổi tiếng của bản Tuyên ngôn ấy, hơn ba mươi năm sau khi Người rời nước Mỹ, sẽ vang lên ở Ba Đình (xem chuyên đề Tất cả mọi người đều sinh ra có quyền bình đẳng).","doc":7},{"loai":"ban_co_biet","text":"Con đường Tự do (Freedom Trail) ở Boston ra đời năm 1951 từ ý tưởng của nhà báo William Schofield. Tuyến đi bộ dài khoảng bốn cây số, được đánh dấu bằng một vạch gạch đỏ trên vỉa hè, nối mười sáu địa điểm lịch sử. King’s Chapel là một trong những điểm dừng trên tuyến đường ấy.","nguon_ten":"Tổ chức Con đường Tự do Boston (The Freedom Trail Foundation)","doc":8},{"loai":"doan","tieu_de":"Người thanh niên giữa thành phố của tuyên ngôn","text":"Năm 1912, những câu chuyện ấy không nằm trong sách vở xa xôi mà hiện diện ngay trên đường phố Boston. Tên phố, tấm biển, tượng đài, những tòa nhà cổ đều nhắc tới cuộc đấu tranh của mười ba thuộc địa. Với người dân một xứ thuộc địa như Việt Nam, đó là điều đáng suy ngẫm. Nước Mỹ hùng mạnh trước mắt từng là thuộc địa của một đế quốc, và đã giành được độc lập bằng cuộc đấu tranh của chính mình.\n\nNhưng cũng chính trên đất nước ấy, Người thấy những con người chưa được hưởng các quyền mà bản Tuyên ngôn đã hứa. Người da đen bị phân biệt đối xử, người lao động nhập cư sống vất vả. Không có tư liệu nào ghi lại suy nghĩ của Người khi đi qua góc phố King’s Chapel. Nhưng những gì Người viết về nước Mỹ trong các năm sau cho thấy hai cảm nhận song song. Người trân trọng tinh thần giành độc lập của cuộc cách mạng Mỹ, đồng thời tỉnh táo nhận ra giới hạn của nó. Cách nhìn ấy được Người trình bày rõ ràng nhất trong một cuốn sách viết mười lăm năm sau.","doc":9},{"loai":"anh","src":"textures/bang_w/G07_9_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà thờ King’s Chapel”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Cách mạng Mỹ trong “Đường Kách mệnh”","text":"Những năm 1925 – 1927, ở Quảng Châu, Trung Quốc, Nguyễn Ái Quốc mở các lớp huấn luyện cho thanh niên yêu nước Việt Nam, những hội viên của Hội Việt Nam Cách mạng Thanh niên. Các bài giảng của Người được tập hợp thành cuốn sách Đường Kách mệnh, in năm 1927. Trong sách có một phần riêng kể về cuộc cách mạng Mỹ. Người giảng cho học viên về nguyên nhân và diễn biến cuộc đấu tranh của các thuộc địa Bắc Mỹ chống nước Anh để giành độc lập.\n\nNgười đánh giá cao tinh thần ấy, nhưng không dừng lại ở ngưỡng mộ. Theo Người, đó là một cuộc cách mệnh tư bản, thành công đã lâu mà công nông vẫn còn cực khổ, nên là cuộc cách mệnh chưa đến nơi. Những người trẻ học ở Quảng Châu, về sau nhiều người trở thành cán bộ nòng cốt của cách mạng Việt Nam, đã học về cuộc cách mạng khởi đầu từ Boston qua chính những trang giảng ấy. Chặng dừng chân lặng lẽ ở Boston năm 1912 vì thế có một tiếng vọng xa hơn nhiều so với vài tháng làm thuê.","doc":10},{"loai":"trich","text":"Mỹ tuy rằng cách mệnh thành công đã hơn 150 năm nay, nhưng công nông vẫn cứ cực khổ, vẫn cứ lo tính cách mệnh lần thứ hai.","nguoi":"Nguyễn Ái Quốc, Đường Kách mệnh (1927)","nguon_ten":"Hồ Chí Minh Toàn tập, tập 2, NXB Chính trị quốc gia – tác phẩm Đường Kách mệnh","doc":11},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hơn một thế kỷ sau mùa đông người thanh niên Việt Nam sống ở Boston, King’s Chapel vẫn đứng nguyên ở góc phố School – Tremont. Những khối đá granit vẫn xám sẫm như xưa, ngọn tháp vuông vẫn không có chóp nhọn, chiếc chuông do Paul Revere đúc lại vẫn ngân vang. Nhà thờ vẫn là nơi sinh hoạt của một giáo đoàn, đồng thời là một điểm dừng trên Con đường Tự do, mở cửa đón du khách. Khu nghĩa trang bên cạnh vẫn giữ những tấm bia cổ, giữa những tòa nhà văn phòng hiện đại.\n\nDu khách đi theo vạch gạch đỏ của Con đường Tự do sẽ dừng ở King’s Chapel, rồi rẽ vào phố School, qua tượng Benjamin Franklin trước Tòa thị chính cũ. Khách sạn Parker House nằm ngay đầu con phố ấy. Trong không gian 3D của bảo tàng, King’s Chapel được phục dựng theo diện mạo đầu thế kỷ XX, với đường ray xe điện chạy dọc phố Tremont. Người xem có thể đứng ở góc phố ấy và hình dung một buổi chiều đông năm 1912. Khi ấy, một người thợ phụ châu Á vừa tan ca, bước qua khối đá xám đã chứng kiến sự ra đời của một nền cộng hòa.","doc":12}],"nguon":["Tổ chức Con đường Tự do Boston (The Freedom Trail Foundation), King’s Chapel & Burying Ground, https://www.thefreedomtrail.org/trail-sites/kings-chapel-burying-ground","Tư liệu của nhà thờ King’s Chapel, Boston","Nguyễn Ái Quốc, Đường Kách mệnh (1927), in trong Hồ Chí Minh Toàn tập, tập 2, NXB Chính trị quốc gia","Tuyên ngôn Độc lập nước Việt Nam Dân chủ Cộng hòa, 2/9/1945","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia"],"doc":[{"t":"King’s Chapel: nhà thờ đá xám ở góc phố người thợ phụ đi qua, giữa thành phố của những lời tuyên ngôn. Mùa đông 1912 – 1913, bước ra khỏi khách sạn Parker House, người ta sẽ thấy ngay ở góc phố Tremont một khối đá xám nặng nề với ngọn tháp vuông không có chóp nhọn. Nhà thờ King’s Chapel khi ấy đã đứng đó gần một trăm sáu mươi năm, chứng kiến Boston từ một thuộc địa trung thành với nhà vua nước Anh trở thành cái nôi của cuộc cách mạng Mỹ. Câu chuyện của nó giúp ta hiểu thành phố mà người thanh niên Việt Nam đã sống, và bài học về độc lập mà Người sẽ còn trở lại nhiều lần."},{"t":"Khối đá xám ở góc phố. Ở góc phố School và phố Tremont, giữa trung tâm Boston, có một công trình trông khác hẳn những tòa nhà xung quanh. Tường nhà thờ xây bằng những khối đá granit xám sẫm, to và thô, khai thác ở vùng Quincy gần Boston. Phía trước là hàng hiên với những cột lớn kiểu Ionic. Phía trên là một ngọn tháp vuông, thấp và vững chãi, trông như còn dang dở. Đó là nhà thờ King’s Chapel, xây dựng trong những năm 1749 – 1754. Nhà thờ nằm ngay bên kia phố School, đối diện khách sạn Parker House. Nếu người thanh niên Nguyễn Tất Thành làm việc ở khách sạn như lời kể, thì hẳn Người đã nhiều lần nhìn thấy khối đá xám ấy trên đường đi làm. Không có tư liệu nào cho biết Người từng bước vào bên trong nhà thờ. Bảng trưng bày này không kể một sự kiện trong đời Người, mà kể về một nhân chứng đứng lặng lẽ bên con đường Người qua lại. Qua nó, người xem hiểu thêm về thành phố nơi một thuộc địa đã đứng lên giành độc lập."},{"t":"Vì sao gọi là “Nhà thờ của nhà vua”. Boston được những người Thanh giáo từ nước Anh lập nên năm 1630. Họ rời quê hương một phần vì không chấp nhận giáo hội chính thức của nước Anh, nên trong nửa thế kỷ đầu, thành phố không có nhà thờ Anh giáo nào. Mọi chuyện thay đổi khi nhà vua nước Anh siết chặt quyền cai quản các thuộc địa ở vùng New England. Năm 1686, giáo đoàn Anh giáo đầu tiên của Boston ra đời, gắn với các quan chức và binh lính do triều đình phái sang. Ngôi nhà thờ đầu tiên của giáo đoàn chỉ là một nhà gỗ nhỏ, dựng trên một góc đất của khu nghĩa trang thành phố. Vì được triều đình bảo trợ, nó mang tên King’s Chapel, nghĩa là Nhà thờ của nhà vua. Với nhiều cư dân Boston thời ấy, ngôi nhà thờ là biểu tượng của quyền lực từ chính quốc bên kia đại dương. Cái tên ấy vì thế đã mang sẵn trong mình mâu thuẫn giữa thuộc địa và chính quốc, mâu thuẫn sẽ bùng nổ gần một thế kỷ sau."},{"t":"Nhà thờ mới dựng quanh nhà thờ cũ. Giữa thế kỷ XVIII, ngôi nhà gỗ đã quá chật và cũ. Giáo đoàn quyết định xây một nhà thờ bằng đá, do kiến trúc sư Peter Harrison ở Rhode Island thiết kế. Công trình được khởi công năm 1749 và hoàn thành năm 1754. Cách xây rất đặc biệt: những bức tường đá mới được dựng bao quanh ngôi nhà gỗ cũ, để giáo dân vẫn có thể làm lễ trong suốt thời gian thi công. Khi phần vỏ đá đã hoàn chỉnh, ngôi nhà gỗ bên trong mới được tháo dỡ. Theo thiết kế, nhà thờ có một ngọn tháp chóp cao, nhưng vì thiếu kinh phí, chóp nhọn ấy chưa bao giờ được xây. Hàng hiên cột phía trước được làm thêm về sau, vào khoảng những năm 1785 – 1787. Những chiếc cột trông như đá, nhưng thực ra làm bằng gỗ và được sơn giả đá. Bên trong, không gian nhà thờ được Tổ chức Con đường Tự do Boston đánh giá là mẫu mực bậc nhất của kiến trúc Georgia ở Bắc Mỹ, với những hàng cột đôi thanh mảnh và những dãy ghế có vách ngăn."},{"t":"Bạn có biết? Chiếc chuông của King’s Chapel được đúc ở nước Anh năm 1772 và bị nứt năm 1814. Năm 1816, nó được đúc lại bởi Paul Revere, người thợ bạc nổi tiếng với chuyến phi ngựa báo tin trong đêm mở đầu Chiến tranh Cách mạng Mỹ. Chiếc chuông ấy vẫn còn ngân vang đến ngày nay."},{"t":"Từ “Nhà thờ của nhà vua” đến “Nhà thờ Đá”. Khi cuộc đấu tranh giành độc lập nổ ra, King’s Chapel rơi vào thế khó. Giáo đoàn của nó vốn gắn với chính quyền nhà vua, và nhiều giáo dân trung thành với nước Anh đã rời Boston khi quân Anh rút khỏi thành phố vào tháng 3/1776. Theo Tổ chức Con đường Tự do Boston, trong thời kỳ cách mạng, nhà thờ từng tạm đổi tên thành “Stone Chapel”, tức Nhà thờ Đá. Việc bỏ chữ “nhà vua” khỏi tên gọi cho thấy không khí của một thành phố đang dứt khoát đoạn tuyệt với chính quốc. Sau chiến tranh, năm 1785, dưới thời mục sư James Freeman, King’s Chapel trở thành nhà thờ đầu tiên ở Mỹ theo phái Nhất vị. Từ một nhà thờ Anh giáo của triều đình, nó đi theo một con đường riêng, phù hợp với tinh thần của nước cộng hòa mới. Nhiều nhân vật lớn của nước Mỹ đã đến đây, trong đó có George Washington, bà Abigail Adams và Paul Revere. Đến năm 1912, nhà thờ đã đi qua gần hai thế kỷ biến động và trở thành một phần ký ức của thành phố."},{"t":"Nghĩa trang cổ nhất Boston. Ngay bên cạnh nhà thờ là khu nghĩa trang King’s Chapel, lập từ năm 1630, bằng tuổi thành phố. Đây là nghĩa trang đầu tiên của khu Boston cổ. Người đầu tiên được an táng ở đây là Isaac Johnson, chủ nhân ban đầu của khu đất. Về sau, nơi đây còn có mộ của John Winthrop, thống đốc đầu tiên của thuộc địa Vịnh Massachusetts. Theo truyền thống, nơi đây còn có mộ bà Mary Chilton, được coi là người phụ nữ đầu tiên bước xuống từ con tàu Mayflower. Những tấm bia đá phiến sẫm màu, nhiều tấm khắc hình đầu lâu có cánh theo lối trang trí của thế kỷ XVII – XVIII, vẫn đứng san sát giữa lòng thành phố hiện đại. Vào năm 1912, khu nghĩa trang nhỏ ấy nằm ngay cạnh những con phố tấp nập xe điện, cửa hiệu và công sở. Hình ảnh ấy là một nét rất riêng của Boston: quá khứ thời thuộc địa không bị xóa đi, mà được giữ lại ngay giữa đời sống thường ngày. Với người dân Boston, những ngôi mộ ấy nhắc lại lịch sử lập nên thành phố và cả những thế hệ đã đấu tranh để giành độc lập."},{"t":"Boston – nơi cách mạng Mỹ bắt đầu. Từ King’s Chapel đi bộ vài phút là tới những địa điểm gắn với những ngày đầu của cuộc cách mạng Mỹ. Ngày 5/3/1770, trước tòa nhà nay gọi là Old State House, lính Anh nổ súng vào đám đông, làm năm người chết. Sự kiện ấy đi vào lịch sử với tên gọi vụ thảm sát Boston. Đêm 16/12/1773, để phản đối thuế của nước Anh, những người dân Boston leo lên tàu và đổ 342 thùng chè xuống bến cảng. Đó là sự kiện Tiệc trà Boston nổi tiếng. Năm 1776, các thuộc địa tuyên bố độc lập. Ngày 18/7/1776, bản Tuyên ngôn Độc lập vừa thông qua ở Philadelphia được đọc lần đầu trước người dân Boston, từ ban công của chính tòa Old State House. Như vậy, chỉ cách khách sạn Parker House ít phút đi bộ là cả một chuỗi địa điểm kể lại câu chuyện một thuộc địa đứng lên chống lại chính quốc. Câu mở đầu nổi tiếng của bản Tuyên ngôn ấy, hơn ba mươi năm sau khi Người rời nước Mỹ, sẽ vang lên ở Ba Đình (xem chuyên đề Tất cả mọi người đều sinh ra có quyền bình đẳng)."},{"t":"Bạn có biết? Con đường Tự do (Freedom Trail) ở Boston ra đời năm 1951 từ ý tưởng của nhà báo William Schofield. Tuyến đi bộ dài khoảng bốn cây số, được đánh dấu bằng một vạch gạch đỏ trên vỉa hè, nối mười sáu địa điểm lịch sử. King’s Chapel là một trong những điểm dừng trên tuyến đường ấy."},{"t":"Người thanh niên giữa thành phố của tuyên ngôn. Năm 1912, những câu chuyện ấy không nằm trong sách vở xa xôi mà hiện diện ngay trên đường phố Boston. Tên phố, tấm biển, tượng đài, những tòa nhà cổ đều nhắc tới cuộc đấu tranh của mười ba thuộc địa. Với người dân một xứ thuộc địa như Việt Nam, đó là điều đáng suy ngẫm. Nước Mỹ hùng mạnh trước mắt từng là thuộc địa của một đế quốc, và đã giành được độc lập bằng cuộc đấu tranh của chính mình. Nhưng cũng chính trên đất nước ấy, Người thấy những con người chưa được hưởng các quyền mà bản Tuyên ngôn đã hứa. Người da đen bị phân biệt đối xử, người lao động nhập cư sống vất vả. Không có tư liệu nào ghi lại suy nghĩ của Người khi đi qua góc phố King’s Chapel. Nhưng những gì Người viết về nước Mỹ trong các năm sau cho thấy hai cảm nhận song song. Người trân trọng tinh thần giành độc lập của cuộc cách mạng Mỹ, đồng thời tỉnh táo nhận ra giới hạn của nó. Cách nhìn ấy được Người trình bày rõ ràng nhất trong một cuốn sách viết mười lăm năm sau."},{"t":"Cách mạng Mỹ trong “Đường Kách mệnh”. Những năm 1925 – 1927, ở Quảng Châu, Trung Quốc, Nguyễn Ái Quốc mở các lớp huấn luyện cho thanh niên yêu nước Việt Nam, những hội viên của Hội Việt Nam Cách mạng Thanh niên. Các bài giảng của Người được tập hợp thành cuốn sách Đường Kách mệnh, in năm 1927. Trong sách có một phần riêng kể về cuộc cách mạng Mỹ. Người giảng cho học viên về nguyên nhân và diễn biến cuộc đấu tranh của các thuộc địa Bắc Mỹ chống nước Anh để giành độc lập. Người đánh giá cao tinh thần ấy, nhưng không dừng lại ở ngưỡng mộ. Theo Người, đó là một cuộc cách mệnh tư bản, thành công đã lâu mà công nông vẫn còn cực khổ, nên là cuộc cách mệnh chưa đến nơi. Những người trẻ học ở Quảng Châu, về sau nhiều người trở thành cán bộ nòng cốt của cách mạng Việt Nam, đã học về cuộc cách mạng khởi đầu từ Boston qua chính những trang giảng ấy. Chặng dừng chân lặng lẽ ở Boston năm 1912 vì thế có một tiếng vọng xa hơn nhiều so với vài tháng làm thuê."},{"t":"Mỹ tuy rằng cách mệnh thành công đã hơn 150 năm nay, nhưng công nông vẫn cứ cực khổ, vẫn cứ lo tính cách mệnh lần thứ hai. — Nguyễn Ái Quốc, Đường Kách mệnh (1927)"},{"t":"Dấu tích hôm nay. Hơn một thế kỷ sau mùa đông người thanh niên Việt Nam sống ở Boston, King’s Chapel vẫn đứng nguyên ở góc phố School – Tremont. Những khối đá granit vẫn xám sẫm như xưa, ngọn tháp vuông vẫn không có chóp nhọn, chiếc chuông do Paul Revere đúc lại vẫn ngân vang. Nhà thờ vẫn là nơi sinh hoạt của một giáo đoàn, đồng thời là một điểm dừng trên Con đường Tự do, mở cửa đón du khách. Khu nghĩa trang bên cạnh vẫn giữ những tấm bia cổ, giữa những tòa nhà văn phòng hiện đại. Du khách đi theo vạch gạch đỏ của Con đường Tự do sẽ dừng ở King’s Chapel, rồi rẽ vào phố School, qua tượng Benjamin Franklin trước Tòa thị chính cũ. Khách sạn Parker House nằm ngay đầu con phố ấy. Trong không gian 3D của bảo tàng, King’s Chapel được phục dựng theo diện mạo đầu thế kỷ XX, với đường ray xe điện chạy dọc phố Tremont. Người xem có thể đứng ở góc phố ấy và hình dung một buổi chiều đông năm 1912. Khi ấy, một người thợ phụ châu Á vừa tan ca, bước qua khối đá xám đã chứng kiến sự ra đời của một nền cộng hòa."}],"so_chu":2028},{"i":10,"tieu_de_bang":"New York và Harlem","tieu_de":"New York 1912: thành phố chọc trời, cửa ngõ người nhập cư và khu Harlem đang thành hình","sapo":"Dấu vết giấy tờ hiếm hoi nhất về chặng Mỹ của Nguyễn Tất Thành là một con dấu bưu điện New York. Thành phố ấy vừa khoe những tòa nhà cao nhất thế giới, vừa đón hàng triệu người nhập cư nghèo, lại vừa chứng kiến người Mỹ gốc Phi dồn về một khu phố phía bắc Manhattan tên là Harlem. Đi qua New York năm 1912 là đi qua cả ánh sáng lẫn bóng tối của nước Mỹ, những điều người thanh niên châu Á ấy sẽ còn nhắc lại trong nhiều trang viết về sau.","bia":{"src":"textures/bai/G07_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một con dấu bưu điện","text":"Giữa tháng 12/1912, ở New York, một người thanh niên Việt Nam gửi đi một lá thư cho các quan chức thuộc địa Pháp. Lá thư đề ngày 15/12/1912 và mang con dấu bưu điện New York. Ngày nay, nó là bằng chứng giấy tờ gần như duy nhất xác nhận Nguyễn Tất Thành đã có mặt trên đất Mỹ (xem chuyên đề Lá thư đóng dấu bưu điện New York). Ngoài dấu vết ấy, những gì ta biết về quãng thời gian Người ở thành phố này đều đến từ lời kể về sau.\n\nVì vậy, bảng trưng bày này không kể lại những sự việc chưa được xác nhận. Nó giới thiệu chính thành phố mà người thanh niên đã đặt chân tới: New York của năm 1912. Đó là thành phố của những bến cảng, những tòa nhà chọc trời, những khu nhà chật chội của người nhập cư, và khu Harlem đang dần trở thành trung tâm của người Mỹ gốc Phi. Hiểu thành phố ấy, người xem sẽ hiểu vì sao những gì Người thấy ở nước Mỹ lại để lại dấu ấn sâu đậm đến vậy trong tư tưởng và ngòi bút của Người.","doc":1},{"loai":"anh","src":"textures/bang_w/G07_10_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “New York và Harlem”, nhìn từ xa."},{"loai":"doan","tieu_de":"Thành phố lớn nhất nước Mỹ","text":"Năm 1912, New York là thành phố lớn nhất nước Mỹ và là một trong những đô thị lớn nhất thế giới. Cuộc điều tra dân số năm 1910 ghi nhận thành phố có gần 4,8 triệu người. Chỉ mười bốn năm trước đó, ngày 1/1/1898, năm khu vực là Manhattan, Brooklyn, Bronx, Queens và Staten Island mới hợp nhất thành thành phố New York ngày nay. Cầu Brooklyn, khánh thành năm 1883, nối Manhattan với Brooklyn qua sông East. Từ năm 1904, những chuyến tàu điện ngầm đầu tiên đã chạy dưới lòng Manhattan.\n\nThành phố lớn lên với tốc độ chóng mặt. Các bến cảng dọc sông Hudson và sông East tấp nập tàu buôn, tàu khách từ châu Âu, châu Mỹ Latinh và châu Á. Nhà máy, xưởng may, kho hàng mọc lên khắp nơi, cần hàng vạn người làm thuê. Trong lá thư ngày 15/12/1912, Nguyễn Tất Thành khai nghề nghiệp của mình là thủy thủ. Với một người đi biển như thế, New York là nơi có thể tìm việc trên tàu, ở bến cảng, trong nhà hàng hay trong những gia đình khá giả. Thành phố ấy cũng là nơi hội tụ gần như đủ mọi dân tộc trên thế giới.","doc":2},{"loai":"ban_co_biet","text":"Khi Người ở New York, tòa nhà Woolworth ở khu hạ Manhattan đang được hoàn thiện. Tối 24/4/1913, Tổng thống Woodrow Wilson bấm nút từ Nhà Trắng ở Washington để thắp sáng tòa nhà trong lễ khánh thành. Cao 241 mét, Woolworth giữ danh hiệu tòa nhà cao nhất thế giới cho đến năm 1930.","nguon_ten":"Cục Công viên Quốc gia Hoa Kỳ (National Park Service), tư liệu về Di tích lịch sử quốc gia Woolworth Building","doc":3},{"loai":"doan","tieu_de":"Cửa ngõ của người nhập cư","text":"New York là cửa ngõ chính của làn sóng nhập cư lớn nhất trong lịch sử nước Mỹ. Từ ngày 1/1/1892, trạm nhập cư trên đảo Ellis ở cảng New York bắt đầu hoạt động. Năm cao điểm 1907, hơn một triệu người nhập cư đã đến nước Mỹ, phần lớn qua cảng này. Họ đến từ Ý, Ireland, Đức, Ba Lan, Nga và nhiều vùng khác của châu Âu, mang theo vài bọc hành lý và hy vọng đổi đời. Tàu chở họ vào cảng đều đi ngang tượng Nữ thần Tự do, món quà nhân dân Pháp tặng nhân dân Mỹ, khánh thành ngày 28/10/1886.\n\nNhưng cuộc sống ở vùng đất hứa không dễ dàng. Phần đông người nhập cư dồn vào những khu nhà thuê chật chội ở khu Lower East Side của Manhattan, nhiều gia đình ở chung trong những căn phòng thiếu ánh sáng, thiếu nước sạch. Họ làm việc nhiều giờ trong các xưởng may, công trường, bến cảng với đồng lương ít ỏi. Ngọn đuốc của Nữ thần Tự do và những khu nhà ổ chuột chỉ cách nhau vài cây số, một hình ảnh tương phản mà người thanh niên thuộc địa, vốn quen quan sát đời sống người lao động, khó có thể bỏ qua.","doc":4},{"loai":"doan","tieu_de":"Brooklyn: làm thuê trong một gia đình giàu có","text":"Theo những lời kể được nhiều tư liệu Việt Nam dẫn lại, ở New York có một thời gian ngắn Người làm người giúp việc cho một gia đình giàu có ở Brooklyn. Báo Nhân Dân năm 2015, khi giới thiệu chặng đường của Người ở nước Mỹ, cũng nhắc tới công việc này trước khi Người đến Boston. Cũng như câu chuyện ở Parker House, chi tiết này chưa có văn bản độc lập từ thời ấy xác nhận, nên cần được hiểu là lời kể.\n\nNếu đúng như vậy, công việc ấy hoàn toàn phù hợp với thời đại. Đầu thế kỷ XX, giúp việc trong gia đình là một trong những nghề phổ biến nhất của người nhập cư mới đến các thành phố lớn nước Mỹ. Brooklyn khi ấy có nhiều khu nhà của các gia đình trung lưu và khá giả, cần người nấu ăn, dọn dẹp, trông nom nhà cửa. Làm việc trong một gia đình Mỹ, người thanh niên có dịp học tiếng Anh hằng ngày, quan sát tận mắt nếp sống của tầng lớp có của. Đó cũng là một cách để Người hiểu khoảng cách giữa những người chủ và những người làm thuê, trong một đất nước tự hào là mảnh đất của cơ hội.","doc":5},{"loai":"anh","src":"textures/bai/G07_v2.jpg","chu_thich":"Một góc không gian 3D tái hiện gian Nước Mỹ – Boston và New York.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Harlem: từ làng Hà Lan đến khu phố của người da đen","text":"Harlem nằm ở phía bắc đảo Manhattan. Thế kỷ XVII, đây là một làng nông nghiệp của những người định cư Hà Lan, về sau trở thành khu ngoại ô yên tĩnh của người da trắng khá giả. Cuối thế kỷ XIX, khi đường sắt trên cao nối Harlem với trung tâm Manhattan, các nhà đầu tư đổ xô xây những dãy nhà cho thuê, đón đợi một làn sóng cư dân mới. Nhưng họ xây quá nhiều. Khoảng năm 1904 – 1905, thị trường nhà đất đổ vỡ, nhiều căn hộ bỏ trống.\n\nĐúng lúc ấy, năm 1904, nhà kinh doanh bất động sản người Mỹ gốc Phi Philip A. Payton Jr. lập Công ty Bất động sản người Mỹ gốc Phi. Ông thuê lại những tòa nhà bỏ trống để cho các gia đình da đen thuê. Trước đó, người da đen ở New York sống dồn trong những khu nghèo ở giữa Manhattan, thường xuyên bị kỳ thị, có lúc bị tấn công. Harlem mở ra cho họ những căn hộ tử tế hơn. Từ đó, người Mỹ gốc Phi chuyển đến ngày một đông. Năm 1912, khu Harlem của người da đen đang thành hình, còn đang lan dần qua từng dãy phố.","doc":6},{"loai":"ban_co_biet","text":"Tên Harlem có gốc từ tiếng Hà Lan. Năm 1658, Peter Stuyvesant, thống đốc thuộc địa Tân Hà Lan, lập ở đây một làng mới và đặt tên là Nieuw Haarlem, theo tên thành phố Haarlem ở Hà Lan. Khi người Anh chiếm thuộc địa năm 1664, cái tên ấy vẫn được giữ lại.","nguon_ten":"Cục Công viên Quốc gia Hoa Kỳ (National Park Service); Bách khoa thư Thành phố New York (The Encyclopedia of New York City)","doc":7},{"loai":"doan","tieu_de":"Tiếng nói đòi quyền bình đẳng","text":"Nước Mỹ năm 1912 đã bãi bỏ chế độ nô lệ gần nửa thế kỷ, nhưng người da đen vẫn chưa được bình đẳng. Ở các bang miền Nam, những đạo luật phân biệt chủng tộc chia tách trường học, toa tàu, nhà hàng, và gạt họ khỏi lá phiếu. Nạn hành hình không qua xét xử vẫn diễn ra (xem chuyên đề Từ Harlem đến bài báo “Hành hình kiểu Linsơ”). Ở miền Bắc, họ bị phân biệt trong việc làm và nhà ở. Chính vì thế, nhiều người rời miền Nam lên các thành phố phía Bắc, và New York là một trong những điểm đến lớn nhất.\n\nNew York cũng là nơi tiếng nói đòi quyền bình đẳng vang lên mạnh mẽ. Năm 1909, Hội Quốc gia vì sự tiến bộ của người da màu, viết tắt là NAACP, được thành lập tại thành phố này. Từ tháng 11/1910, hội phát hành tạp chí The Crisis do nhà sử học, nhà xã hội học W. E. B. Du Bois làm chủ bút. Tạp chí lên tiếng tố cáo nạn hành hình, đòi quyền công dân cho người da đen. Những năm Người có mặt ở New York, đó là những cuộc tranh luận nóng bỏng của đời sống thành phố.","doc":8},{"loai":"anh","src":"textures/bang_w/G07_10_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “New York và Harlem”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Người khách lạ ở Harlem","text":"Theo một số nhà viết tiểu sử, trong thời gian ở New York, Người có thể đã sống một thời gian ở Harlem, hoặc ít nhất đã đến đây để tìm hiểu đời sống của người da đen. Các tác giả ấy đều dùng chữ “có thể”, vì chi tiết này đến từ lời kể chứ không phải từ văn bản đương thời. Bảo tàng giữ đúng sự thận trọng ấy. Điều chắc chắn hơn nằm ở những trang viết của Người mười một năm sau.\n\nNăm 1924, Nguyễn Ái Quốc viết bài “Hành hình kiểu Linsơ” và bài về tổ chức Ku Klux Klan, tố cáo tội ác phân biệt chủng tộc ở Mỹ bằng những chi tiết cụ thể, day dứt. Người không nhìn thân phận người da đen như chuyện riêng của nước Mỹ. Người đặt nó bên cạnh thân phận người dân các xứ thuộc địa, những người cùng bị coi là thấp kém và cùng bị tước quyền con người. Dù Người có ở Harlem hay không, những dãy phố nơi người Mỹ gốc Phi đang tụ hội năm 1912 là hình ảnh rõ nhất cho điều Người sẽ viết. Ngay giữa một nước cộng hòa, vẫn có những con người đang đòi quyền bình đẳng mà bản Tuyên ngôn Độc lập của chính nước ấy đã long trọng hứa hẹn.","doc":9},{"loai":"doan","tieu_de":"Một người châu Á ở New York","text":"Người thanh niên Việt Nam ở New York năm 1912 cũng thuộc một nhóm người chịu sự kỳ thị: người châu Á. Năm 1882, Quốc hội Mỹ thông qua Đạo luật Loại trừ người Hoa, cấm lao động người Hoa nhập cư. Đạo luật được gia hạn năm 1892, rồi năm 1902 được kéo dài không thời hạn, mãi đến năm 1943 mới bị bãi bỏ. Đạo luật này thường được coi là đạo luật đầu tiên của nước Mỹ cấm nhập cư đối với người lao động thuộc một dân tộc cụ thể.\n\nỞ khu hạ Manhattan, quanh phố Mott, khu phố người Hoa đã hình thành từ cuối thế kỷ XIX. Người lao động châu Á thường chỉ tìm được việc trong các tiệm giặt là, nhà hàng, bếp ăn hay làm người giúp việc. Không có tư liệu nào cho biết Người từng gặp khó khăn cụ thể vì màu da ở New York. Nhưng sống giữa thành phố ấy, một người châu Á hẳn nhận ra rằng những lời tuyên bố về tự do và bình đẳng không đến với mọi người như nhau. Nhận thức ấy nối liền trải nghiệm của Người ở nước Mỹ với những điều Người đã thấy ở các thuộc địa châu Phi và ở chính quê hương mình.","doc":10},{"loai":"anh","src":"textures/bang_w/G07_10_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “New York và Harlem”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Khác với Boston, nơi khách sạn Parker House vẫn kể câu chuyện về người thợ làm bánh Việt Nam, ở New York chưa có địa chỉ cụ thể nào được xác định chắc chắn gắn với những ngày Người sống ở đây. Lá thư đóng dấu bưu điện New York vẫn nằm trong hồ sơ của chính quyền thuộc địa Pháp, như một dấu mốc nhỏ nhưng chắc chắn. Tuy vậy, New York vẫn giữ nhiều chứng tích của thời đại Người đi qua.\n\nTượng Nữ thần Tự do vẫn đứng ở cửa cảng. Trạm nhập cư trên đảo Ellis từ năm 1990 đã trở thành bảo tàng về lịch sử nhập cư. Tòa nhà Woolworth vẫn đứng ở khu hạ Manhattan. Ở Harlem, Trung tâm Nghiên cứu Văn hóa Da đen Schomburg, thuộc Thư viện Công cộng New York, lưu giữ một trong những kho tư liệu lớn nhất về lịch sử người Mỹ gốc Phi. Trong không gian 3D của bảo tàng, góc New York và Harlem được dựng như một lời nhắc: người thanh niên ấy không chỉ đi qua những tòa nhà chọc trời. Người còn nhìn thấy những con người ở tầng thấp nhất của xã hội Mỹ, và mang hình ảnh của họ theo suốt con đường đấu tranh cho quyền bình đẳng của các dân tộc.","doc":11}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","William J. Duiker, Ho Chi Minh: A Life, Hyperion, New York, 2000","Văn Nghiệp Chúc, “Bài 3: Bác Hồ ở Boston”, báo Nhân Dân điện tử, 13/9/2015, https://nhandan.vn/bai-3-bac-ho-o-boston-post242486.html","Hồ Chí Minh Toàn tập, tập 1, NXB Chính trị quốc gia (bài “Hành hình kiểu Linsơ”, 1924)","Cục Công viên Quốc gia Hoa Kỳ (National Park Service) – tư liệu về tượng Nữ thần Tự do, đảo Ellis","Kenneth T. Jackson (chủ biên), The Encyclopedia of New York City, Yale University Press"],"doc":[{"t":"New York 1912: thành phố chọc trời, cửa ngõ người nhập cư và khu Harlem đang thành hình. Dấu vết giấy tờ hiếm hoi nhất về chặng Mỹ của Nguyễn Tất Thành là một con dấu bưu điện New York. Thành phố ấy vừa khoe những tòa nhà cao nhất thế giới, vừa đón hàng triệu người nhập cư nghèo, lại vừa chứng kiến người Mỹ gốc Phi dồn về một khu phố phía bắc Manhattan tên là Harlem. Đi qua New York năm 1912 là đi qua cả ánh sáng lẫn bóng tối của nước Mỹ, những điều người thanh niên châu Á ấy sẽ còn nhắc lại trong nhiều trang viết về sau."},{"t":"Một con dấu bưu điện. Giữa tháng 12/1912, ở New York, một người thanh niên Việt Nam gửi đi một lá thư cho các quan chức thuộc địa Pháp. Lá thư đề ngày 15/12/1912 và mang con dấu bưu điện New York. Ngày nay, nó là bằng chứng giấy tờ gần như duy nhất xác nhận Nguyễn Tất Thành đã có mặt trên đất Mỹ (xem chuyên đề Lá thư đóng dấu bưu điện New York). Ngoài dấu vết ấy, những gì ta biết về quãng thời gian Người ở thành phố này đều đến từ lời kể về sau. Vì vậy, bảng trưng bày này không kể lại những sự việc chưa được xác nhận. Nó giới thiệu chính thành phố mà người thanh niên đã đặt chân tới: New York của năm 1912. Đó là thành phố của những bến cảng, những tòa nhà chọc trời, những khu nhà chật chội của người nhập cư, và khu Harlem đang dần trở thành trung tâm của người Mỹ gốc Phi. Hiểu thành phố ấy, người xem sẽ hiểu vì sao những gì Người thấy ở nước Mỹ lại để lại dấu ấn sâu đậm đến vậy trong tư tưởng và ngòi bút của Người."},{"t":"Thành phố lớn nhất nước Mỹ. Năm 1912, New York là thành phố lớn nhất nước Mỹ và là một trong những đô thị lớn nhất thế giới. Cuộc điều tra dân số năm 1910 ghi nhận thành phố có gần 4,8 triệu người. Chỉ mười bốn năm trước đó, ngày 1/1/1898, năm khu vực là Manhattan, Brooklyn, Bronx, Queens và Staten Island mới hợp nhất thành thành phố New York ngày nay. Cầu Brooklyn, khánh thành năm 1883, nối Manhattan với Brooklyn qua sông East. Từ năm 1904, những chuyến tàu điện ngầm đầu tiên đã chạy dưới lòng Manhattan. Thành phố lớn lên với tốc độ chóng mặt. Các bến cảng dọc sông Hudson và sông East tấp nập tàu buôn, tàu khách từ châu Âu, châu Mỹ Latinh và châu Á. Nhà máy, xưởng may, kho hàng mọc lên khắp nơi, cần hàng vạn người làm thuê. Trong lá thư ngày 15/12/1912, Nguyễn Tất Thành khai nghề nghiệp của mình là thủy thủ. Với một người đi biển như thế, New York là nơi có thể tìm việc trên tàu, ở bến cảng, trong nhà hàng hay trong những gia đình khá giả. Thành phố ấy cũng là nơi hội tụ gần như đủ mọi dân tộc trên thế giới."},{"t":"Bạn có biết? Khi Người ở New York, tòa nhà Woolworth ở khu hạ Manhattan đang được hoàn thiện. Tối 24/4/1913, Tổng thống Woodrow Wilson bấm nút từ Nhà Trắng ở Washington để thắp sáng tòa nhà trong lễ khánh thành. Cao 241 mét, Woolworth giữ danh hiệu tòa nhà cao nhất thế giới cho đến năm 1930."},{"t":"Cửa ngõ của người nhập cư. New York là cửa ngõ chính của làn sóng nhập cư lớn nhất trong lịch sử nước Mỹ. Từ ngày 1/1/1892, trạm nhập cư trên đảo Ellis ở cảng New York bắt đầu hoạt động. Năm cao điểm 1907, hơn một triệu người nhập cư đã đến nước Mỹ, phần lớn qua cảng này. Họ đến từ Ý, Ireland, Đức, Ba Lan, Nga và nhiều vùng khác của châu Âu, mang theo vài bọc hành lý và hy vọng đổi đời. Tàu chở họ vào cảng đều đi ngang tượng Nữ thần Tự do, món quà nhân dân Pháp tặng nhân dân Mỹ, khánh thành ngày 28/10/1886. Nhưng cuộc sống ở vùng đất hứa không dễ dàng. Phần đông người nhập cư dồn vào những khu nhà thuê chật chội ở khu Lower East Side của Manhattan, nhiều gia đình ở chung trong những căn phòng thiếu ánh sáng, thiếu nước sạch. Họ làm việc nhiều giờ trong các xưởng may, công trường, bến cảng với đồng lương ít ỏi. Ngọn đuốc của Nữ thần Tự do và những khu nhà ổ chuột chỉ cách nhau vài cây số, một hình ảnh tương phản mà người thanh niên thuộc địa, vốn quen quan sát đời sống người lao động, khó có thể bỏ qua."},{"t":"Brooklyn: làm thuê trong một gia đình giàu có. Theo những lời kể được nhiều tư liệu Việt Nam dẫn lại, ở New York có một thời gian ngắn Người làm người giúp việc cho một gia đình giàu có ở Brooklyn. Báo Nhân Dân năm 2015, khi giới thiệu chặng đường của Người ở nước Mỹ, cũng nhắc tới công việc này trước khi Người đến Boston. Cũng như câu chuyện ở Parker House, chi tiết này chưa có văn bản độc lập từ thời ấy xác nhận, nên cần được hiểu là lời kể. Nếu đúng như vậy, công việc ấy hoàn toàn phù hợp với thời đại. Đầu thế kỷ XX, giúp việc trong gia đình là một trong những nghề phổ biến nhất của người nhập cư mới đến các thành phố lớn nước Mỹ. Brooklyn khi ấy có nhiều khu nhà của các gia đình trung lưu và khá giả, cần người nấu ăn, dọn dẹp, trông nom nhà cửa. Làm việc trong một gia đình Mỹ, người thanh niên có dịp học tiếng Anh hằng ngày, quan sát tận mắt nếp sống của tầng lớp có của. Đó cũng là một cách để Người hiểu khoảng cách giữa những người chủ và những người làm thuê, trong một đất nước tự hào là mảnh đất của cơ hội."},{"t":"Harlem: từ làng Hà Lan đến khu phố của người da đen. Harlem nằm ở phía bắc đảo Manhattan. Thế kỷ XVII, đây là một làng nông nghiệp của những người định cư Hà Lan, về sau trở thành khu ngoại ô yên tĩnh của người da trắng khá giả. Cuối thế kỷ XIX, khi đường sắt trên cao nối Harlem với trung tâm Manhattan, các nhà đầu tư đổ xô xây những dãy nhà cho thuê, đón đợi một làn sóng cư dân mới. Nhưng họ xây quá nhiều. Khoảng năm 1904 – 1905, thị trường nhà đất đổ vỡ, nhiều căn hộ bỏ trống. Đúng lúc ấy, năm 1904, nhà kinh doanh bất động sản người Mỹ gốc Phi Philip A. Payton Jr. lập Công ty Bất động sản người Mỹ gốc Phi. Ông thuê lại những tòa nhà bỏ trống để cho các gia đình da đen thuê. Trước đó, người da đen ở New York sống dồn trong những khu nghèo ở giữa Manhattan, thường xuyên bị kỳ thị, có lúc bị tấn công. Harlem mở ra cho họ những căn hộ tử tế hơn. Từ đó, người Mỹ gốc Phi chuyển đến ngày một đông. Năm 1912, khu Harlem của người da đen đang thành hình, còn đang lan dần qua từng dãy phố."},{"t":"Bạn có biết? Tên Harlem có gốc từ tiếng Hà Lan. Năm 1658, Peter Stuyvesant, thống đốc thuộc địa Tân Hà Lan, lập ở đây một làng mới và đặt tên là Nieuw Haarlem, theo tên thành phố Haarlem ở Hà Lan. Khi người Anh chiếm thuộc địa năm 1664, cái tên ấy vẫn được giữ lại."},{"t":"Tiếng nói đòi quyền bình đẳng. Nước Mỹ năm 1912 đã bãi bỏ chế độ nô lệ gần nửa thế kỷ, nhưng người da đen vẫn chưa được bình đẳng. Ở các bang miền Nam, những đạo luật phân biệt chủng tộc chia tách trường học, toa tàu, nhà hàng, và gạt họ khỏi lá phiếu. Nạn hành hình không qua xét xử vẫn diễn ra (xem chuyên đề Từ Harlem đến bài báo “Hành hình kiểu Linsơ”). Ở miền Bắc, họ bị phân biệt trong việc làm và nhà ở. Chính vì thế, nhiều người rời miền Nam lên các thành phố phía Bắc, và New York là một trong những điểm đến lớn nhất. New York cũng là nơi tiếng nói đòi quyền bình đẳng vang lên mạnh mẽ. Năm 1909, Hội Quốc gia vì sự tiến bộ của người da màu, viết tắt là NAACP, được thành lập tại thành phố này. Từ tháng 11/1910, hội phát hành tạp chí The Crisis do nhà sử học, nhà xã hội học W. E. B. Du Bois làm chủ bút. Tạp chí lên tiếng tố cáo nạn hành hình, đòi quyền công dân cho người da đen. Những năm Người có mặt ở New York, đó là những cuộc tranh luận nóng bỏng của đời sống thành phố."},{"t":"Người khách lạ ở Harlem. Theo một số nhà viết tiểu sử, trong thời gian ở New York, Người có thể đã sống một thời gian ở Harlem, hoặc ít nhất đã đến đây để tìm hiểu đời sống của người da đen. Các tác giả ấy đều dùng chữ “có thể”, vì chi tiết này đến từ lời kể chứ không phải từ văn bản đương thời. Bảo tàng giữ đúng sự thận trọng ấy. Điều chắc chắn hơn nằm ở những trang viết của Người mười một năm sau. Năm 1924, Nguyễn Ái Quốc viết bài “Hành hình kiểu Linsơ” và bài về tổ chức Ku Klux Klan, tố cáo tội ác phân biệt chủng tộc ở Mỹ bằng những chi tiết cụ thể, day dứt. Người không nhìn thân phận người da đen như chuyện riêng của nước Mỹ. Người đặt nó bên cạnh thân phận người dân các xứ thuộc địa, những người cùng bị coi là thấp kém và cùng bị tước quyền con người. Dù Người có ở Harlem hay không, những dãy phố nơi người Mỹ gốc Phi đang tụ hội năm 1912 là hình ảnh rõ nhất cho điều Người sẽ viết. Ngay giữa một nước cộng hòa, vẫn có những con người đang đòi quyền bình đẳng mà bản Tuyên ngôn Độc lập của chính nước ấy đã long trọng hứa hẹn."},{"t":"Một người châu Á ở New York. Người thanh niên Việt Nam ở New York năm 1912 cũng thuộc một nhóm người chịu sự kỳ thị: người châu Á. Năm 1882, Quốc hội Mỹ thông qua Đạo luật Loại trừ người Hoa, cấm lao động người Hoa nhập cư. Đạo luật được gia hạn năm 1892, rồi năm 1902 được kéo dài không thời hạn, mãi đến năm 1943 mới bị bãi bỏ. Đạo luật này thường được coi là đạo luật đầu tiên của nước Mỹ cấm nhập cư đối với người lao động thuộc một dân tộc cụ thể. Ở khu hạ Manhattan, quanh phố Mott, khu phố người Hoa đã hình thành từ cuối thế kỷ XIX. Người lao động châu Á thường chỉ tìm được việc trong các tiệm giặt là, nhà hàng, bếp ăn hay làm người giúp việc. Không có tư liệu nào cho biết Người từng gặp khó khăn cụ thể vì màu da ở New York. Nhưng sống giữa thành phố ấy, một người châu Á hẳn nhận ra rằng những lời tuyên bố về tự do và bình đẳng không đến với mọi người như nhau. Nhận thức ấy nối liền trải nghiệm của Người ở nước Mỹ với những điều Người đã thấy ở các thuộc địa châu Phi và ở chính quê hương mình."},{"t":"Dấu tích hôm nay. Khác với Boston, nơi khách sạn Parker House vẫn kể câu chuyện về người thợ làm bánh Việt Nam, ở New York chưa có địa chỉ cụ thể nào được xác định chắc chắn gắn với những ngày Người sống ở đây. Lá thư đóng dấu bưu điện New York vẫn nằm trong hồ sơ của chính quyền thuộc địa Pháp, như một dấu mốc nhỏ nhưng chắc chắn. Tuy vậy, New York vẫn giữ nhiều chứng tích của thời đại Người đi qua. Tượng Nữ thần Tự do vẫn đứng ở cửa cảng. Trạm nhập cư trên đảo Ellis từ năm 1990 đã trở thành bảo tàng về lịch sử nhập cư. Tòa nhà Woolworth vẫn đứng ở khu hạ Manhattan. Ở Harlem, Trung tâm Nghiên cứu Văn hóa Da đen Schomburg, thuộc Thư viện Công cộng New York, lưu giữ một trong những kho tư liệu lớn nhất về lịch sử người Mỹ gốc Phi. Trong không gian 3D của bảo tàng, góc New York và Harlem được dựng như một lời nhắc: người thanh niên ấy không chỉ đi qua những tòa nhà chọc trời. Người còn nhìn thấy những con người ở tầng thấp nhất của xã hội Mỹ, và mang hình ảnh của họ theo suốt con đường đấu tranh cho quyền bình đẳng của các dân tộc."}],"so_chu":2129}],"do_vat":[{"id":"table@1.4,-9.4","x":1.4,"y":0.1,"z":-9.4,"loai":"table","ten":"Bàn nhồi bột","tieu_de":"Chiếc bàn của người thợ phụ","text":"Chiếc bàn gỗ dài, mặt bàn phủ lớp bột trắng, dựng trong gian bếp tái hiện là đồ vật minh họa: nơi bột mì được nhào, cán, chia thành từng phần rồi nặn thành hình bánh trước khi đưa vào lò nướng. Đây là công cụ quen thuộc trong bất cứ gian bếp bánh nào ở các khách sạn lớn phương Tây đầu thế kỷ XX, nơi người thợ phụ bếp phải đứng hàng giờ liền bên bàn để kịp mẻ bánh phục vụ khách vào mỗi buổi sáng.\n\nCâu chuyện gắn với chiếc bàn này thuộc về một trong những giai đoạn ít tư liệu nhất trong cuộc đời hoạt động của Nguyễn Tất Thành: mùa đông năm 1912 – 1913, tại thành phố Boston, bang Massachusetts, Hoa Kỳ. Theo lời kể về sau và một tấm bưu thiếp Người gửi cho nhà chí sĩ Phan Châu Trinh, Người từng làm phụ bếp bánh tại khách sạn Parker House — khách sạn khai trương từ năm 1855 do ông Harvey D. Parker sáng lập, được xem là khách sạn còn hoạt động liên tục lâu đời nhất nước Mỹ.\n\nCác nhà nghiên cứu khi đối chiếu với hồ sơ nhân sự của khách sạn không tìm thấy tên Người trong đó; điều này không có nghĩa câu chuyện là bịa đặt, mà chỉ có nghĩa chưa có văn bản độc lập nào xác nhận. Đây cũng là lý do vì sao giai đoạn nước Mỹ trong hành trình của Người thường được trình bày một cách thận trọng, tách bạch rõ giữa điều đã có bằng chứng và điều mới chỉ là lời kể. Nhưng câu chuyện về người thợ phụ bếp bánh ở Boston lại khớp với cả một chuỗi năm tháng: từ người phụ bếp trên tàu Amiral Latouche-Tréville rời Sài Gòn giữa năm 1911, qua Marseille, Le Havre, rồi vượt Đại Tây Dương sang Mỹ cuối năm 1912, đến khi tiếp tục làm nhiều nghề chân tay tại nước Anh đầu năm 1913 — một chuỗi năm tháng mà Người luôn sống bằng chính sức lao động của mình để có thể vừa đi, vừa học, vừa quan sát thế giới.\n\nĐứng bên chiếc bàn nhồi bột nơi tầng hầm khách sạn, người thợ phụ hai mươi hai tuổi khi ấy hẳn còn xa lạ với thứ tiếng Anh của xứ Boston, xa lạ với khí hậu mùa đông khắc nghiệt của vùng Đông Bắc nước Mỹ, nhưng không xa lạ với công việc: đó vẫn là đôi bàn tay lao động đã từng quét dọn nhà bếp trên tàu viễn dương, nay chuyển sang nhồi bột, nướng bánh nơi đất khách. Gian bếp khách sạn lớn ở Mỹ đầu thế kỷ XX thường thuê khá đông nhân công gốc nhập cư — người Ireland, người Ý, người Hoa và cả một số người đến từ các thuộc địa châu Á — nên một thanh niên da vàng đứng lẫn trong số thợ phụ bếp không phải điều gì bất thường, và cũng vì thế càng khó để lại dấu vết riêng trong sổ sách nhân sự.\n\nSo với các trạm dừng chân trước đó — con tàu viễn dương giữa năm 1911, những cảng biển thuộc Pháp và châu Phi trên đường sang châu Âu — thì quãng thời gian ở Boston ngắn ngủi hơn nhiều, kéo dài chưa trọn một mùa đông. Nhưng chính sự ngắn ngủi ấy, cùng với việc gần như không để lại giấy tờ, khiến các nhà viết tiểu sử luôn phải thận trọng khi thuật lại, và cũng khiến mỗi chi tiết nhỏ như chiếc bàn nhồi bột này trở thành một mảnh ghép đáng quý trong bức tranh còn nhiều khoảng trống về những năm tháng nước Mỹ của Người.\n\nKhách sạn Parker House ngày nay vẫn hoạt động tại góc phố Tremont và School, giữa trung tâm Boston, dưới tên gọi Omni Parker House, dù tòa nhà hiện tại phần lớn được xây dựng lại từ năm 1927 nên không còn hoàn toàn giống kiến trúc mà người thợ phụ bếp gốc Việt từng biết đến hơn một thế kỷ trước. Chiếc bàn nhồi bột trong không gian 3D, vì thế, chỉ là hình ảnh gợi lại một công việc thầm lặng giữa một chặng đường còn nhiều khoảng trống tư liệu.","nguon":"William J. Duiker, Ho Chi Minh: A Life (2000); Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":[{"t":"Chiếc bàn của người thợ phụ. Chiếc bàn gỗ dài, mặt bàn phủ lớp bột trắng, dựng trong gian bếp tái hiện là đồ vật minh họa: nơi bột mì được nhào, cán, chia thành từng phần rồi nặn thành hình bánh trước khi đưa vào lò nướng. Đây là công cụ quen thuộc trong bất cứ gian bếp bánh nào ở các khách sạn lớn phương Tây đầu thế kỷ XX, nơi người thợ phụ bếp phải đứng hàng giờ liền bên bàn để kịp mẻ bánh phục vụ khách vào mỗi buổi sáng."},{"t":"Câu chuyện gắn với chiếc bàn này thuộc về một trong những giai đoạn ít tư liệu nhất trong cuộc đời hoạt động của Nguyễn Tất Thành: mùa đông năm 1912 – 1913, tại thành phố Boston, bang Massachusetts, Hoa Kỳ. Theo lời kể về sau và một tấm bưu thiếp Người gửi cho nhà chí sĩ Phan Châu Trinh, Người từng làm phụ bếp bánh tại khách sạn Parker House — khách sạn khai trương từ năm 1855 do ông Harvey D. Parker sáng lập, được xem là khách sạn còn hoạt động liên tục lâu đời nhất nước Mỹ."},{"t":"Các nhà nghiên cứu khi đối chiếu với hồ sơ nhân sự của khách sạn không tìm thấy tên Người trong đó; điều này không có nghĩa câu chuyện là bịa đặt, mà chỉ có nghĩa chưa có văn bản độc lập nào xác nhận. Đây cũng là lý do vì sao giai đoạn nước Mỹ trong hành trình của Người thường được trình bày một cách thận trọng, tách bạch rõ giữa điều đã có bằng chứng và điều mới chỉ là lời kể. Nhưng câu chuyện về người thợ phụ bếp bánh ở Boston lại khớp với cả một chuỗi năm tháng: từ người phụ bếp trên tàu Amiral Latouche-Tréville rời Sài Gòn giữa năm 1911, qua Marseille, Le Havre, rồi vượt Đại Tây Dương sang Mỹ cuối năm 1912, đến khi tiếp tục làm nhiều nghề chân tay tại nước Anh đầu năm 1913 — một chuỗi năm tháng mà Người luôn sống bằng chính sức lao động của mình để có thể vừa đi, vừa học, vừa quan sát thế giới."},{"t":"Đứng bên chiếc bàn nhồi bột nơi tầng hầm khách sạn, người thợ phụ hai mươi hai tuổi khi ấy hẳn còn xa lạ với thứ tiếng Anh của xứ Boston, xa lạ với khí hậu mùa đông khắc nghiệt của vùng Đông Bắc nước Mỹ, nhưng không xa lạ với công việc: đó vẫn là đôi bàn tay lao động đã từng quét dọn nhà bếp trên tàu viễn dương, nay chuyển sang nhồi bột, nướng bánh nơi đất khách. Gian bếp khách sạn lớn ở Mỹ đầu thế kỷ XX thường thuê khá đông nhân công gốc nhập cư — người Ireland, người Ý, người Hoa và cả một số người đến từ các thuộc địa châu Á — nên một thanh niên da vàng đứng lẫn trong số thợ phụ bếp không phải điều gì bất thường, và cũng vì thế càng khó để lại dấu vết riêng trong sổ sách nhân sự."},{"t":"So với các trạm dừng chân trước đó — con tàu viễn dương giữa năm 1911, những cảng biển thuộc Pháp và châu Phi trên đường sang châu Âu — thì quãng thời gian ở Boston ngắn ngủi hơn nhiều, kéo dài chưa trọn một mùa đông. Nhưng chính sự ngắn ngủi ấy, cùng với việc gần như không để lại giấy tờ, khiến các nhà viết tiểu sử luôn phải thận trọng khi thuật lại, và cũng khiến mỗi chi tiết nhỏ như chiếc bàn nhồi bột này trở thành một mảnh ghép đáng quý trong bức tranh còn nhiều khoảng trống về những năm tháng nước Mỹ của Người."},{"t":"Khách sạn Parker House ngày nay vẫn hoạt động tại góc phố Tremont và School, giữa trung tâm Boston, dưới tên gọi Omni Parker House, dù tòa nhà hiện tại phần lớn được xây dựng lại từ năm 1927 nên không còn hoàn toàn giống kiến trúc mà người thợ phụ bếp gốc Việt từng biết đến hơn một thế kỷ trước. Chiếc bàn nhồi bột trong không gian 3D, vì thế, chỉ là hình ảnh gợi lại một công việc thầm lặng giữa một chặng đường còn nhiều khoảng trống tư liệu."},{"t":"Bạn có biết? Tòa nhà khách sạn Parker House mà du khách thấy ngày nay phần lớn được xây lại từ năm 1927, khác với kiến trúc nguyên bản của thời điểm Người được cho là từng làm việc ở đây."}],"ban_co_biet":"Tòa nhà khách sạn Parker House mà du khách thấy ngày nay phần lớn được xây lại từ năm 1927, khác với kiến trúc nguyên bản của thời điểm Người được cho là từng làm việc ở đây."},{"id":"wooden_bowl_01@0.1,-9.2","x":0.15,"y":1,"z":-9.25,"loai":"wooden_bowl_01","ten":"Âu gỗ trộn bột","tieu_de":"Chiếc bánh mang tên Parker House","text":"Chiếc âu gỗ tròn, lòng sâu, đủ rộng để một người thợ dùng tay hoặc thìa gỗ khuấy đều bột, là đồ vật minh họa gợi lại công đoạn đầu tiên trong nghề làm bánh: trộn bột mì với men, nước ấm và một chút bơ, đường, để bột nghỉ cho men nở trước khi mang ra bàn nhồi, cán, chia thành từng phần.\n\nGian bếp bánh của khách sạn Parker House ở Boston, nơi chiếc âu gỗ này gợi nhớ, nổi tiếng khắp nước Mỹ với một loại bánh mì riêng: Parker House roll — ổ bánh nhỏ, mềm, được gấp đôi lại trước khi nướng, tạo thành một lớp vỏ mỏng giòn bên ngoài và ruột bông xốp bên trong. Loại bánh ra đời tại khách sạn vào thế kỷ XIX, gắn liền với danh tiếng của Parker House như một trong những khách sạn sang trọng bậc nhất vùng Đông Bắc Hoa Kỳ, và về sau trở thành món bánh quen thuộc trên bàn ăn của nhiều gia đình Mỹ, nhất là trong các dịp lễ.\n\nTheo lời kể về sau và một tấm bưu thiếp Người gửi nhà chí sĩ Phan Châu Trinh, chính trong gian bếp bánh nổi tiếng ấy, mùa đông năm 1912 – 1913, người thanh niên Việt Nam mang nhiều tên gọi khác nhau trong hành trình bôn ba — trong đó có tên Nguyễn Tất Thành — đã làm thợ phụ, tham gia vào công đoạn chuẩn bị bột cho những mẻ bánh mỗi sáng. Đây là một trong những mắt xích ít được biết đến nhất của cả hành trình: sau khi rời Sài Gòn giữa năm 1911, làm phụ bếp trên tàu biển, ghé qua nhiều cảng thuộc Pháp và châu Phi, Người tiếp tục vượt Đại Tây Dương sang Mỹ, sống một thời gian ngắn giữa Boston và New York, trước khi rời nước Mỹ đầu năm 1913 để sang nước Anh, tiếp tục chuỗi ngày làm nhiều nghề chân tay nơi đất khách.\n\nBa mươi năm sau đó, khi đứng trước quốc dân đọc bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa ngày 2 tháng 9 năm 1945, chính Người đã chọn mở đầu bằng những lời trong bản Tuyên ngôn Độc lập của Hoa Kỳ năm 1776 — như một lời nhắc rằng, ngay từ những năm tháng lặng lẽ làm thuê nơi đất khách, trong đó có những giờ đứng bên âu bột ở một gian bếp khách sạn Boston, Người đã sớm nhìn thấy trong lý tưởng của nước Mỹ trẻ cả ánh sáng lẫn những giới hạn của nó.\n\nKhách sạn Parker House, nay là Omni Parker House, vẫn hoạt động tại trung tâm Boston và vẫn phục vụ món Parker House roll trong thực đơn nhà hàng của mình — một chi tiết khiến chiếc âu gỗ trộn bột trong không gian phục dựng, dù chỉ là vật minh họa, vẫn gợi được sợi dây nối giữa một câu chuyện lịch sử và một món ăn còn tồn tại đến ngày nay.\n\nCũng chính khách sạn này, vài thập niên sau, còn là nơi làm việc của một nhân vật khác từng đấu tranh cho quyền lợi của những người bị áp bức: theo nhiều tư liệu về sau, vào thập niên 1940 có một thanh niên da đen tên Malcolm Little — người mà thế giới sau này biết đến với tên gọi Malcolm X — cũng từng làm việc tại đây. Hai số phận, cách nhau vài chục năm, cùng từng bước qua một mái nhà, trước khi mỗi người theo đuổi con đường đấu tranh riêng cho dân tộc và cộng đồng của mình. Với gian bếp bánh nhỏ ở tầng hầm Parker House, chiếc âu gỗ trộn bột vì thế không chỉ gợi lại một công việc mưu sinh, mà còn là điểm giao của nhiều câu chuyện lớn hơn về khát vọng công bằng của con người.","nguon":"Tư liệu lịch sử của khách sạn Omni Parker House, Boston; Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":[{"t":"Chiếc bánh mang tên Parker House. Chiếc âu gỗ tròn, lòng sâu, đủ rộng để một người thợ dùng tay hoặc thìa gỗ khuấy đều bột, là đồ vật minh họa gợi lại công đoạn đầu tiên trong nghề làm bánh: trộn bột mì với men, nước ấm và một chút bơ, đường, để bột nghỉ cho men nở trước khi mang ra bàn nhồi, cán, chia thành từng phần."},{"t":"Gian bếp bánh của khách sạn Parker House ở Boston, nơi chiếc âu gỗ này gợi nhớ, nổi tiếng khắp nước Mỹ với một loại bánh mì riêng: Parker House roll — ổ bánh nhỏ, mềm, được gấp đôi lại trước khi nướng, tạo thành một lớp vỏ mỏng giòn bên ngoài và ruột bông xốp bên trong. Loại bánh ra đời tại khách sạn vào thế kỷ XIX, gắn liền với danh tiếng của Parker House như một trong những khách sạn sang trọng bậc nhất vùng Đông Bắc Hoa Kỳ, và về sau trở thành món bánh quen thuộc trên bàn ăn của nhiều gia đình Mỹ, nhất là trong các dịp lễ."},{"t":"Theo lời kể về sau và một tấm bưu thiếp Người gửi nhà chí sĩ Phan Châu Trinh, chính trong gian bếp bánh nổi tiếng ấy, mùa đông năm 1912 – 1913, người thanh niên Việt Nam mang nhiều tên gọi khác nhau trong hành trình bôn ba — trong đó có tên Nguyễn Tất Thành — đã làm thợ phụ, tham gia vào công đoạn chuẩn bị bột cho những mẻ bánh mỗi sáng. Đây là một trong những mắt xích ít được biết đến nhất của cả hành trình: sau khi rời Sài Gòn giữa năm 1911, làm phụ bếp trên tàu biển, ghé qua nhiều cảng thuộc Pháp và châu Phi, Người tiếp tục vượt Đại Tây Dương sang Mỹ, sống một thời gian ngắn giữa Boston và New York, trước khi rời nước Mỹ đầu năm 1913 để sang nước Anh, tiếp tục chuỗi ngày làm nhiều nghề chân tay nơi đất khách."},{"t":"Ba mươi năm sau đó, khi đứng trước quốc dân đọc bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa ngày 2 tháng 9 năm 1945, chính Người đã chọn mở đầu bằng những lời trong bản Tuyên ngôn Độc lập của Hoa Kỳ năm 1776 — như một lời nhắc rằng, ngay từ những năm tháng lặng lẽ làm thuê nơi đất khách, trong đó có những giờ đứng bên âu bột ở một gian bếp khách sạn Boston, Người đã sớm nhìn thấy trong lý tưởng của nước Mỹ trẻ cả ánh sáng lẫn những giới hạn của nó."},{"t":"Khách sạn Parker House, nay là Omni Parker House, vẫn hoạt động tại trung tâm Boston và vẫn phục vụ món Parker House roll trong thực đơn nhà hàng của mình — một chi tiết khiến chiếc âu gỗ trộn bột trong không gian phục dựng, dù chỉ là vật minh họa, vẫn gợi được sợi dây nối giữa một câu chuyện lịch sử và một món ăn còn tồn tại đến ngày nay."},{"t":"Cũng chính khách sạn này, vài thập niên sau, còn là nơi làm việc của một nhân vật khác từng đấu tranh cho quyền lợi của những người bị áp bức: theo nhiều tư liệu về sau, vào thập niên 1940 có một thanh niên da đen tên Malcolm Little — người mà thế giới sau này biết đến với tên gọi Malcolm X — cũng từng làm việc tại đây. Hai số phận, cách nhau vài chục năm, cùng từng bước qua một mái nhà, trước khi mỗi người theo đuổi con đường đấu tranh riêng cho dân tộc và cộng đồng của mình. Với gian bếp bánh nhỏ ở tầng hầm Parker House, chiếc âu gỗ trộn bột vì thế không chỉ gợi lại một công việc mưu sinh, mà còn là điểm giao của nhiều câu chuyện lớn hơn về khát vọng công bằng của con người."},{"t":"Bạn có biết? Khách sạn Parker House, nay là Omni Parker House, vẫn hoạt động tại Boston và vẫn phục vụ món bánh Parker House roll ra đời từ thế kỷ XIX trong thực đơn của mình."}],"ban_co_biet":"Khách sạn Parker House, nay là Omni Parker House, vẫn hoạt động tại Boston và vẫn phục vụ món bánh Parker House roll ra đời từ thế kỷ XIX trong thực đơn của mình."}]};
